local config = {
  ui_story_5035_50350101_1_dialog_content = "<color=#e8d9bb>ピッ――</color>",
  ui_story_5035_50350101_2_dialog_content = "ハロハロ～！これ、もう回ってるの？",
  ui_story_5035_50350101_3_dialog_content = "よいしょっと…カメラって、やっぱりちょっと重いわ。",
  ui_story_5035_50350101_4_dialog_content = "まずは誰を撮ろうかな…\nあ、カチンコさん！",
  ui_story_5035_50350101_5_dialog_content = "えっ！？わ、わたしですか？",
  ui_story_5035_50350101_6_dialog_content = "…でも、あの…レンズキャップ、外れてないみたいですけど…",
  ui_story_5035_50350101_7_dialog_content = "え？あらら！？大失敗！",
  ui_story_5035_50350101_8_dialog_content = "本番じゃなくてよかった～。\nカチンコさん、ありがと～！",
  ui_story_5035_50350101_9_dialog_content = "と、とんでもない…",
  ui_story_5035_50350101_10_dialog_content = "それじゃ、カメラに向かって一言お願い！",
  ui_story_5035_50350101_11_dialog_content = "み、皆様、こんにちは…\nこちらの撮影現場では、映画<color=#FFB400>『ザ・スクリーム』</color>の…",
  ui_story_5035_50350101_12_dialog_content = "そんな堅苦しくなくっていいのよ？\nメイキング映像なんだから。",
  ui_story_5035_50350101_13_dialog_content = "で、でも、他にどんなことを言えばいいのか\n分かりませんし…",
  ui_story_5035_50350101_14_dialog_content = "それに、今回の<color=#FFB400>主演女優</color>はあなたですよ？\nやっぱり…わたしがカメラを回します。",
  ui_story_5035_50350101_15_dialog_content = "ダメ、まだ撮り足らないの！",
  ui_story_5035_50350101_16_dialog_content = "うう…そういうことなら…\n監督！監督、来てください！",
  ui_story_5035_50350101_17_dialog_content = "仕方ないわね～。カチンコさんったら、あがり症なんだから。\nじゃあ、カメラは――",
  ui_story_5035_50350101_18_dialog_content = "ジャジャジャジャーン！こちら――\nヨハン監督に向けましょ！",
  ui_story_5035_50350101_19_dialog_content = "ハハハ、そんなにカメラが好きなら…",
  ui_story_5035_50350101_20_dialog_content = "この後たっぷり、かついでいてもらうかな。",
  ui_story_5035_50350101_21_dialog_content = "え？どういうこと？",
  ui_story_5035_50350101_22_dialog_content = "今回は新しい試みをしようと思ってね。\n<color=#FFB400>モキュメンタリー</color>、つまり記録映画風のホラーを撮るんだ。",
  ui_story_5035_50350101_23_dialog_content = "君にはそのカメラをかついでもらって、\n一人称視点で屋敷の取材をしてもらう。",
  ui_story_5035_50350101_24_dialog_content = "どこを回り、何を話して、無意識にどんな反応をするか――\n君の言動のすべてが、真っ先にカメラに記録されるんだ。",
  ui_story_5035_50350101_25_dialog_content = "どうだ、できるかい？",
  ui_story_5035_50350101_26_dialog_content = "本当！？サイコーじゃない！",
  ui_story_5035_50350101_27_dialog_content = "ハハハ、自信は君の魅力の一つだな。\nこの映画が上映されれば、一気にスターへの道を駆け上がれるさ。",
  ui_story_5035_50350101_28_dialog_content = "監督も有名になること間違いなしね！",
  ui_story_5035_50350101_29_dialog_content = "それも悪くないがな。\nだが、私はもう「有名になる」かどうかなんて、気にする歳でもない。",
  ui_story_5035_50350101_30_dialog_content = "空前絶後のホラーを撮ることさえできれば、\nそれが私にとっての成功なんだ。",
  ui_story_5035_50350101_31_dialog_content = "あははっ、監督ったら、またその話？",
  ui_story_5035_50350101_32_dialog_content = "とにかく、カメラは安心してあたしに任せて…",
  ui_story_5035_50350101_33_dialog_content = "あっ！！",
  ui_story_5035_50350101_34_dialog_content = "だ、大丈夫ですか！？",
  ui_story_5035_50350101_35_dialog_content = "ケーブルが引っかかっただけよ。\nえへへ、大したことないわ…",
  ui_story_5035_50350101_36_dialog_content = "おい、カメラマン君。\n撮影中は君もそばに付いていてやれ。",
  ui_story_5035_50350101_37_dialog_content = "分かりました。機器の安全は守ります。",
  ui_story_5035_50350101_38_dialog_content = "それでは…『ザ・スクリーム』シーン1、カット1、テイク1、アクション！",
  ui_story_5035_50350101_39_dialog_content = "あああ、なんということでしょう、とうとう来てしまいました…\n目の前のこの豪邸こそ、ウワサに名高い幽霊屋敷です！",
  ui_story_5035_50350101_40_dialog_content = "見るからに恐ろしい気配ですが…\n今から友人たちと一緒に中に入ってみたいと思います！",
  ui_story_5035_50350101_41_dialog_content = "ああ、こういう時こそヨハン監督にも\n一緒について来てもらいたかったところですが…",
  ui_story_5035_50350101_42_dialog_content = "まったく、信じられません！監督はどこへ行ったんでしょう？\nさっそく、おかしな事が起こりました！",
  ui_story_5035_50350101_43_dialog_content = "カット！",
  ui_story_5035_50350101_44_dialog_content = "そういうわざとらしい話し方をされると、編集が難しくなる。",
  ui_story_5035_50350101_45_dialog_content = "今の部分はたぶん、全部カットだな。\n次からは普通に話してくれればいい。",
  ui_story_5035_50350101_46_dialog_content = "アハハ…分かったわ。",
  ui_story_5035_50350101_47_dialog_content = "それにしても、監督はどこに行ったの？",
  ui_story_5035_50350101_48_dialog_content = "プロデューサーは昨日から急に休みをとったって言うし、\n今度は監督までいなくなっちゃうなんて…",
  ui_story_5035_50350101_49_dialog_content = "まさか撮影を放り出して、\n自分だけサボってるわけじゃないわよね？",
  ui_story_5035_50350101_50_dialog_content = "それとも…こっそりどこかに隠れて、\nあたしたちを驚かせようって何か準備でもしてる？",
  ui_story_5035_50350101_51_dialog_content = "…カット、今のもカットだ。",
  ui_story_5035_50350101_52_dialog_content = "いいか、モキュメンタリーの売りは「真実味」なんだ。",
  ui_story_5035_50350101_53_dialog_content = "中に入った後も、\nネタばらしになるようなことは言わないでくれ。",
  ui_story_5035_50350101_54_dialog_content = "はーい…",
  ui_story_5035_50350101_55_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_5035_50350101_56_dialog_content = "この先の角がウワサで聞いた「永遠にどこへも行けない階段」ね。",
  ui_story_5035_50350101_57_dialog_content = "カメラさん、後で写真も撮ってね。\nカチンコさんは道順を記録しておいてもらえる？",
  ui_story_5035_50350101_58_dialog_content = "はい、わかりました。ただ…",
  ui_story_5035_50350101_59_dialog_content = "せ、先頭を歩くのはちょっと…",
  ui_story_5035_50350101_60_dialog_content = "それなら大丈夫よ。\nあたしが撮影しながら道を探すから！",
  ui_story_5035_50350101_61_dialog_content = "階段ちゃ～ん待っててね～♪",
  ui_story_5035_50350101_62_dialog_content = "あ、この階段、頭ぶつけるかも。",
  ui_story_5035_50350101_63_dialog_content = "あたしは大丈夫だけど、\nカチンコさんとカメラさんは頭を…",
  ui_story_5035_50350101_64_dialog_content = "<color=#e8d9bb>ゴンッ！</color>",
  ui_story_5035_50350101_65_dialog_content = "もう少し早く言ってください…",
  ui_story_5035_50350101_66_dialog_content = "まったく。度胸があるのか、にぶいだけなのか…",
  ui_story_5035_50350101_67_dialog_content = "経験から言うと、ホラー映画で真っ先に襲われるのは君みたいな人だ。",
  ui_story_5035_50350101_68_dialog_content = "ああっ――",
  ui_story_5035_50350101_69_dialog_content = "きゃああああああ！",
  ui_story_5035_50350101_70_dialog_content = "今度はどうした！？",
  ui_story_5035_50350101_71_dialog_content = "こ、この階段…",
  ui_story_5035_50350101_72_dialog_content = "行き止まりだわ！",
  ui_story_5035_50350101_73_dialog_content = "…それだけか？",
  ui_story_5035_50350101_74_dialog_content = "じゃあ、なんでカチンコが悲鳴をあげたんだ？",
  ui_story_5035_50350101_75_dialog_content = "つ、つられてつい…",
  ui_story_5035_50350101_76_dialog_content = "…",
  ui_story_5035_50350101_77_dialog_content = "エへへ、やっぱり、ウワサなんて大げさなものよね。\nスクリーンの前のみんな、今のは気にしないでね～。",
  ui_story_5035_50350101_78_dialog_content = "じゃ、次へ行きましょ！",
  ui_story_5035_50350101_79_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5035_50350101_80_dialog_content = "気のせいかしら…なんだか変な匂いがしない…？",
  ui_story_5035_50350101_81_dialog_content = "何かが…腐ってるみたいな…",
  ui_story_5035_50350101_82_dialog_content = "ほ、本当ですか？",
  ui_story_5035_50350101_83_dialog_content = "分からないわ。あたしのカン違いかも。",
  ui_story_5035_50350101_84_dialog_content = "だって、見た感じ、ヘンな人形があるだけだし…",
  ui_story_5035_50350101_85_dialog_content = "あら…！？",
  ui_story_5035_50350101_86_dialog_content = "また錯覚かしら？この人形、さっきと向きが変わってない？",
  ui_story_5035_50350101_87_dialog_content = "え！？",
  ui_story_5035_50350101_88_dialog_content = "疑っていても仕方ない。\nカメラを再生すれば、分かることじゃないか。",
  ui_story_5035_50350101_89_dialog_content = "確かに、カメラさんの言う通りね！",
  ui_story_5035_50350101_90_dialog_content = "<color=#e8d9bb>シュルルルル…</color>",
  ui_story_5035_50350101_91_dialog_content = "…おかしいわね…",
  ui_story_5035_50350101_92_dialog_content = "<color=#e8d9bb>ザザー…</color>",
  ui_story_5035_50350101_93_dialog_content = "まさか…カメラ、壊れちゃった？",
  ui_story_5035_50350101_94_dialog_content = "（弁償になったらどうしよう…）",
  ui_story_5035_50350101_95_dialog_content = "<color=#e8d9bb>ザッ――</color>",
  ui_story_5035_50350101_96_dialog_content = "（い、今の何！？）",
  ui_story_5035_50350101_97_dialog_content = "どうしたんだ？",
  ui_story_5035_50350101_98_dialog_content = "あはは、別に、何でもないわ。\n部屋から出れば…",
  ui_story_5035_50350101_99_dialog_content = "…あら？",
  ui_story_5035_50350101_100_dialog_content = "ファインダーの画面が、元に戻った？",
  ui_story_5035_50350101_101_dialog_content = "いったい何してるんだ？",
  ui_story_5035_50350101_102_dialog_content = "それは監督たちに言ってよ！",
  ui_story_5035_50350101_103_dialog_content = "「心霊スポット」で映画を撮るなんて言ってたけど、\n心霊現象なんて起こらないじゃない。",
  ui_story_5035_50350101_104_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5035_50350101_105_dialog_content = "もうイヤになっちゃうわ…\nこの地下室が最後の撮影場所よ。",
  ui_story_5035_50350101_106_dialog_content = "このままじゃ、今日の撮影が失敗になっちゃう…",
  ui_story_5035_50350101_107_dialog_content = "<color=#e8d9bb>ピチャン…ポタッ…</color>",
  ui_story_5035_50350101_108_dialog_content = "変ですね。この音…どこから聞こえてくるんでしょうか…",
  ui_story_5035_50350101_109_dialog_content = "ただの水滴の音だろう？\n考えすぎるから怖くなるんだ。",
  ui_story_5035_50350101_110_dialog_content = "え？水滴？",
  ui_story_5035_50350101_111_dialog_content = "でも、お手洗いもキッチンも…",
  ui_story_5035_50350101_112_dialog_content = "<color=#e8d9bb>ボッ――</color>",
  ui_story_5035_50350101_113_dialog_content = "ロ、ロウソクが…？",
  ui_story_5035_50350101_114_dialog_content = "<color=#e8d9bb>ガラン…ガラン…</color>",
  ui_story_5035_50350101_115_dialog_content = "<anim type=Shake><size=50>グォォ――</size></anim>",
  ui_story_5035_50350101_116_dialog_content = "<anim type=Shake><size=50>きゃああああああ！</size></anim>",
  ui_story_5035_50350101_117_dialog_content = "<anim type=Shake><size=50>た、助けて！\nあ、あたし、ま、まだ死にたく――</size></anim>",
  ui_story_5035_50350101_118_dialog_content = "<color=#e8d9bb>ガチャン――</color>",
  ui_story_5035_50350101_119_dialog_content = "<color=#e8d9bb>ザザー…</color>",
  ui_story_5035_50350101_120_dialog_content = "<color=#e8d9bb>ソラヴァン・ブリッジ</color>",
  ui_story_5035_50350101_121_dialog_content = "う～ん…",
  ui_story_5035_50350101_122_dialog_content = "え？",
  ui_story_5035_50350101_123_dialog_content = "そんな…！",
  ui_story_5035_50350101_124_dialog_content = "バイス、何を見てるの？",
  ui_story_5035_50350101_125_dialog_content = "あ、PlayerName、起きたのね。おはよう！",
  ui_story_5035_50350101_126_dialog_content = "今日の『デイリー・スクープ速報版』を読んでるの。",
  ui_story_5035_50350101_127_dialog_content = "え？こんな朝早くに、\n影ノ街の新聞なんてどこで手に入れたの？",
  ui_story_5035_50350101_128_dialog_content = "さっき配達に来たウェンディが持ってたの。\nちょっと興味があったから、置いていってもらったのよ。",
  ui_story_5035_50350101_129_dialog_content = "PlayerName、ほらほら、\nちょっとこの記事を見て！",
  ui_story_5035_50350101_130_dialog_content = "どれどれ…",
  ui_story_5035_50350101_131_dialog_content = "「尋ね人：B級ホラー映画の無名主演女優が謎の失踪」？",
  ui_story_5035_50350101_132_dialog_content = "影ノ街なら、そういう事件も起こりそうだけど…",
  ui_story_5035_50350101_133_dialog_content = "ヤラセじゃないの？",
  ui_story_5035_50350101_134_dialog_content = "その記事じゃないわよ。\nもっと上の方にある記事を見て…",
  ui_story_5035_50350101_135_dialog_content = "「ボクシング試合現場を直撃」、「人気歌手、鮮烈デビュー」…",
  ui_story_5035_50350101_136_dialog_content = "<color=#FFB400>「『アンデルセンのゴーストハウス』開業」！？</color>",
  ui_story_5035_50350101_137_dialog_content = "そう、その記事よ！",
  ui_story_5035_50350101_138_dialog_content = "宣伝文句がずいぶん大げさなのよ！\n「正真正銘の怪奇現象！絶望の叫びが響きわたる」ですって。",
  ui_story_5035_50350101_139_dialog_content = "（「アンデルセン」って、まさか…）",
  ui_story_5035_50350101_140_dialog_content = "どう？面白そうでしょ？",
  ui_story_5035_50350101_141_dialog_content = "面白そうかな…？\n宣伝文句だってずいぶん安っぽいと思うけど。",
  ui_story_5035_50350101_142_dialog_content = "えっ、PlayerName、興味ないの？\n正真正銘の怪奇現象に？",
  ui_story_5035_50350101_143_dialog_content = "（うっ、バイス、行きたがってるみたいだ…）",
  ui_story_5035_50350101_144_dialog_content = "バイス、だったら一緒に…",
  ui_story_5035_50350101_145_dialog_content = "それに、最後の1行が絶対に無視できないわ！",
  ui_story_5035_50350101_146_dialog_content = "…「開業記念、ペアでお越しの方はチケット半額」…？",
  ui_story_5035_50350101_147_dialog_content = "ふふふふ…PlayerName～。",
  ui_story_5035_50350101_148_dialog_content = "分かった、分かったよ！",
  ui_story_5035_50350201_1_dialog_content = "<color=#e8d9bb>影ノ街の外れ、「アンデルセンのゴーストハウス」</color>",
  ui_story_5035_50350201_2_dialog_content = "ずいぶんとへんぴな所にあるね…",
  ui_story_5035_50350201_3_dialog_content = "そういう場所の方が、雰囲気も出るってものでしょ！",
  ui_story_5035_50350201_4_dialog_content = "…とはいえ、このお屋敷、本当にちょっと不気味ね。",
  ui_story_5035_50350201_5_dialog_content = "正面のボロボロのドアが入口かしら？",
  ui_story_5035_50350201_6_dialog_content = "PlayerName、急いで急いで。\nチケットもちゃんと出す用意をしておいてよ。",
  ui_story_5035_50350201_7_dialog_content = "おや…？これはこれは、PlayerName様ではありませんか。",
  ui_story_5035_50350201_8_dialog_content = "やっぱり…名前を見た時から、\nそうじゃないかなって思ってたんだ。",
  ui_story_5035_50350201_9_dialog_content = "また会ったね、ミノス。\nここでも執事として働いてるの？",
  ui_story_5035_50350201_10_dialog_content = "その通りでございます。\n事前のお出迎えも出来ず申し訳ございません。",
  ui_story_5035_50350201_11_dialog_content = "それでは、PlayerName様。\nチケットを拝見いたします。",
  ui_story_5035_50350201_12_dialog_content = "相変わらずていねいだね。",
  ui_story_5035_50350201_13_dialog_content = "一緒にいるのは、友だちのバイス…",
  ui_story_5035_50350201_14_dialog_content = "こんにちは！あの、宣伝に書いてあったことって本当ですか？\n本当に本物の怪奇現象が？",
  ui_story_5035_50350201_15_dialog_content = "…で、その…怪奇現象オタクなんだ。",
  ui_story_5035_50350201_16_dialog_content = "フフフ、もちろんでございますよ。\nタネも仕掛けもない正真正銘の怪奇現象がご覧になれます。",
  ui_story_5035_50350201_17_dialog_content = "当「アンデルセンのゴーストハウス」で、\nスリルと絶叫を存分にお楽しみください。",
  ui_story_5035_50350201_18_dialog_content = "わぁ、楽しみ！",
  ui_story_5035_50350201_19_dialog_content = "あ、そうだ。このお化け屋敷って…\nもしかしてニナが新しく始めた事業？",
  ui_story_5035_50350201_20_dialog_content = "ええ、お嬢様は最近不動産業に目を向けられており、\nこの幽霊屋敷を営利目的で購入され、営業を始められたのです。",
  ui_story_5035_50350201_21_dialog_content = "何もかも理想どおりとはまいりませんでしたが…\nここがお嬢様の初めて購入された不動産でございます。",
  ui_story_5035_50350201_22_dialog_content = "ですので、私も全力を尽くし、\nお嬢様を支援する所存でおります。",
  ui_story_5035_50350201_23_dialog_content = "目の前にあるこの屋敷も、\nお嬢様と私が厳選に厳選を重ねたものです。",
  ui_story_5035_50350201_24_dialog_content = "こんな大きなお屋敷、\n買うだけでも相当な金額だったでしょ？",
  ui_story_5035_50350201_25_dialog_content = "そうでもございませんよ。\n実のところ、驚くほど安く購入しております。",
  ui_story_5035_50350201_26_dialog_content = "内装を含めても、\nそれほどの出費ではございません。",
  ui_story_5035_50350201_27_dialog_content = "そういう訳で、私もお嬢様の選択されたことに期待しているのです。\nもしかすると、本当に大きな利益を生むやも…",
  ui_story_5035_50350201_28_dialog_content = "<color=#e8d9bb>ヒュゥ…</color>",
  ui_story_5035_50350201_29_dialog_content = "…ハハハ…まだ営業を始めたばかりでございますから、\nあせらずゆっくりと、人が集まるよう努めましょう…",
  ui_story_5035_50350201_30_dialog_content = "そうでございますね、お嬢様？",
  ui_story_5035_50350201_31_dialog_content = "…",
  ui_story_5035_50350201_32_dialog_content = "おや？聞こえていらっしゃらないようですね。",
  ui_story_5035_50350201_33_dialog_content = "PlayerName、私たちもあいさつしにいきましょ。",
  ui_story_5035_50350201_34_dialog_content = "少々お待ちになって…\nお1人ずつお願いできませんこと？",
  ui_story_5035_50350201_35_dialog_content = "べっぴんのお姉さん、チケットどす！",
  ui_story_5035_50350201_36_dialog_content = "早く早く、次は私だってば！",
  ui_story_5035_50350201_37_dialog_content = "ピープ、横入りはいけませんよ！そんなに急がないでください！",
  ui_story_5035_50350201_38_dialog_content = "ありゃ、ナビゲーターはんとバイスはんやないどすか！",
  ui_story_5035_50350201_39_dialog_content = "PlayerName、ごきげんよう。お久しぶりね。",
  ui_story_5035_50350201_40_dialog_content = "アンデルセンのゴーストハウスへようこそ。\nミノスに言って、友だち割ということにしておくわ。",
  ui_story_5035_50350201_41_dialog_content = "え？ありがとうございます！",
  ui_story_5035_50350201_42_dialog_content = "やっぱりあなたと来て正解だったわ、PlayerName！",
  ui_story_5035_50350201_43_dialog_content = "バイスらしいよ…",
  ui_story_5035_50350201_44_dialog_content = "それにしても、どうして突然\nお化け屋敷なんてやろうと思ったの？",
  ui_story_5035_50350201_45_dialog_content = "何となくだけど、君はこういうの、\n苦手だったようなイメージがあるけど…",
  ui_story_5035_50350201_46_dialog_content = "まぁ！？失礼ではなくて！？",
  ui_story_5035_50350201_47_dialog_content = "<color=#e8d9bb>カチャリ――</color>",
  ui_story_5035_50350201_48_dialog_content = "チケットは拝見しましてよ。\n3名様、どうぞお持ちになって。",
  ui_story_5035_50350201_49_dialog_content = "ありがとうございます！",
  ui_story_5035_50350201_50_dialog_content = "でも…<color=#FFB400>お1人足りない</color>のではありませんこと？",
  ui_story_5035_50350201_51_dialog_content = "…え？",
  ui_story_5035_50350201_52_dialog_content = "<size=50>ええっ！？</size>",
  ui_story_5035_50350201_53_dialog_content = "お、驚かさんといてください！！",
  ui_story_5035_50350201_54_dialog_content = "ほほほ…もう1人いらっしゃれば、ペア割引が使えたという意味でございますわ。",
  ui_story_5035_50350201_55_dialog_content = "次はお友だちをたくさんお連れでいらしてくださいな。",
  ui_story_5035_50350201_56_dialog_content = "ほ、ほな…うちらは中に入りますえ！",
  ui_story_5035_50350201_57_dialog_content = "お楽しみくださいまし。",
  ui_story_5035_50350201_58_dialog_content = "PlayerName、今、見たでしょう？\n私のようにオバケを怖がる方も大勢いるからこそ…",
  ui_story_5035_50350201_59_dialog_content = "お化け屋敷を始めたのよ。",
  ui_story_5035_50350201_60_dialog_content = "まさに私らしいビジネスプランではなくて？",
  ui_story_5035_50350201_61_dialog_content = "確かに、それはその通りかも…",
  ui_story_5035_50350201_62_dialog_content = "<color=#e8d9bb>ガサッ…カサッ…</color>",
  ui_story_5035_50350201_63_dialog_content = "えっ！？",
  ui_story_5035_50350201_64_dialog_content = "今の不気味な音も、ニナさんの演出かしら…？",
  ui_story_5035_50350201_65_dialog_content = "…あれ？ニナは？",
  ui_story_5035_50350201_66_dialog_content = "わ、私も知らなくてよ！？",
  ui_story_5035_50350201_67_dialog_content = "グォォ…",
  ui_story_5035_50350201_68_dialog_content = "グア！！！",
  ui_story_5035_50350201_69_dialog_content = "暗鬼！？",
  ui_story_5035_50350201_70_dialog_content = "まったく、こんな所で人を驚かそうなんて！",
  ui_story_5035_50350202_1_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5035_50350202_2_dialog_content = "お召し物が汚れずにすんで、幸いでした。",
  ui_story_5035_50350202_3_dialog_content = "ミノス、これはあなたの落ち度ね。\nお客様と私を危険にさらすなど…",
  ui_story_5035_50350202_4_dialog_content = "申し訳ございません、お嬢様。\nつつしんで罰をお受けいたします。",
  ui_story_5035_50350202_5_dialog_content = "（ニナ、今日は何だか厳しいな）",
  ui_story_5035_50350202_6_dialog_content = "PlayerNameは初めてだから、\n道案内をしてあげて。",
  ui_story_5035_50350202_7_dialog_content = "<color=#FFB400>あの人</color>も屋敷の中で待っているの。\n価格交渉の上、契約したいそうよ。",
  ui_story_5035_50350202_8_dialog_content = "あなたも待ちきれないのではなくて？",
  ui_story_5035_50350202_9_dialog_content = "そのようなことはございません、お嬢様。\n私はただ、ゴーストハウスを軌道に乗せたい一心で…",
  ui_story_5035_50350202_10_dialog_content = "話はいいわ。\n今すぐ私の前から消えなさい。それが罰よ。",
  ui_story_5035_50350202_11_dialog_content = "…承知いたしました、お嬢様。",
  ui_story_5035_50350202_12_dialog_content = "<color=#e8d9bb>アンデルセンのゴーストハウス、1階廊下</color>",
  ui_story_5035_50350202_13_dialog_content = "ここがアンデルセンのゴーストハウス、1階でございます。",
  ui_story_5035_50350202_14_dialog_content = "屋敷の構造が複雑でして…\n偽物のドアや窓が多くございます。",
  ui_story_5035_50350202_15_dialog_content = "道順を覚えていませんと、迷ってしまうことでしょう。",
  ui_story_5035_50350202_16_dialog_content = "1階に向かわれるようでしたら、私に…",
  ui_story_5035_50350202_17_dialog_content = "…いや、失礼。\n2階へ向かわれたいようでしたら…",
  ui_story_5035_50350202_18_dialog_content = "（ミノス、心ここにあらずって感じだ）",
  ui_story_5035_50350202_19_dialog_content = "ミノス、ニナとまた何かあったの？",
  ui_story_5035_50350202_20_dialog_content = "あと、ニナが言ってた「あの人」って誰？",
  ui_story_5035_50350202_21_dialog_content = "取るに足らないことでございます。\nPlayerName様とバイス様には、お見苦しいところをお見せしました。",
  ui_story_5035_50350202_22_dialog_content = "「あの人」と申しますのは…\n2日前、お嬢様を訪ねてきた男性がおりまして。",
  ui_story_5035_50350202_23_dialog_content = "開業したばかりのこの「ゴーストハウス」を、\n長期間借り受けたいと言ってきたのです。",
  ui_story_5035_50350202_24_dialog_content = "ここで、何やら撮影をしたいとのことだそうで。",
  ui_story_5035_50350202_25_dialog_content = "そんなことがあったんですか。\nでも、開業したてでそんな訳にはいかないですよね？",
  ui_story_5035_50350202_26_dialog_content = "私もそのように考え、お断りしようとしたのですが、\nどうしてもとおっしゃって、高額な報酬まで提示されております。",
  ui_story_5035_50350202_27_dialog_content = "それで…認めちゃったの？",
  ui_story_5035_50350202_28_dialog_content = "もちろん、そのようなことはいたしません。\nただ…私は板挟みの、難しい立場でして。",
  ui_story_5035_50350202_29_dialog_content = "ミノスに難しいことがあるなんてね。",
  ui_story_5035_50350202_30_dialog_content = "ハハハ…PlayerName様、\nどうかお笑いにならないでください。",
  ui_story_5035_50350202_31_dialog_content = "表向きには、確かに私はなんでも解決できるように映るかもしれません。\nですが、私にもどうにもできないことがあるのです。",
  ui_story_5035_50350202_32_dialog_content = "ただ、この件の対処は考えてあります。",
  ui_story_5035_50350202_33_dialog_content = "ひとまず相手の条件を承諾して、臨時のプロデューサーとして\n撮影に参加し、宣伝VTRの仮製作に協力するつもりです。",
  ui_story_5035_50350202_34_dialog_content = "その間、相手がお嬢様のビジネスパートナーにふさわしいかどうか、\n判断と交渉の材料を集めるつもりでおります。",
  ui_story_5035_50350202_35_dialog_content = "そのこと、ニナさんにも話したんですか？",
  ui_story_5035_50350202_36_dialog_content = "いえ、きのうの晩に考えたことですので…",
  ui_story_5035_50350202_37_dialog_content = "…ニナさんが怒る理由も少し分かった気がします。",
  ui_story_5035_50350202_38_dialog_content = "いずれにせよ、お2人はお客様です。\n私とお嬢様のことは、どうかお気になさらず。",
  ui_story_5035_50350202_39_dialog_content = "引き続き、ゴーストハウスの案内をいたしましょう。",
  ui_story_5035_50350202_40_dialog_content = "それとも、ご自由に歩き回っていただく方がお好みでしょうか？",
  ui_story_5035_50350202_41_dialog_content = "バイス、どう思う？",
  ui_story_5035_50350202_42_dialog_content = "そうね…スタッフさんに案内してもらったら、\n驚きも面白さも減っちゃうわ…",
  ui_story_5035_50350202_43_dialog_content = "やっぱり、自分たちで自由に歩いた方がよさそう！",
  ui_story_5035_50350202_44_dialog_content = "だって、「本物の怪奇現象」が起こるんでしょ！？\nすっごく楽しみにしてるの！",
  ui_story_5035_50350202_45_dialog_content = "ハハハ…では、私はお2人の後を歩くことにいたしましょう。",
  ui_story_5035_50350202_46_dialog_content = "分かったよ。",
  ui_story_5035_50350202_47_dialog_content = "そういえば、ミノスさん。\n不思議に思ったことがあるんですが…",
  ui_story_5035_50350202_48_dialog_content = "このお屋敷、いわゆるオバケが本当にいるんですか？\n聞いた感じ、ニナさんは苦手なんでしょう？",
  ui_story_5035_50350202_49_dialog_content = "どうやってオバケをこの屋敷に連れて来たんですか？",
  ui_story_5035_50350202_50_dialog_content = "私が思うに、きっとお嬢様なりの考えがあって、\nあのような広告を出されたのでしょう。",
  ui_story_5035_50350202_51_dialog_content = "ふふふ、もちろんいるわ！\nしかも、この部屋の中に！",
  ui_story_5035_50350202_52_dialog_content = "え？誰かいるの？",
  ui_story_5035_50350202_53_dialog_content = "あたしは、真相を突き止めるために来たの！",
  ui_story_5035_50350202_54_dialog_content = "そんなに興味があるなら、\nあなたも「ミステリー探検隊」に入らない？",
  ui_story_5035_50350202_55_dialog_content = "え！？面白そう！！",
  ui_story_5035_50350202_56_dialog_content = "あ、でもちょっと待って。あなたは…？",
  ui_story_5035_50350202_57_dialog_content = "あたしはリリカ、\nあの有名な「オバケハンター」よ！",
  ui_story_5035_50350202_58_dialog_content = "…えっ！？",
  ui_story_5035_50350202_59_dialog_content = "あたしの名前…聞いたことないの？",
  ui_story_5035_50350202_60_dialog_content = "うん、全然、まったく…",
  ui_story_5035_50350202_61_dialog_content = "はぁ…",
  ui_story_5035_50350202_62_dialog_content = "ま、いいわ。改めて聞くわね。\n「ミステリー探検隊」に入らない？",
  ui_story_5035_50350202_63_dialog_content = "これは千載一遇のチャンスよ！",
  ui_story_5035_50350202_64_dialog_content = "チャンス？",
  ui_story_5035_50350202_65_dialog_content = "そうよ、このセロロが見える？",
  ui_story_5035_50350202_66_dialog_content = "その、カメラを持った…小鳥のこと？",
  ui_story_5035_50350202_67_dialog_content = "コウモリじゃないの？",
  ui_story_5035_50350202_68_dialog_content = "セロロは小鳥でも、コウモリでもないわ！\nあたしの撮影のパートナーよ！",
  ui_story_5035_50350202_69_dialog_content = "（撮影？）",
  ui_story_5035_50350202_70_dialog_content = "ミノス、君が交渉してる人のスタッフ？",
  ui_story_5035_50350202_71_dialog_content = "いえ、リリカ様は…\n今日いらしたお客様の1人だと記憶しておりますが。",
  ui_story_5035_50350202_72_dialog_content = "あたしの他にスタッフなんていないわ。\nあたし1人の企画だもの！",
  ui_story_5035_50350202_73_dialog_content = "ここでの探検をカメラに収めて、\n映像にするの！",
  ui_story_5035_50350202_74_dialog_content = "最近影ノ街のエンターテイメント業界では、\nこういう日常生活を切り取ったのがはやってるのよ。",
  ui_story_5035_50350202_75_dialog_content = "あたしの作品に出演すれば、\nあなたたちも大スターになれるかもしれないわ！",
  ui_story_5035_50350202_76_dialog_content = "あ、そうだわ。まだ名前を聞いてなかったわね。",
  ui_story_5035_50350202_77_dialog_content = "僕はPlayerNameで、こっちがバイス。\nそれから…",
  ui_story_5035_50350202_78_dialog_content = "ミノスでしょ。さっき聞こえたわ！",
  ui_story_5035_50350202_79_dialog_content = "すばらしい記憶力をおもちのようですね。",
  ui_story_5035_50350202_80_dialog_content = "当然でしょ。あたしはプロの探偵だもの。\nさあさあ、みんなカメラに向かって笑って笑って～！",
  ui_story_5035_50350202_81_dialog_content = "<color=#e8d9bb>カシャッ――</color>",
  ui_story_5035_50350202_82_dialog_content = "ふふふ…一緒に写真を撮ったからには、\nもう3人とも探検隊の隊員よ！",
  ui_story_5035_50350202_83_dialog_content = "もちろん、よろこんで隊員になるわ！",
  ui_story_5035_50350202_84_dialog_content = "お客様に喜んでいただけるのでしたら…",
  ui_story_5035_50350202_85_dialog_content = "あの…僕の意見は…？",
  ui_story_5035_50350301_1_dialog_content = "それじゃあさっそく…撮影開始よ！",
  ui_story_5035_50350301_2_dialog_content = "あ、ちょっと待って…",
  ui_story_5035_50350301_3_dialog_content = "どうかなさいましたか？",
  ui_story_5035_50350301_4_dialog_content = "ストーリーの一貫性を保つなら、\nいったん外へ出て、ゴーストハウスの入口から撮った方がいいかも。",
  ui_story_5035_50350301_5_dialog_content = "ほら、よくあるでしょ…",
  ui_story_5035_50350301_6_dialog_content = "「今日はみなさんをゴーストハウス探検の旅にお連れします」みたいな。",
  ui_story_5035_50350301_7_dialog_content = "（やっぱりああいう場面って、\nちゃんと計画的に撮ってたんだ！）",
  ui_story_5035_50350301_8_dialog_content = "入口には、この屋敷の主であるニナお嬢様がいらっしゃいます。\n右手のドアから出れば、入口へ向かえますよ。",
  ui_story_5035_50350301_9_dialog_content = "一時的に外に出られても、\n再入場できますので、安心していってらっしゃいませ。",
  ui_story_5035_50350301_10_dialog_content = "それはよかったわ。\nじゃ、ちょっと行ってくるわね！",
  ui_story_5035_50350301_11_dialog_content = "いかにもプロって感じね！",
  ui_story_5035_50350301_12_dialog_content = "完成した作品を見るのが楽しみになってきたわ。",
  ui_story_5035_50350301_13_dialog_content = "バイス、撮影とかに詳しいの？",
  ui_story_5035_50350301_14_dialog_content = "ううん…詳しいってほどじゃないわ。\nちょっとかじった程度よ。",
  ui_story_5035_50350301_15_dialog_content = "<size=30>ソラヴァンの休憩室のプロジェクターで、\nこんな感じの作品を見たことがあっただけ…</size>",
  ui_story_5035_50350301_16_dialog_content = "え！？",
  ui_story_5035_50350301_17_dialog_content = "そんなの、全然知らなかったんだけど…\n巨像に映画なんてあった？",
  ui_story_5035_50350301_18_dialog_content = "影ノ街へ来るたびに仕入れてたのよ。",
  ui_story_5035_50350301_19_dialog_content = "ほら、道端でよく安売りしてるでしょ。\nいつも帰る直前にそういう所で買ってたの。",
  ui_story_5035_50350301_20_dialog_content = "そうそう、それで最近、\n運命の監督に出会えたのよ！",
  ui_story_5035_50350301_21_dialog_content = "「運命の」監督？どういうこと…？",
  ui_story_5035_50350301_22_dialog_content = "ホラー映画が専門の監督なんだけど…\nどの作品も全部、私のツボにはまってるの！",
  ui_story_5035_50350301_23_dialog_content = "PlayerNameも興味があるなら、貸してあげるわ！\nオススメは…",
  ui_story_5035_50350301_24_dialog_content = "待って！\nお、オススメしてくれなくていいよ！",
  ui_story_5035_50350301_25_dialog_content = "へえ、ここにもホラー好きがいるのかい？",
  ui_story_5035_50350301_26_dialog_content = "そのオススメとやら、ぜひ聞かせてほしいね。",
  ui_story_5035_50350301_27_dialog_content = "これはこれは…ヨハン様、おはようございます。\nクルーの皆様も、お仕事始めですか？",
  ui_story_5035_50350301_28_dialog_content = "あ、そいつは西側の廊下に持っていってくれ。\nそうだ、ぶつけないように気を付けてくれよ。",
  ui_story_5035_50350301_29_dialog_content = "ええ、ミノスさん。申し訳ないが、\nお手伝いいただくか、大道具に道をあけてやってください。",
  ui_story_5035_50350301_30_dialog_content = "これは失礼しました。",
  ui_story_5035_50350301_31_dialog_content = "<color=#e8d9bb>ガランガラン…ガラン…</color>",
  ui_story_5035_50350301_32_dialog_content = "おや？これも…撮影道具でございますか？",
  ui_story_5035_50350301_33_dialog_content = "棺（ひつぎ）ですか？ええ、山場のシーンで使う予定なんです。\n本物みたいでしょう？",
  ui_story_5035_50350301_34_dialog_content = "確かに、ずいぶんと凝った造りのようでございますね。",
  ui_story_5035_50350301_35_dialog_content = "具体的にはどのようなシーンで？",
  ui_story_5035_50350301_36_dialog_content = "ふふふ…企業秘密ですよ。",
  ui_story_5035_50350301_37_dialog_content = "ヨハン…？撮影…え！？",
  ui_story_5035_50350301_38_dialog_content = "（それに、この格好…）",
  ui_story_5035_50350301_39_dialog_content = "ま、まさか、あなたは…",
  ui_story_5035_50350301_40_dialog_content = "<color=#FFB400>ヨハン</color>…ヨハン・マデリン監督！？",
  ui_story_5035_50350301_41_dialog_content = "ええ、そうですが、あなたは…？",
  ui_story_5035_50350301_42_dialog_content = "私、監督の大ファンなんです！！",
  ui_story_5035_50350301_43_dialog_content = "（え、まさか、この人がそうなの？）",
  ui_story_5035_50350301_44_dialog_content = "…",
  ui_story_5035_50350301_45_dialog_content = "アハハ…",
  ui_story_5035_50350301_46_dialog_content = "実に光栄ですね。\n私の新作『ホラーを止めるな！』、ぜひ楽しみにしていてください。",
  ui_story_5035_50350301_47_dialog_content = "これからも、もっとすばらしい作品を撮っていきますよ。",
  ui_story_5035_50350301_48_dialog_content = "そのためにここへ来たんですから。",
  ui_story_5035_50350301_49_dialog_content = "それはそうと、ミノスさん。\n考えはまとまりましたか？",
  ui_story_5035_50350301_50_dialog_content = "大きな商談を短期間で決断することはできません。\nですから、今回の契約はあくまで、短期のものとさせていただきます。",
  ui_story_5035_50350301_51_dialog_content = "でしたら、ひとまず今回の作品の出演者たちを紹介しましょう。",
  ui_story_5035_50350301_52_dialog_content = "こちらはゴルディ、今回の作品の主演の1人ですね。\nもう1人の秘密の登場人物と掛け合いを演じます。",
  ui_story_5035_50350301_53_dialog_content = "彼女は歌手でもあるんですよ。\nまだデビューしたばかりですが、ものすごい人気ぶりでしてね。",
  ui_story_5035_50350301_54_dialog_content = "ゴルディです。よろしくね～。",
  ui_story_5035_50350301_55_dialog_content = "あれ？もしかして、けさの影ノ街のタブロイドに載ってた…",
  ui_story_5035_50350301_56_dialog_content = "「ボクシング試合現場を直撃」、「人気歌手、鮮烈デビュー」…",
  ui_story_5035_50350301_57_dialog_content = "<color=#FFB400>「『アンデルセンのゴーストハウス』開業」！？</color>",
  ui_story_5035_50350301_58_dialog_content = "あの記事の人気歌手！？",
  ui_story_5035_50350301_59_dialog_content = "フフフ、その通りよ～！\nあ、でもあんまり大声で騒がないでね。",
  ui_story_5035_50350301_60_dialog_content = "ヨハンって超ラッキーよ。\n映画出演の契約、歌手デビューの前に決めてたから。",
  ui_story_5035_50350301_61_dialog_content = "今から契約したら、あんなギャラじゃ済まないわ！",
  ui_story_5035_50350301_62_dialog_content = "そいつは…",
  ui_story_5035_50350301_63_dialog_content = "アハハ、冗談よ！\nなんといっても、まだ新人だしね。",
  ui_story_5035_50350301_64_dialog_content = "これがデビューしてから初めての映画作品だし、\nいつも以上にがんばっちゃうわ。",
  ui_story_5035_50350301_65_dialog_content = "監督のことは、これからも私と「幸運の弾丸」が守ってあげる！",
  ui_story_5035_50350301_66_dialog_content = "ハハ、それは楽しみだ。",
  ui_story_5035_50350301_67_dialog_content = "おっと…もう一人忘れてた。\nこっちはサディ。脇役です。",
  ui_story_5035_50350301_68_dialog_content = "…",
  ui_story_5035_50350301_69_dialog_content = "どういう意味？\nあたしは紹介する価値ナシってコト？",
  ui_story_5035_50350301_70_dialog_content = "まあ、いいよ。\nあたしは雇われ者だし、ご機嫌とりは必要なし。",
  ui_story_5035_50350301_71_dialog_content = "あたしは義賊、「サディ・666」。",
  ui_story_5035_50350301_72_dialog_content = "サディって呼んでくれればいいよ。",
  ui_story_5035_50350301_73_dialog_content = "映画に出るのも、義賊の活動のうちなの？",
  ui_story_5035_50350301_74_dialog_content = "いや？景気がよくない時は、\nこだわらないで、いろんな仕事を受けてるんだ。",
  ui_story_5035_50350301_75_dialog_content = "ま、何をしてようと、\n義賊のプライドは失くさないから！",
  ui_story_5035_50350301_76_dialog_content = "そういうあんたたちは？エキストラ？",
  ui_story_5035_50350301_77_dialog_content = "違うわ、私たちはただの客よ。",
  ui_story_5035_50350301_78_dialog_content = "正確に言うと、<color=#FFB400>「本物の怪奇現象」</color>を体験しにきたの！",
  ui_story_5035_50350301_79_dialog_content = "「本物の怪奇現象」？",
  ui_story_5035_50350301_80_dialog_content = "まさか、この世に本物のオバケと怪奇現象が存在するってコト…？",
  ui_story_5035_50350301_81_dialog_content = "そうよ、私はずっとそう信じてるの！",
  ui_story_5035_50350301_82_dialog_content = "この…「アンデルセンのゴーストハウス」に？",
  ui_story_5035_50350301_83_dialog_content = "そうだって、ミノスさんが言ってたわ！",
  ui_story_5035_50350301_84_dialog_content = "ウフフ、怖いなら、守ってあげるわ。\n私は怖くないもの！",
  ui_story_5035_50350301_85_dialog_content = "しょーもな…",
  ui_story_5035_50350301_86_dialog_content = "えっ！？",
  ui_story_5035_50350301_87_dialog_content = "そんなの客寄せのウソに決まってるじゃん。\nあ、あたしは信じないよ。",
  ui_story_5035_50350301_88_dialog_content = "今、動揺してなかった…？",
  ui_story_5035_50350301_89_dialog_content = "フフフ、実に正直なお人柄でございますね。",
  ui_story_5035_50350301_90_dialog_content = "ミノスさん、そろそろ決めていただけますかね。\nロケハンを始めたいんですが。",
  ui_story_5035_50350301_91_dialog_content = "でしたら、ご自由にどうぞ。",
  ui_story_5035_50350301_92_dialog_content = "どーも。ゴルディ、サディ、行くぞ。",
  ui_story_5035_50350301_93_dialog_content = "…サディ？",
  ui_story_5035_50350301_94_dialog_content = "落とし物しちゃったから、探してくる。",
  ui_story_5035_50350301_95_dialog_content = "そうか？まぁ、君の出番はとうぶん先だ。",
  ui_story_5035_50350301_96_dialog_content = "探し物が見つかったら、ミノスさんと一緒に合流してくれ。",
  ui_story_5035_50350301_97_dialog_content = "ええ、お任せください。",
  ui_story_5035_50350301_98_dialog_content = "じゃあ、僕たちはここでリリカを待とう。\n待ってる間にサディの手伝いもできるし。",
  ui_story_5035_50350301_99_dialog_content = "そうですね。そろそろお戻りになる頃合いでしょう。",
  ui_story_5035_50350301_100_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ…</color>",
  ui_story_5035_50350301_101_dialog_content = "あ、足音だわ！",
  ui_story_5035_50350301_102_dialog_content = "リリカ、こっちよ！",
  ui_story_5035_50350301_103_dialog_content = "…？",
  ui_story_5035_50350301_104_dialog_content = "『…誰か呼んだか？』",
  ui_story_5035_50350301_105_dialog_content = "な、何か言ってる！？",
  ui_story_5035_50350301_106_dialog_content = "暗鬼も道に迷うのでしょうか…？",
  ui_story_5035_50350301_107_dialog_content = "2人とも、気にするところを間違えてるよ！\n急いで…",
  ui_story_5035_50350301_108_dialog_content = "早く、追い払わなきゃ！",
  ui_story_5035_50350302_1_dialog_content = "どうして暗鬼が中に…？",
  ui_story_5035_50350302_2_dialog_content = "開業前、お嬢様と共に\nすべての部屋の安全を確かめたのですが…",
  ui_story_5035_50350302_3_dialog_content = "複雑な構造の屋敷ですから、\nどこか侵入口を発見できていないのかも…",
  ui_story_5035_50350302_4_dialog_content = "（入口のお嬢様がご無事だといいのですが…）",
  ui_story_5035_50350302_5_dialog_content = "皆様、おケガはございませんか？",
  ui_story_5035_50350302_6_dialog_content = "暗鬼ぐらい、軽くぶっ飛ばせるよ。",
  ui_story_5035_50350302_7_dialog_content = "そういえば、サディ。\n何を落としたの？",
  ui_story_5035_50350302_8_dialog_content = "ああ、あれはね…",
  ui_story_5035_50350302_9_dialog_content = "何も。監督にウソついただけ。",
  ui_story_5035_50350302_10_dialog_content = "なんてったって、あたしは義賊だよ。\nモノを失くす側じゃない。",
  ui_story_5035_50350302_11_dialog_content = "あの人とロケハンなんて面倒でしょ。\nいちいち説教くさいし。",
  ui_story_5035_50350302_12_dialog_content = "そ、そうなの？",
  ui_story_5035_50350302_13_dialog_content = "それに、さっき話してる間に、\nロケハンの予定表を「借りといた」から。",
  ui_story_5035_50350302_14_dialog_content = "（さらっと言ってるけど、\nそれ盗んでるよね！）",
  ui_story_5035_50350302_15_dialog_content = "どこに行くつもりなのか、興味があったんだけど…\nこの表の見方、よく分かんなくてさ。",
  ui_story_5035_50350302_16_dialog_content = "だから、こっちに残ったの。",
  ui_story_5035_50350302_17_dialog_content = "悪いけど、なんて書いてあるか読んでくれる？",
  ui_story_5035_50350302_18_dialog_content = "フフフ…分かったわ！",
  ui_story_5035_50350302_19_dialog_content = "あなたも「ミステリー探検隊」に入りたいのね！？",
  ui_story_5035_50350302_20_dialog_content = "なななな何言ってんの！？",
  ui_story_5035_50350302_21_dialog_content = "そ、そんなわけないでしょ！\n悪ふざけなら好きにして、でもデタラメは言わないで！",
  ui_story_5035_50350302_22_dialog_content = "<anim type=Shake><size=45>一人前</size>の<size=45>義賊</size>の<size=30>あたし</size>、\n<size=45>インチキ</size>なんかに<size=45>ダマされない</size>♪</anim>",
  ui_story_5035_50350302_23_dialog_content = "<anim type=Shake><size=50>あたし</size>の<size=45>目的</size>、\n<size=30>屋敷</size>の<size=45>探索</size>♪</anim>",
  ui_story_5035_50350302_24_dialog_content = "<anim type=Shake><size=45>一人前</size>の<size=30>義賊</size>のあたし、\n<size=45>白髪</size>の<size=45>ワナ</size>にはハマらない♪</anim>",
  ui_story_5035_50350302_25_dialog_content = "（ムキになってるわね…）",
  ui_story_5035_50350302_26_dialog_content = "そう？だったら、\nまずは撮影予定の場所がどこなのか見てみましょ！",
  ui_story_5035_50350302_27_dialog_content = "じゃ、コレ、お願い。",
  ui_story_5035_50350302_28_dialog_content = "どれどれ…全部で3か所の予定みたいね…",
  ui_story_5035_50350302_29_dialog_content = "<color=#FFB400>1階寝室</color>、<color=#FFB400>2階陳列室</color>、\nそれから<color=#FFB400>地下室</color>。",
  ui_story_5035_50350302_30_dialog_content = "なるほど、確かによさそうな場所です。",
  ui_story_5035_50350302_31_dialog_content = "では、その3か所を1つずつ見に行くことにいたしましょう。",
  ui_story_5035_50350302_32_dialog_content = "見に行くって？何を見に行くの？",
  ui_story_5035_50350302_33_dialog_content = "アハハ！「ミステリー探検隊」、もう動きだしたのね？",
  ui_story_5035_50350302_34_dialog_content = "イントロは撮ってきたわ。こっちはどんな調子？",
  ui_story_5035_50350302_35_dialog_content = "あら、おかえりなさい！",
  ui_story_5035_50350302_36_dialog_content = "紹介するわ。新しい隊員のサディよ！",
  ui_story_5035_50350302_37_dialog_content = "あたしは隊員じゃないって…",
  ui_story_5035_50350302_38_dialog_content = "こんにちは、サディ！あたしはリリカ。\n撮影とミステリー、それからシーフードが大好きよ。",
  ui_story_5035_50350302_39_dialog_content = "だから、隊員じゃない…",
  ui_story_5035_50350302_40_dialog_content = "さあ、カメラに向かって笑って笑って～！\n一緒にオバケを探しましょ！",
  ui_story_5035_50350302_41_dialog_content = "だから、隊員じゃ…\n…もう、わかったよ。ヨロシク。",
  ui_story_5035_50350302_42_dialog_content = "よ～し！",
  ui_story_5035_50350302_43_dialog_content = "ミステリー探検隊、全員そろったわね！",
  ui_story_5035_50350302_44_dialog_content = "それでそれで？行く先のあてがあるみたいね？",
  ui_story_5035_50350302_45_dialog_content = "そうだね、サディが撮影現場の予定表を手に入れてるから、\nそれに沿って、見て回ろうと思うんだ。",
  ui_story_5035_50350302_46_dialog_content = "え、ロケハン表がもうあるなんて、超ラッキー！",
  ui_story_5035_50350302_47_dialog_content = "サディ隊員、大てがらよ！\nさっそくあたしの映画の撮影に貢献してくれたわね！",
  ui_story_5035_50350302_48_dialog_content = "ちゃんと制作協力として大きく名前を載せてあげるわ！",
  ui_story_5035_50350302_49_dialog_content = "いらないよ…",
  ui_story_5035_50350302_50_dialog_content = "あ、あとエンドロールとポスターにも載せよっと！",
  ui_story_5035_50350302_51_dialog_content = "だから、いいって…",
  ui_story_5035_50350302_52_dialog_content = "そうそう、「スペシャルサンクス」にも載せないと！\nあとビデオのパッケージにも…",
  ui_story_5035_50350302_53_dialog_content = "……",
  ui_story_5035_50350302_54_dialog_content = "もたもたしてられないわ、\nさあ、最初の場所に向かいましょ！",
  ui_story_5035_50350302_55_dialog_content = "オッケー！目的地は――1階の寝室ね！",
  ui_story_5035_50350302_56_dialog_content = "あたしの『ゴーストハウス』――撮影開始よ！\nみんな、カメラの前で思いっきり叫んでね～！",
  ui_story_5035_50350401_1_dialog_content = "<color=#e8d9bb>アンデルセンのゴーストハウス、1階廊下</color>",
  ui_story_5035_50350401_2_dialog_content = "（曲がり角ばかりで、なんだか目まいがしてきた…）",
  ui_story_5035_50350401_3_dialog_content = "皆様、もう少しの辛抱です。\nこの先を2回曲がれば到着いたします。",
  ui_story_5035_50350401_4_dialog_content = "ミノスはやっぱり気がつくね…",
  ui_story_5035_50350401_5_dialog_content = "こうして見ると、このゴーストハウス、\nなかなかよくできてるね。",
  ui_story_5035_50350401_6_dialog_content = "天井にぶつかって行き止まりになる階段、クモの巣みたいな形の窓…\nお客さんもおっかなびっくりじゃないかな。",
  ui_story_5035_50350401_7_dialog_content = "いえ、実は…このお屋敷自体が、もともとそのような設計だったのです。",
  ui_story_5035_50350401_8_dialog_content = "この遊び心あふれる設計は屋敷の最初の主――\nエスター夫人の手になるものです。",
  ui_story_5035_50350401_9_dialog_content = "「エスター夫人」？誰ですか？",
  ui_story_5035_50350401_10_dialog_content = "来たわ！舞台の歴史の紹介シーンね！",
  ui_story_5035_50350401_11_dialog_content = "やっぱりそういうのがあると、\n雰囲気が盛りあがるのよね！",
  ui_story_5035_50350401_12_dialog_content = "ミノス、もう少し寄って…\nそうそう、もうちょっと、こっち。",
  ui_story_5035_50350401_13_dialog_content = "ここでよろしいですか？",
  ui_story_5035_50350401_14_dialog_content = "バッチリ！はい、始めて！",
  ui_story_5035_50350401_15_dialog_content = "コホン…この屋敷は何度も持ち主を変えておりますが、\n初代の主はエスター夫人という方だと伝わっております。",
  ui_story_5035_50350401_16_dialog_content = "エスター夫人には身寄りがなく、\nここで自身と使用人だけで暮らしていたそうです。",
  ui_story_5035_50350401_17_dialog_content = "変わった性格の方で、強い妄想に取りつかれており…",
  ui_story_5035_50350401_18_dialog_content = "毎日夕方になると、汚れた者が屋敷に潜り込み、\n命を奪いにくると心配しだしたとか…",
  ui_story_5035_50350401_19_dialog_content = "きゃあぁぁぁ！",
  ui_story_5035_50350401_20_dialog_content = "バイス、ど、どうしたの！？",
  ui_story_5035_50350401_21_dialog_content = "アハハ…何でもないわ。\n大事なところだったから、つい叫んじゃっただけよ…",
  ui_story_5035_50350401_22_dialog_content = "それから？それから？",
  ui_story_5035_50350401_23_dialog_content = "それから…",
  ui_story_5035_50350401_24_dialog_content = "夫人は全財産を投じて、\n屋敷を「迷宮」に造りかえてしまったのです。",
  ui_story_5035_50350401_25_dialog_content = "開かないドアやどこにも通じない階段などをあちこちに造り、\n毎晩寝室を変えて眠ったそうです。",
  ui_story_5035_50350401_26_dialog_content = "ベッド脇のロウソクも夜通し火をともしたままで、\n壁には夫人の震える顔の影が映っていたとか…",
  ui_story_5035_50350401_27_dialog_content = "いやああああ――――",
  ui_story_5035_50350401_28_dialog_content = "そして、もしロウソクが消えてしまうと、夫人は叫び声をあげたそうです。\n使用人たちも、その耳をつんざくような叫び声で目を覚ますほどに。",
  ui_story_5035_50350401_29_dialog_content = "結局、エスター夫人は大火事で亡くなりました。",
  ui_story_5035_50350401_30_dialog_content = "ロウソクの火が部屋に燃え移り、\nすさまじい火の手の中、夫人は必死に逃げ回りましたが…",
  ui_story_5035_50350401_31_dialog_content = "自ら造り出した「迷宮」が命取りとなってしまったのです。",
  ui_story_5035_50350401_32_dialog_content = "使用人たちはあわてて屋敷の中を探し回りましたが、\n夫人は結局、火の海と化した行き止まりの廊下で亡くなっていたそうです。",
  ui_story_5035_50350401_33_dialog_content = "伝え聞いたところによると、その後の何代かの持ち主は、\n寝ている時に使用人たちが走り回る足音を聞いたそうです。",
  ui_story_5035_50350401_34_dialog_content = "屋敷の中の片付けと清掃は済ませておりますが、\nもしかしたら私にもまだ見つけられていない場所があり、そこには使用人の…",
  ui_story_5035_50350401_35_dialog_content = "きゃあぁぁぁ！！",
  ui_story_5035_50350401_36_dialog_content = "…お話は以上でございます。",
  ui_story_5035_50350401_37_dialog_content = "カット！すばらしいわ、いい感じよ！",
  ui_story_5035_50350401_38_dialog_content = "ちょうど1階の寝室に到着いたしました。\nでは皆様、どうぞ中へ…",
  ui_story_5035_50350401_39_dialog_content = "<color=#e8d9bb>ゴン――</color>",
  ui_story_5035_50350401_40_dialog_content = "うっ…これは、大変失礼いたしました。",
  ui_story_5035_50350401_41_dialog_content = "ご覧の通り、たった今私が開けたドアも\nニセモノでございます。",
  ui_story_5035_50350401_42_dialog_content = "どうか皆様もお気をつけください。\n私のように壁にぶつからないよう…",
  ui_story_5035_50350401_43_dialog_content = "ミノス、本当に大丈夫！？",
  ui_story_5035_50350401_44_dialog_content = "本物は右隣りのこちらでございます。\nどうぞ後に続いて、中にお入りください。",
  ui_story_5035_50350401_45_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5035_50350401_46_dialog_content = "へー…",
  ui_story_5035_50350401_47_dialog_content = "あら？",
  ui_story_5035_50350401_48_dialog_content = "見た感じ…普通の寝室ね。\nボロボロだけど。",
  ui_story_5035_50350401_49_dialog_content = "この部屋の薄暗さは、\n重苦しい空気の屋内シーンを撮るにはふさわしいかと思います。",
  ui_story_5035_50350401_50_dialog_content = "サディ様、表を見せていただけますか？\nここではどのようなシーンを撮る予定なのでしょう？",
  ui_story_5035_50350401_51_dialog_content = "はい、どーぞ。",
  ui_story_5035_50350401_52_dialog_content = "ふむ、なるほど…",
  ui_story_5035_50350401_53_dialog_content = "あっ…みんな、ちょっとこれを見て！",
  ui_story_5035_50350401_54_dialog_content = "本物そっくりのテレビがあるわ！",
  ui_story_5035_50350401_55_dialog_content = "テレビの前で記念写真を撮りましょ！",
  ui_story_5035_50350401_56_dialog_content = "その受像機はゴーストハウスの演出でも、\n撮影用の小道具でもありませんね。",
  ui_story_5035_50350401_57_dialog_content = "大火事の後に残った物の1つです。",
  ui_story_5035_50350401_58_dialog_content = "（そんなもの、持ってるのは啓光ぐらいかと思ってた…）",
  ui_story_5035_50350401_59_dialog_content = "別にフツーのテレビじゃん。よくある骨董品でしょ。",
  ui_story_5035_50350401_60_dialog_content = "甘くみちゃいけないわ！\nうまく使えば、ホラー映画のいい演出に使えるんだから。",
  ui_story_5035_50350401_61_dialog_content = "たとえば…電源の入ってない黒い画面に、\n自分じゃない何かの姿が映るとか…",
  ui_story_5035_50350401_62_dialog_content = "長い髪をたらした不気味な女の人が、\n中からはい出してくるとか…",
  ui_story_5035_50350401_63_dialog_content = "とにかく、テレビと一緒に写真を撮りましょ！",
  ui_story_5035_50350401_64_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_5035_50350401_65_dialog_content = "え……?",
  ui_story_5035_50350401_66_dialog_content = "そ、そんな…ウソでしょ！？",
  ui_story_5035_50350401_67_dialog_content = "まさか、本当に…",
  ui_story_5035_50350401_68_dialog_content = "<color=#e8d9bb>ザザー…</color>",
  ui_story_5035_50350401_69_dialog_content = "…ごきげんよう…",
  ui_story_5035_50350401_70_dialog_content = "で、出たあああああああ！",
  ui_story_5035_50350401_71_dialog_content = "出たわね！オバケ登場の瞬間、逃がさないわよ！",
  ui_story_5035_50350401_72_dialog_content = "こんにちは～！あなたはゴーストハウスの役者さん？\nただの変人さん？それとも、ビデオテープの霊？",
  ui_story_5035_50350401_73_dialog_content = "（どれでも聞くことじゃないよ！）",
  ui_story_5035_50350401_74_dialog_content = "貴方は私を知らない、\nしかし私は貴方を知っている。",
  ui_story_5035_50350401_75_dialog_content = "かまわないわ！これで知り合いだもの。\nさ、カメラの向こうのみんなにあいさつして！はい、チーズ！",
  ui_story_5035_50350401_76_dialog_content = "ゲームをしましょう。",
  ui_story_5035_50350401_77_dialog_content = "いいわ、面白そう！",
  ui_story_5035_50350401_78_dialog_content = "（そんな簡単に！？）",
  ui_story_5035_50350401_79_dialog_content = "これ、どう考えても録画だよ…",
  ui_story_5035_50350401_80_dialog_content = "リリカの質問にゼンゼン答えてないし…",
  ui_story_5035_50350401_81_dialog_content = "全ての質問に答える必要はないの。",
  ui_story_5035_50350401_82_dialog_content = "！？",
  ui_story_5035_50350401_83_dialog_content = "代わりに、貴方達には3つの謎が用意されている。",
  ui_story_5035_50350401_84_dialog_content = "さあ、始めましょう。",
  ui_story_5035_50350401_85_dialog_content = "貴方たちが入ってきた瞬間、部屋には鍵がかけられた。",
  ui_story_5035_50350401_86_dialog_content = "<color=#e8d9bb>ガチャガチャ――</color>",
  ui_story_5035_50350401_87_dialog_content = "開かないわ…ウ、ウソじゃないみたい！?",
  ui_story_5035_50350401_88_dialog_content = "貴方たちにも勝ち目があるように…",
  ui_story_5035_50350401_89_dialog_content = "鍵の隠し場所のヒントをあげましょう。",
  ui_story_5035_50350401_90_dialog_content = "生きるか死ぬかは貴方次第。",
  ui_story_5035_50350401_91_dialog_content = "…ねえ、ミノス。これってどういうこと…？",
  ui_story_5035_50350401_92_dialog_content = "PlayerName様…常に冷静であることは執事の美徳でございますが、\n今は事実を申しあげるしかございません…",
  ui_story_5035_50350401_93_dialog_content = "これは私の手配したものではありません…",
  ui_story_5035_50350401_94_dialog_content = "よく聞きなさい。\n第1問…この屋敷の主は誰？",
  ui_story_5035_50350401_95_option_content = "エスター夫人",
  ui_story_5035_50350401_96_dialog_content = "まったく話にならない…",
  ui_story_5035_50350401_97_dialog_content = "いったい誰がこの屋敷に新しい命を吹き込んだと思っている？",
  ui_story_5035_50350401_98_dialog_content = "残念ながら、直接主にわびる機会はないだろう。",
  ui_story_5035_50350401_99_dialog_content = "PlayerName様、ニナお嬢様の名前をお忘れになったのですか？",
  ui_story_5035_50350401_100_option_content = "ニナ",
  ui_story_5035_50350401_101_dialog_content = "まったく話にならない…",
  ui_story_5035_50350401_102_dialog_content = "最初の主である夫人への敬意が足りないようだ。",
  ui_story_5035_50350401_103_dialog_content = "「地獄」で夫人と相まみえた時、\n敬意を伝え、わびるがいい。",
  ui_story_5035_50350401_104_dialog_content = "PlayerName様、私がエスター夫人のお話をして\nさしあげたばかりでございますが…",
  ui_story_5035_50350401_105_dialog_content = "こんなのおかしいよ、\n正解なんてどうとでも言える問題でしょ？",
  ui_story_5035_50350401_106_dialog_content = "第2問…この屋敷にはドアがいくつある？",
  ui_story_5035_50350401_107_dialog_content = "（よかった、これは正解のある問題だ…）",
  ui_story_5035_50350401_108_dialog_content = "ミノス、頼んだよ。",
  ui_story_5035_50350401_109_dialog_content = "万が一のために、屋敷の地図を持っていて幸いでした。\n確認のため、少々お時間を…",
  ui_story_5035_50350401_110_dialog_content = "そんなの、誰が知ってるって言うの？\nヘンタイマスクさんだって知らないんじゃない？",
  ui_story_5035_50350401_111_dialog_content = "…",
  ui_story_5035_50350401_112_dialog_content = "…あっ、まずい！",
  ui_story_5035_50350401_113_dialog_content = "答えられないという答え…残念、不正解。",
  ui_story_5035_50350401_114_dialog_content = "え！？そんなのズルいわ！\nあたしが答えるなんて言ってないのに！",
  ui_story_5035_50350401_115_dialog_content = "これが上映されたら、\nあなたにブーイング間違いなしよ！",
  ui_story_5035_50350401_116_dialog_content = "このままだとまずいわ。\n最後の問題も答えられなかったら…",
  ui_story_5035_50350401_117_dialog_content = "第3問…テレビの下に鍵はない。",
  ui_story_5035_50350401_118_dialog_content = "…え？それって、問題じゃないよね？",
  ui_story_5035_50350401_119_dialog_content = "PlayerName、万が一の可能性も考えて、\n調べてみましょ。",
  ui_story_5035_50350401_120_dialog_content = "それならサディに任せて…",
  ui_story_5035_50350401_121_dialog_content = "…あっ！",
  ui_story_5035_50350401_122_dialog_content = "本当に鍵があったわ…こんな簡単に見つかっていいの？",
  ui_story_5035_50350401_123_dialog_content = "あたしが取るよ…",
  ui_story_5035_50350401_124_dialog_content = "不正解。近道に通じる幻を簡単に信じてしまった。",
  ui_story_5035_50350401_125_dialog_content = "正解率ゼロ。それなら、<color=#FFB400>罰ゲーム</color>の時間。",
  ui_story_5035_50350401_126_dialog_content = "え！？",
  ui_story_5035_50350401_127_dialog_content = "こんなのメチャクチャだよ…ミノス、何か方法はないの？",
  ui_story_5035_50350401_128_dialog_content = "そうよ！隠し部屋とか、隠し扉とか、\n執事がスペアの鍵をもってるとか？",
  ui_story_5035_50350401_129_dialog_content = "今こそ次々に襲い掛かる危機から抜け出す逆転のシーンよ！",
  ui_story_5035_50350401_130_dialog_content = "<color=#e8d9bb>ドスン…ドスン…</color>",
  ui_story_5035_50350401_131_dialog_content = "何かがこの部屋に向かって来てる…",
  ui_story_5035_50350401_132_dialog_content = "簡単に申しましょう。\n私からの提案はただ1つ――",
  ui_story_5035_50350401_133_dialog_content = "グアァ～…",
  ui_story_5035_50350401_134_dialog_content = "<anim type=Shake><size=45>グォォ～！！！！</size></anim>",
  ui_story_5035_50350401_135_dialog_content = "ドアが破られます、今のうちに逃げましょう！",
  ui_story_5035_50350501_1_dialog_content = "グアァ～！",
  ui_story_5035_50350501_2_dialog_content = "あたしの出番ね！",
  ui_story_5035_50350501_3_dialog_content = "グアォオオ～！",
  ui_story_5035_50350501_4_dialog_content = "（あら、この暗鬼…ちょっとやわらかい？）",
  ui_story_5035_50350501_5_dialog_content = "（マットレスを叩いたみたいな感触…？）",
  ui_story_5035_50350501_6_dialog_content = "…ダメダメ、集中しなきゃ！",
  ui_story_5035_50350501_7_dialog_content = "セロロ、行きなさい！",
  ui_story_5035_50350501_8_dialog_content = "グォォ～！！！",
  ui_story_5035_50350501_9_dialog_content = "（まだ何もしてないのに倒れちゃった？\nこの暗鬼…戦う気が無い？）",
  ui_story_5035_50350501_10_dialog_content = "あんた、意外と強いんだね。",
  ui_story_5035_50350501_11_dialog_content = "えっ…",
  ui_story_5035_50350501_12_dialog_content = "…ふふふ、当たり前でしょ！",
  ui_story_5035_50350501_13_dialog_content = "だって、あたしは探検隊隊長だもの！",
  ui_story_5035_50350501_14_dialog_content = "さあ、こっちよ、突破口が開いたわ！\n逆転のクライマックスよ！",
  ui_story_5035_50350501_15_dialog_content = "ふふふ…このシーンの主役はあたしね！",
  ui_story_5035_50350501_16_dialog_content = "PlayerName、一気に突破しましょ！",
  ui_story_5035_50350501_17_dialog_content = "分かった！！",
  ui_story_5035_50350501_18_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5035_50350501_19_dialog_content = "あいたた…",
  ui_story_5035_50350501_20_dialog_content = "君は…！",
  ui_story_5035_50350501_21_dialog_content = "ゲームオーバー。",
  ui_story_5035_50350501_22_dialog_content = "！？",
  ui_story_5035_50350501_23_dialog_content = "（…<color=#FFB400>そういうこと</color>でしたか）",
  ui_story_5035_50350501_24_dialog_content = "ま、まさか…ビデオテープの霊！？",
  ui_story_5035_50350501_25_dialog_content = "ご、ごめんなさい！\nやっぱりヘンタイマスクは言い過ぎだったわ…",
  ui_story_5035_50350501_26_dialog_content = "し、視聴者のみなさん、見てください。\nこちらがこの屋敷に潜む「オバケ」の1人…",
  ui_story_5035_50350501_27_dialog_content = "て、手ブレしてるけど…\nこの屋敷の怪奇現象を解き明かすのがあたしの使命…",
  ui_story_5035_50350501_28_dialog_content = "おじけづいたりしないわ！",
  ui_story_5035_50350501_29_dialog_content = "い、今から…オバケに1歩近づくわ。\nみんなに、ハッキリ見せなくちゃ…",
  ui_story_5035_50350501_30_dialog_content = "も、もう1歩…",
  ui_story_5035_50350501_31_dialog_content = "…",
  ui_story_5035_50350501_32_dialog_content = "リリカ、は、早く戻って！",
  ui_story_5035_50350501_33_dialog_content = "バイス、PlayerName、あ、あああ、あたしに、\nな、なな、何かあったら、このテープを…",
  ui_story_5035_50350501_34_dialog_content = "貴方たちに…",
  ui_story_5035_50350501_35_dialog_content = "ううううう…",
  ui_story_5035_50350501_36_dialog_content = "もう、逃げ場はない。",
  ui_story_5035_50350501_37_dialog_content = "<color=#e8d9bb>ウイィ～ン…ガガガ！</color>",
  ui_story_5035_50350501_38_dialog_content = "暗鬼が…回転ノコギリを持ってる！？やっぱり…",
  ui_story_5035_50350501_39_dialog_content = "（「やっぱり」…何だろう？）",
  ui_story_5035_50350501_40_dialog_content = "では、皆様方。絶叫を響かせてあげなさい。",
  ui_story_5035_50350502_1_dialog_content = "（おかしいな。僕は「怪奇現象」なんて信じてないけど…）",
  ui_story_5035_50350502_2_dialog_content = "（この「マスクの人」が暗鬼を操ってるんだとしたら、\nきっと日蝕の一員だ）",
  ui_story_5035_50350502_3_dialog_content = "（でも、暗力がまったく感じられない…）",
  ui_story_5035_50350502_4_dialog_content = "（ということは、本当に怪奇現象？いや…）",
  ui_story_5035_50350502_5_dialog_content = "速射感知――！",
  ui_story_5035_50350502_6_dialog_content = "<color=#e8d9bb>ヒュン――</color>",
  ui_story_5035_50350502_7_dialog_content = "（避けられた！？）",
  ui_story_5035_50350502_8_dialog_content = "…もう1回！速射…",
  ui_story_5035_50350502_9_dialog_content = "まあ、待て待て！",
  ui_story_5035_50350502_10_dialog_content = "えっ？",
  ui_story_5035_50350502_11_dialog_content = "マジの戦いはここまでにしようぜ。\n労災にでもなっちゃ、たまんねえからな。",
  ui_story_5035_50350502_12_dialog_content = "そうだそうだ。",
  ui_story_5035_50350502_13_dialog_content = "お芝居はこのぐらいにしとこうぜ！",
  ui_story_5035_50350502_14_dialog_content = "…この服、暑い。",
  ui_story_5035_50350502_15_dialog_content = "コルゴン、クマ、それにペギ！？",
  ui_story_5035_50350502_16_dialog_content = "…じゃあ、あのマスクの人は…",
  ui_story_5035_50350502_17_dialog_content = "ふふふ、皆様、『ゲーム』はお楽しみいただけて？",
  ui_story_5035_50350502_18_dialog_content = "私が皆様をこの部屋から出して差しあげるわ。",
  ui_story_5035_50350502_19_dialog_content = "やっぱり、ニナだったんだね！",
  ui_story_5035_50350502_20_dialog_content = "…まったく、ビックリしたわ！",
  ui_story_5035_50350502_21_dialog_content = "ミノスさん以外、全員まんまとだまされたってこと？",
  ui_story_5035_50350502_22_dialog_content = "さっき戦いが終わりかけた時、\nいったんカメラを止めてってミノスに言われたけど…",
  ui_story_5035_50350502_23_dialog_content = "単に企業秘密だったってことね！\n何かタブーに触れると、たたりに遭うみたいな話かと思ったわ！",
  ui_story_5035_50350502_24_dialog_content = "それは誤解がございますね。\nこれはすべて、お嬢様がお一人でお考えになった演出でございます。",
  ui_story_5035_50350502_25_dialog_content = "私もまったく存じあげておりませんでした。\nお嬢様が姿を現した時にやっと気づいたのです。",
  ui_story_5035_50350502_26_dialog_content = "何しろ、声とお姿はよく存じあげておりますから。",
  ui_story_5035_50350502_27_dialog_content = "フン…",
  ui_story_5035_50350502_28_dialog_content = "（バレないように口調までがんばってたのに…）",
  ui_story_5035_50350502_29_dialog_content = "…まぁ、ミノスの言う通りでしてよ。\n今のは私がお客様のために特別にご用意した、オプション体験ですの。",
  ui_story_5035_50350502_30_dialog_content = "初回ですから、貴重なご意見をお聞かせいただきたいわ！",
  ui_story_5035_50350502_31_dialog_content = "ふーん、じゃ、あたしから。",
  ui_story_5035_50350502_32_dialog_content = "まず、テレビのことかな。\n実際はリアルタイムで話してたみたいだけど、受け答えがぎこちなかったね。",
  ui_story_5035_50350502_33_dialog_content = "うっ…覚えておきますわ。",
  ui_story_5035_50350502_34_dialog_content = "それと、問題もあんまりよくなかったかな。\nなんかバカにされてた気がするし…",
  ui_story_5035_50350502_35_dialog_content = "…あら、そうだったかしら…",
  ui_story_5035_50350502_36_dialog_content = "それから、暗鬼の着ぐるみはさすがに…",
  ui_story_5035_50350502_37_dialog_content = "ふふふ…ご説明いたしますわ！",
  ui_story_5035_50350502_38_dialog_content = "脱ぎ捨てられている暗鬼の着ぐるみ、よくご覧になって！",
  ui_story_5035_50350502_39_dialog_content = "え！？この手触りは…",
  ui_story_5035_50350502_40_dialog_content = "その通り！\n特注の逸品でしてよ。",
  ui_story_5035_50350502_41_dialog_content = "これを着ていれば、\nたいていの光力術に耐えられ、痛みも感じませんの！",
  ui_story_5035_50350502_42_dialog_content = "ま、唯一の欠点は――",
  ui_story_5035_50350502_43_dialog_content = "…中、暑い。",
  ui_story_5035_50350502_44_dialog_content = "（わざわざそんなものまで…！？）",
  ui_story_5035_50350502_45_dialog_content = "これで、一般のお客様方にも、\n暗鬼と戦う緊張感と恐怖を味わっていただけるわ！",
  ui_story_5035_50350502_46_dialog_content = "これこそ本物の、見て触れられる「怪奇現象」！",
  ui_story_5035_50350502_47_dialog_content = "光霊ならだれしも心の奥底に持っている、\n暗闇への恐怖を克服するのは難しくてよ。それに…",
  ui_story_5035_50350502_48_dialog_content = "監視カメラごしに皆様の怖がる顔を拝見するのも、\nなかなか面白かったわ。",
  ui_story_5035_50350502_49_dialog_content = "ふふふ…！",
  ui_story_5035_50350502_50_dialog_content = "（監視カメラだって安くない貴重品のはずだけど、\nこんなことに使うなんて、ぜいたくだなぁ…）",
  ui_story_5035_50350502_51_dialog_content = "（お嬢様…どうやら、おかしな趣味に\n目覚めてしまわれたようですね…）",
  ui_story_5035_50350502_52_dialog_content = "そーだったんだ。\nどっちにしても、ヨハン監督がくれる仕事よりずっと信用できそう。",
  ui_story_5035_50350502_53_dialog_content = "部屋のセットとか、中の人の募集とか、着ぐるみ作りとか…\n全部1人でやったの？",
  ui_story_5035_50350502_54_dialog_content = "けっこースゴいんだね…\n自分の仕事ができるアネキってカッコいいよね。リスペクトだよ。",
  ui_story_5035_50350502_55_dialog_content = "あ、あら、本当！？",
  ui_story_5035_50350502_56_dialog_content = "…オホン…でしたら、\nぜひアンデルセンのゴーストハウスで働かれるといいわ。",
  ui_story_5035_50350502_57_dialog_content = "それは、ゆっくり考えさせて。",
  ui_story_5035_50350502_58_dialog_content = "テキトーに受けたモノだけど、\n今の仕事もきちんと最後までやりとげたいからさ。",
  ui_story_5035_50350502_59_dialog_content = "うぅ…そういうことだったのね…",
  ui_story_5035_50350502_60_dialog_content = "「正真正銘の怪奇現象」が、\n暗鬼の着ぐるみだったなんて…",
  ui_story_5035_50350502_61_dialog_content = "バイス、どうしたの？\n探検隊の隊長として、聞かせてもらうわ！",
  ui_story_5035_50350502_62_dialog_content = "だって…新聞の広告を見た時から、\nずっと楽しみにしてたんだもの。",
  ui_story_5035_50350502_63_dialog_content = "でも、「怪奇現象」の正体…\n何だかマジックの種明かしを聞かされた時みたいな気分だわ。",
  ui_story_5035_50350502_64_dialog_content = "（…バイスの気持ち、ちょっと分かる気がする）",
  ui_story_5035_50350502_65_dialog_content = "だ、大丈夫だよ、バイス。\nまだ僕たちが行ってない場所に、そういう存在がいるかも…",
  ui_story_5035_50350502_66_dialog_content = "そんなこと、あるかしら…",
  ui_story_5035_50350502_67_dialog_content = "（自分でも何言ってるんだろうって思うけどね…）",
  ui_story_5035_50350502_68_dialog_content = "申し訳ございません、バイス様。\n私もお嬢様も、貴方のようなお客様のお気持ちに考えが至りませんでした。",
  ui_story_5035_50350502_69_dialog_content = "ごめんなさい…",
  ui_story_5035_50350502_70_dialog_content = "あ、謝らないで…\nそもそも「怪奇現象を呼び込む」なんて、できると思う方が…",
  ui_story_5035_50350502_71_dialog_content = "できるかもしれないわ！",
  ui_story_5035_50350502_72_dialog_content = "えぇっ！？",
  ui_story_5035_50350502_73_dialog_content = "オバケハンターから言わせてもらうと、\nこのお屋敷、怪奇現象が存在する可能性がまだまだあるの！",
  ui_story_5035_50350502_74_dialog_content = "でも、ニナさんとミノスさんがたった今、\nそういう演出だって…",
  ui_story_5035_50350502_75_dialog_content = "ええ、そうよ。\nでも、種明かしされたのは、2人が準備したものだけでしょ。",
  ui_story_5035_50350502_76_dialog_content = "でも、2人がいじってない場所はどう？",
  ui_story_5035_50350502_77_dialog_content = "確かに、可能性は否定できないけど…",
  ui_story_5035_50350502_78_dialog_content = "可能性がゼロじゃないってことは、\n可能性は十分ってことよ！",
  ui_story_5035_50350502_79_dialog_content = "「疑わしきは追求」！\nそれこそあたしたちミステリー探検隊の理念よ！",
  ui_story_5035_50350502_80_dialog_content = "それに、ここは1つ目の目的地にすぎないわ。\n調査を続けたら何が出てくるか、まだ分からないじゃない？",
  ui_story_5035_50350502_81_dialog_content = "確かに…そんな気がしてきたわ！",
  ui_story_5035_50350502_82_dialog_content = "（今ので納得できるの…？）",
  ui_story_5035_50350502_83_dialog_content = "そうそう、リリカの言う通り。\nあたしもロケハン終わってないし。",
  ui_story_5035_50350502_84_dialog_content = "遅くならないうちに、さっさと次行こ。",
  ui_story_5035_50350502_85_dialog_content = "そう来なくっちゃ！\nじゃあ、急いで2階の陳列室に向かいましょ。",
  ui_story_5035_50350502_86_dialog_content = "あたしの『ゴーストハウス』、撮影再開よ！",
  ui_story_5035_50350502_87_dialog_content = "そうと決まれば、引き続き私がご案内いたします。",
  ui_story_5035_50350502_88_dialog_content = "ただ、お嬢様も十分お気をつけくださいませ。\n本物の暗鬼が紛れ込んできているようですので…",
  ui_story_5035_50350502_89_dialog_content = "そんなことが？",
  ui_story_5035_50350502_90_dialog_content = "私の手落ちだわ…むろん、あなたの手落ちでもあるわね。",
  ui_story_5035_50350502_91_dialog_content = "だったら、雇い主は俺たちが守るさ。",
  ui_story_5035_50350502_92_dialog_content = "この丸ノコを、もともと使うべき相手に使えるってこった。",
  ui_story_5035_50350502_93_dialog_content = "オレたちも行くぜ。\nもちろん、食いモンははずんでもらうからな！",
  ui_story_5035_50350502_94_dialog_content = "あと、クーラー。",
  ui_story_5035_50350502_95_dialog_content = "じゃあ、ここで別れよう。\n皆、気を付けてね！",
  ui_story_5035_50350601_1_dialog_content = "<color=#e8d9bb>ピッ…ザザッ…</color>",
  ui_story_5035_50350601_2_dialog_content = "えっ！？",
  ui_story_5035_50350601_3_dialog_content = "リリカ、どうしたの？",
  ui_story_5035_50350601_4_dialog_content = "ファインダーが…急に光りだしたの。",
  ui_story_5035_50350601_5_dialog_content = "こ、壊れちゃったのかな…？",
  ui_story_5035_50350601_6_dialog_content = "え？何が壊れたって？",
  ui_story_5035_50350601_7_dialog_content = "な、何でもないわ！\nちょっと調べれば大丈夫よ！",
  ui_story_5035_50350601_8_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5035_50350601_9_dialog_content = "クンクン…",
  ui_story_5035_50350601_10_dialog_content = "ハックション！！",
  ui_story_5035_50350601_11_dialog_content = "ジメジメしててカビ臭い…\n古いじゅうたんみたいな感じ。",
  ui_story_5035_50350601_12_dialog_content = "<color=#e8d9bb>ベチャッ…</color>",
  ui_story_5035_50350601_13_dialog_content = "あ、ここのじゅうたん、\nほんとにビショビショだ！",
  ui_story_5035_50350601_14_dialog_content = "これは申し訳ございません。\n転ばないようお気をつけください。",
  ui_story_5035_50350601_15_dialog_content = "ここのところ、じめじめした天気が続いていたものですから。\n今後は換気を徹底いたします。",
  ui_story_5035_50350601_16_dialog_content = "うーん、それだけじゃ足りませんね。\nこの部屋、たくさん陳列品があるから、しっかり湿度管理をしないと…",
  ui_story_5035_50350601_17_dialog_content = "ここに置いてある物って…\n初代の主人の頃からあったもの？",
  ui_story_5035_50350601_18_dialog_content = "ええ。この屋敷を購入した後で分かったことですが、\n今までの主たちの手で、大切に保管されていたようです。",
  ui_story_5035_50350601_19_dialog_content = "お嬢様も元の主への敬意を表し、\nそのままの状態を残すことになさったのです。",
  ui_story_5035_50350601_20_dialog_content = "そうすれば、お客様にも屋敷を作った主の趣味を\n分かっていただけるでしょう？",
  ui_story_5035_50350601_21_dialog_content = "ここも確かによい撮影ができそうです。",
  ui_story_5035_50350601_22_dialog_content = "ずいぶん…変わった趣味だったのね。",
  ui_story_5035_50350601_23_dialog_content = "どうしてこんなものを作ったのかは、\n置いておくにしても…",
  ui_story_5035_50350601_24_dialog_content = "この人形たちを見てるだけで、\n何だかイヤな気分がしてくるわ。",
  ui_story_5035_50350601_25_dialog_content = "あ、ホコリも払わないと。\n一度積もっちゃうと、きれいにするのは大変よ…",
  ui_story_5035_50350601_26_dialog_content = "バイス様…お手を汚す必要はございません。\nお客様なのですから。",
  ui_story_5035_50350601_27_dialog_content = "大丈夫ですよ、\nもうきれいになりましたから！",
  ui_story_5035_50350601_28_dialog_content = "入口にお手拭きがございますので、お持ちいたします。",
  ui_story_5035_50350601_29_dialog_content = "おや？",
  ui_story_5035_50350601_30_dialog_content = "リリカ様、なぜ入口に立ち尽くしていらっしゃるのでしょう？\nどうかなさいましたか？",
  ui_story_5035_50350601_31_dialog_content = "怪奇現象が起こるのを待ってるの！",
  ui_story_5035_50350601_32_dialog_content = "（待ってれば起こるものなの！？）",
  ui_story_5035_50350601_33_dialog_content = "あっ！！！",
  ui_story_5035_50350601_34_dialog_content = "来た来た！？",
  ui_story_5035_50350601_35_dialog_content = "さっきは気づかなかったけど、\n人形の山の中にカードが隠れてたわ。",
  ui_story_5035_50350601_36_dialog_content = "またニナの用意した演出かな？",
  ui_story_5035_50350601_37_dialog_content = "そうでしょうね。何か詩が書いてあるけど…\nちょっとおかしな内容だわ。",
  ui_story_5035_50350601_38_dialog_content = "え、じゃ、じゃあ、もっと近くに寄せて！\nカメラで撮っておくから…",
  ui_story_5035_50350601_39_dialog_content = "じゃあどうぞ、自分で持って。\nカメラで撮りながら、読み上げてみたら？",
  ui_story_5035_50350601_40_dialog_content = "そ、そうね、じゃあ、読みあげるわ…\n怖くなったら、ストップかけていいからね！",
  ui_story_5035_50350601_41_dialog_content = "「１人、2人…」",
  ui_story_5035_50350601_42_dialog_content = "<color=#e8d9bb>カチャッ――</color>",
  ui_story_5035_50350601_43_dialog_content = "「1人、2人、3人のお人形さん♪」",
  ui_story_5035_50350601_44_dialog_content = "「4人、5人、6人のお人形さん♪」",
  ui_story_5035_50350601_45_dialog_content = "「7人、8人、9人のお人形さん♪」",
  ui_story_5035_50350601_46_dialog_content = "「9人のお人形さん、頭が8つ♪」",
  ui_story_5035_50350601_47_dialog_content = "<color=#e8d9bb>ピチャン…ポタッ…</color>",
  ui_story_5035_50350601_48_dialog_content = "こ、この声は…",
  ui_story_5035_50350601_49_dialog_content = "…って、さすがにだまされないわ！？",
  ui_story_5035_50350601_50_dialog_content = "お嬢様の演出が見破られてしまったようですね。",
  ui_story_5035_50350601_51_dialog_content = "そのカードで録音を再生するしかけになっているのです。",
  ui_story_5035_50350601_52_dialog_content = "ふぅ…ホンモノかと思ってビックリしちゃったわ。",
  ui_story_5035_50350601_53_dialog_content = "リリカ、怖がりだったんだ？",
  ui_story_5035_50350601_54_dialog_content = "こ、怖いというより…興奮しちゃっただけよ！",
  ui_story_5035_50350601_55_dialog_content = "怖いんだったら守ってあげてもいいよ。",
  ui_story_5035_50350601_56_dialog_content = "もちろん、用心棒代はもらうけど。",
  ui_story_5035_50350601_57_dialog_content = "今の見たでしょ。全部、演出だよ。",
  ui_story_5035_50350601_58_dialog_content = "音質はよくないし、水滴の音もリズムになってないし、\nライムも特にないし…",
  ui_story_5035_50350601_59_dialog_content = "あと、サウンド流しっぱなしだし。",
  ui_story_5035_50350601_60_dialog_content = "貴重なご意見ありがとうございます。\nお嬢様にお伝えし、改善いたします。それから…",
  ui_story_5035_50350601_61_dialog_content = "<color=#e8d9bb>カチャッ</color>",
  ui_story_5035_50350601_62_dialog_content = "…おや？おかしいですね。\nどうして再生が急に止まってしまったのでしょう？",
  ui_story_5035_50350601_63_dialog_content = "ま、まさか、録音テープの霊に\n今のコメントを聞かれた…！？",
  ui_story_5035_50350601_64_dialog_content = "制御室を見てまいります。\n皆様はここでしばらくお待ちください。",
  ui_story_5035_50350601_65_dialog_content = "（リリカの様子がおかしい、\n会った時とぜんぜん違う…）",
  ui_story_5035_50350601_66_dialog_content = "リリカ、怖がることはないよ。\nたまたま再生が止まっただけじゃないかな。",
  ui_story_5035_50350601_67_dialog_content = "そもそも僕たちがどうにかできるものでもないし。",
  ui_story_5035_50350601_68_dialog_content = "そ、そうよね。今、あたしたちが「再生して」って言ったって、\n本当に再生してくれるわけじゃ…",
  ui_story_5035_50350601_69_dialog_content = "<color=#e8d9bb>カチャリ――</color>",
  ui_story_5035_50350601_70_dialog_content = "「1人、2人、3人のお人形さん♪」",
  ui_story_5035_50350601_71_dialog_content = "「4人、5人…」",
  ui_story_5035_50350601_72_dialog_content = "え…きゃあああああ！？",
  ui_story_5035_50350601_73_dialog_content = "…あわてないで！\nさっきと何も変わってないよ。",
  ui_story_5035_50350601_74_dialog_content = "ミ、ミノスが直したらまた動き出したのかな？",
  ui_story_5035_50350601_75_dialog_content = "き、きっと、そうだよ…",
  ui_story_5035_50350601_76_dialog_content = "<color=#e8d9bb>ピチャン…ポタッ…</color>",
  ui_story_5035_50350601_77_dialog_content = "<color=#e8d9bb>ポタッ…ポタッ…</color>",
  ui_story_5035_50350601_78_dialog_content = "…あれ？水滴のリズムが変わってる…？",
  ui_story_5035_50350601_79_dialog_content = "それももう直した…のかな？\nずいぶん早いね…",
  ui_story_5035_50350601_80_dialog_content = "ううっ…ダメよ、逃げちゃダメ！",
  ui_story_5035_50350601_81_dialog_content = "（リリカは肝心な時にはしっかりしてるみたいだ）",
  ui_story_5035_50350601_82_dialog_content = "ゆっくり、そ～っと部屋を出るの。\nカメラがブレないように…",
  ui_story_5035_50350601_83_dialog_content = "…",
  ui_story_5035_50350601_84_dialog_content = "ふぅ…",
  ui_story_5035_50350601_85_dialog_content = "心臓が止まるかと思ったけど、\n何も起こらなくてよかったわ。",
  ui_story_5035_50350601_86_dialog_content = "落ち着いたら、\nなんだか今度はいろんなアイデアが浮かんできたわ！",
  ui_story_5035_50350601_87_dialog_content = "さっきの歌、テーマソングにしようかしら？",
  ui_story_5035_50350601_88_dialog_content = "あ、陳列室で記念写真撮るのも忘れちゃった！",
  ui_story_5035_50350601_89_dialog_content = "…あんた、回復はやいね…",
  ui_story_5035_50350601_90_dialog_content = "ヒヒヒ…",
  ui_story_5035_50350601_91_dialog_content = "うわっ！？",
  ui_story_5035_50350601_92_dialog_content = "僕の肩をつついたのは誰？",
  ui_story_5035_50350601_93_dialog_content = "ごめんなさい、バーバ・ヤーガよ…",
  ui_story_5035_50350601_94_dialog_content = "代わりに謝るわ…PlayerName、痛かった？",
  ui_story_5035_50350601_95_dialog_content = "いや、全然痛くはないよ。\n痛いというより、驚いただけ。",
  ui_story_5035_50350601_96_dialog_content = "ミヤ、どうしてここに？",
  ui_story_5035_50350601_97_dialog_content = "ここがどうしても気になるって、\nバーバ・ヤーガが言うから、一緒に来たの。",
  ui_story_5035_50350601_98_dialog_content = "ペア割引は使えなかったわ…",
  ui_story_5035_50350601_99_dialog_content = "だからぁ、言ったじゃない。\n私がスタッフを「説得」してあげるって！",
  ui_story_5035_50350601_100_dialog_content = "ねぇ？PlayerName。\nミヤったら相変わらず、恥ずかしがり屋でしょ？",
  ui_story_5035_50350601_101_dialog_content = "ここであなたに会えるなんて、\n何かの縁かしらねぇ～。",
  ui_story_5035_50350601_102_dialog_content = "そうそう、さっきつつかれた時の顔――かわいかったわぁ。",
  ui_story_5035_50350601_103_dialog_content = "バーバ・ヤーガ、ミヤ、後ろ…！",
  ui_story_5035_50350601_104_dialog_content = "あらぁ？その顔、どういう意味かしらぁ？",
  ui_story_5035_50350601_105_dialog_content = "私の顔が、そんなに怖いかしら――",
  ui_story_5035_50350601_106_dialog_content = "グォォ！！！",
  ui_story_5035_50350601_107_dialog_content = "きゃああああ――！",
  ui_story_5035_50350601_108_dialog_content = "暗鬼なんて怖くないわ！",
  ui_story_5035_50350601_109_dialog_content = "義賊の心得第2条！誰かが困っている時に逃げ出さない。\n助けが必要なら、すかさず手を貸す！",
  ui_story_5035_50350601_110_dialog_content = "あたしの「クールスター」でかっ飛ばしてやるよ！",
  ui_story_5035_50350702_1_dialog_content = "ああ――暗鬼ごときで叫ぶなんて、\nいったいどうしちゃったのかしらねぇ？",
  ui_story_5035_50350702_2_dialog_content = "お姉さん、すっごくカッコいいわね！\nいくつかアングルを変えて撮影させてもらっていい？",
  ui_story_5035_50350702_3_dialog_content = "フフフフ、どうぞぉ～。",
  ui_story_5035_50350702_4_dialog_content = "でも、公開はしないでねぇ。\nミヤって、あんまり人前に自分をさらすのが好きじゃないのぉ。",
  ui_story_5035_50350702_5_dialog_content = "でないと――私がそのカメラを抱えてる虫ごと、\n踏みつぶしちゃうからぁ。",
  ui_story_5035_50350702_6_dialog_content = "う…わ、分かったわ…",
  ui_story_5035_50350702_7_dialog_content = "そういうことは言わないでって、\n言ってるでしょう…",
  ui_story_5035_50350702_8_dialog_content = "ごめんなさい、おどそうと思って言ってるんじゃないの…",
  ui_story_5035_50350702_9_dialog_content = "大丈夫よ、映ってる人の意志は尊重するから！",
  ui_story_5035_50350702_10_dialog_content = "皆様、ご無事でしたか？",
  ui_story_5035_50350702_11_dialog_content = "騒がしい音を聞いたので、心配しておりましたが…\n単なる暗鬼で済んだようで幸いでした。",
  ui_story_5035_50350702_12_dialog_content = "陳列室の録音の故障は直してまいりました。\n皆様、もう1度お入りに…",
  ui_story_5035_50350702_13_dialog_content = "い、いえ！\nもう大丈夫です、アハハハ…",
  ui_story_5035_50350702_14_dialog_content = "早く次に進みましょう！",
  ui_story_5035_50350702_15_dialog_content = "それなら、私はここでお別れするわね。",
  ui_story_5035_50350702_16_dialog_content = "せっかくお知り合いになれたんだし、\n1つ聞いてもいい？",
  ui_story_5035_50350702_17_dialog_content = "あなた、ええと…あなたたち？\nミステリー探検隊に入る気はない？",
  ui_story_5035_50350702_18_dialog_content = "やめておくわ。\nバーバ・ヤーガが…好きに回りたいって。",
  ui_story_5035_50350702_19_dialog_content = "そう？じゃあ、気を付けて。",
  ui_story_5035_50350702_20_dialog_content = "そういえば…",
  ui_story_5035_50350702_21_dialog_content = "PlayerName――\n<color=#FFB400>あの子</color>とは、一緒じゃないのねぇ。",
  ui_story_5035_50350702_22_dialog_content = "私たちの方が先に<color=#FFB400>彼女</color>と\n知り合えたってことかしらぁ？",
  ui_story_5035_50350702_23_dialog_content = "…「彼女」？",
  ui_story_5035_50350702_24_dialog_content = "そう。でも、私もなかなか会えないのぉ。",
  ui_story_5035_50350702_25_dialog_content = "ここなら会えるかと思ったけど、\n会えなくて、ちょっとガッカリよぉ――",
  ui_story_5035_50350702_26_dialog_content = "い、いったい誰のこと…？",
  ui_story_5035_50350702_27_dialog_content = "ヒヒヒ、冗談よぉ。\n<color=#FFB400>彼女</color>のことは、ミヤと探すことにするわぁ。",
  ui_story_5035_50350702_28_dialog_content = "ただ、PlayerName、忠告しておくけど――",
  ui_story_5035_50350702_29_dialog_content = "<color=#FFB400>彼女のトリコにならないように、\n気をつけなさいねぇ…</color>",
  ui_story_5035_50350702_30_dialog_content = "だって、<color=#FFB400>彼女を「宴」に引きずりこめる</color>のは、\n私しかいないんだからぁ。",
  ui_story_5035_50350702_31_dialog_content = "どういう意味…？",
  ui_story_5035_50350702_32_dialog_content = "フフフ…その「訳がわからない」って顔、かわいいわぁ。",
  ui_story_5035_50350702_33_dialog_content = "じゃあ、また会いましょう？",
  ui_story_5035_50350702_34_dialog_content = "まったく――こんなことなら…",
  ui_story_5035_50350702_35_dialog_content = "ここの持ち主が、\n私に筋書きを書かせてくれればよかったのよぉ…",
  ui_story_5035_50350702_36_dialog_content = "行っちゃったわね…",
  ui_story_5035_50350702_37_dialog_content = "（バーバ・ヤーガが言ってたのって、誰だろう？）",
  ui_story_5035_50350702_38_dialog_content = "（でも、あまり多くは話したくないみたいだったし…）",
  ui_story_5035_50350702_39_dialog_content = "（まあ、いいや。そのうち真相が分かるといいけど）",
  ui_story_5035_50350702_40_dialog_content = "画面の前のみんな～！\n彼がウワサの空の末裔よ！",
  ui_story_5035_50350702_41_dialog_content = "さっき出会った、屋敷の奥深くを歩き回ってる女の子…",
  ui_story_5035_50350702_42_dialog_content = "意味深な会話だったけど、\nいったい何を暗示してるのかしら…？",
  ui_story_5035_50350702_43_dialog_content = "リリカ、変なこと言わないでよ！？",
  ui_story_5035_50350702_44_dialog_content = "ウソウソ！カメラは回してないわ！",
  ui_story_5035_50350702_45_dialog_content = "はいはい…じゃれ合いおしまい、ここにずっとは止まってらんない。",
  ui_story_5035_50350702_46_dialog_content = "次の地下室でロケハンおしまい。",
  ui_story_5035_50350702_47_dialog_content = "サディ様はまだお若いというのに、\n冷静なプロの精神をお持ちのようですね。",
  ui_story_5035_50350702_48_dialog_content = "！？",
  ui_story_5035_50350702_49_dialog_content = "た、大したことじゃないよ。\nカ、カッコいい義賊はみんな、こんなもんだよ！",
  ui_story_5035_50350702_50_dialog_content = "じゃあ、地下室へレッツゴ～！",
  ui_story_5035_50350702_51_dialog_content = "ご案内いたします。",
  ui_story_5035_50350702_52_dialog_content = "さぁさぁ、撮影続けるよ！",
  ui_story_5035_50350801_1_dialog_content = "<color=#e8d9bb>ピッ――</color>",
  ui_story_5035_50350801_2_dialog_content = "お化け屋敷で探すよ、最後の撮影ロケーション♪",
  ui_story_5035_50350801_3_dialog_content = "リストの最後の目的地、今から行くのはアンダーグラウンド…\n執事さん、案内よろしく。",
  ui_story_5035_50350801_4_dialog_content = "そのことについてですが…ヨハン様との契約では、\n撮影可能な範囲を明確に取り決めておりました。",
  ui_story_5035_50350801_5_dialog_content = "地下室は当ゴーストハウスの営業区域外ですので、\n明日監督と、価格も含めて再度お話が必要ですね。",
  ui_story_5035_50350801_6_dialog_content = "やめてよ、お金なんてつまんない話、雰囲気台無しじゃん。\nま、いいや。とにかく出発しよ。",
  ui_story_5035_50350801_7_dialog_content = "…リリカ、何してんの？\n早く行こうよ。",
  ui_story_5035_50350801_8_dialog_content = "充電はまだ大丈夫そうね。レンズキャップも外したし…\n焦点はとりあえず適当に合わせとこっと…",
  ui_story_5035_50350801_9_dialog_content = "できた！PlayerName、こっち来て！",
  ui_story_5035_50350801_10_dialog_content = "え、僕？",
  ui_story_5035_50350801_11_dialog_content = "そうそう。あなた、器用そうだし。",
  ui_story_5035_50350801_12_dialog_content = "カメラマン、やってみない？面白いわよ！",
  ui_story_5035_50350801_13_dialog_content = "カメラマン？君が自分で撮ってるやつでしょ？\n僕が撮る必要ある？",
  ui_story_5035_50350801_14_dialog_content = "この後、あたしも映ろうと思って。\nだから、手伝って！",
  ui_story_5035_50350801_15_dialog_content = "ううん、別にいいけど、どうやれば…",
  ui_story_5035_50350801_16_dialog_content = "ほら、これを肩にかついで。",
  ui_story_5035_50350801_17_dialog_content = "うわ！？",
  ui_story_5035_50350801_18_dialog_content = "落とさないでね、高いんだから！",
  ui_story_5035_50350801_19_dialog_content = "壊しちゃったら、\n何十何百何千万コインの弁償が必要になるかもよ？",
  ui_story_5035_50350801_20_dialog_content = "そんなリスクのある仕事、やりたくないよ！",
  ui_story_5035_50350801_21_dialog_content = "アハハ、冗談よ。\nさ、カメラをあたしに向けて。",
  ui_story_5035_50350801_22_dialog_content = "そう、その調子。",
  ui_story_5035_50350801_23_dialog_content = "リリカ、なんでまたカメラをいじりだしたの？",
  ui_story_5035_50350801_24_dialog_content = "え？だって…",
  ui_story_5035_50350801_25_dialog_content = "何かが起こった時、\nカメラが記録してくれるかもしれないでしょ。",
  ui_story_5035_50350801_26_dialog_content = "この後、事件が起こるってコト？",
  ui_story_5035_50350801_27_dialog_content = "もう、そういう意味じゃないって。\nとにかく…",
  ui_story_5035_50350801_28_dialog_content = "ミノス、さっき地下室は\n営業エリアじゃないって言ったわよね？",
  ui_story_5035_50350801_29_dialog_content = "はい、確かに。",
  ui_story_5035_50350801_30_dialog_content = "つまり、地下室は撮影しても\nお化け屋敷のネタばらしにはならないってことよね！",
  ui_story_5035_50350801_31_dialog_content = "ええ、どうぞご自由に。",
  ui_story_5035_50350801_32_dialog_content = "よかった。せっかくカメラを持ってきたんだから、\nできるだけたくさん撮らなきゃ！",
  ui_story_5035_50350801_33_dialog_content = "さあさあ、出発よ！",
  ui_story_5035_50350801_34_dialog_content = "わかったよ。あ、先に言っとくけど、\nあたしの映ってるシーンを公開するなら、ギャラをちょうだいね。",
  ui_story_5035_50350801_35_dialog_content = "ええ？さっき「お金の話はするな」って言ってなかった？",
  ui_story_5035_50350801_36_dialog_content = "地下室はこちらです。\n道が良くありませんので、お気をつけください。",
  ui_story_5035_50350801_37_dialog_content = "PlayerName、カメラはちゃんと使える？",
  ui_story_5035_50350801_38_dialog_content = "かついでレンズを向けるだけでしょ、大丈夫。",
  ui_story_5035_50350801_39_dialog_content = "でも、バイス…\nそんなに近くにいたら、顔が大きく映っちゃうよ。",
  ui_story_5035_50350801_40_dialog_content = "え？ちょ、ちょっと、寄らないで！？",
  ui_story_5035_50350801_41_dialog_content = "急いで、ちゃんと付いてきてね！\nカメラはずっとあたしに向けといて！",
  ui_story_5035_50350801_42_dialog_content = "<color=#e8d9bb>タッ、タッ、タッ――</color>",
  ui_story_5035_50350801_43_dialog_content = "そういえば、ミノス。\nどうして地下室は営業に使ってないの？",
  ui_story_5035_50350801_44_dialog_content = "地下室なんて、いかにも怖そうじゃない？\n別料金にだってできるかもしれないわ。",
  ui_story_5035_50350801_45_dialog_content = "その件についてご説明するには、\nお嬢様がこの屋敷を購入された時のことからお話しせねばなりませんね。",
  ui_story_5035_50350801_46_dialog_content = "前の持ち主は屋敷を手放すことを急いでおり、\nずいぶんと安い値段で売り出していましたが…",
  ui_story_5035_50350801_47_dialog_content = "そのうえ、地下室を含めずに床面積を計算しておりました。",
  ui_story_5035_50350801_48_dialog_content = "つまり、地下室は値段に\n含まれていなかったわけでございますね。",
  ui_story_5035_50350801_49_dialog_content = "へー、そんな良心的な売り手がいるのね。",
  ui_story_5035_50350801_50_dialog_content = "お嬢様に代わって屋敷を検収した際、地下室があることに気づき、\n前の持ち主にたずねたところ…",
  ui_story_5035_50350801_51_dialog_content = "地下室はとうの昔に使われなくなっていて、\n中も汚く荒れ果てており、嫌な臭いまでするとのことでした。",
  ui_story_5035_50350801_52_dialog_content = "そのようなものに値段をつけるのは申しわけないと思い、\n床面積には含めなかった、と言っておりました。",
  ui_story_5035_50350801_53_dialog_content = "地下室には入らないほうがよい、\n下手にいじろうとしても、損をするだけだと忠告もいただきまして。",
  ui_story_5035_50350801_54_dialog_content = "いっそ完全に塞いでしまって、\n存在しないものと考えた方がいいとおっしゃっていました。",
  ui_story_5035_50350801_55_dialog_content = "で、言う通りにしたってこと？",
  ui_story_5035_50350801_56_dialog_content = "ほぼそういうことになりますね。\nただ、工期の都合がつかず、地下室を処分する時間がありませんでしたので…",
  ui_story_5035_50350801_57_dialog_content = "まだ、完全には塞がれておりません。",
  ui_story_5035_50350801_58_dialog_content = "ひとまず入口は隠してあります。\nあまり人の来ない時期になったら、改修しようかと。",
  ui_story_5035_50350801_59_dialog_content = "いろいろ考えてるのね…",
  ui_story_5035_50350801_60_dialog_content = "到着いたしました。こちらです。",
  ui_story_5035_50350801_61_dialog_content = "<color=#e8d9bb>バサッ――</color>",
  ui_story_5035_50350801_62_dialog_content = "わ！じゅうたんの下に隠してあったのね！",
  ui_story_5035_50350801_63_dialog_content = "しっかり付いてきてください。\n中は少し暗くなっております。",
  ui_story_5035_50350801_64_dialog_content = "PlayerName、カメラをぶつけないように注意してね！",
  ui_story_5035_50350801_65_dialog_content = "分かってるよ。",
  ui_story_5035_50350801_66_dialog_content = "これ、少し暗いどころじゃないわ、何も見えない！",
  ui_story_5035_50350801_67_dialog_content = "どっちを見ても真っ暗がり…\nゴホゴホッ…宙に充満するホコリ…",
  ui_story_5035_50350801_68_dialog_content = "あれ、ミノス？見失っちゃったみたい…",
  ui_story_5035_50350801_69_dialog_content = "明かりをつけましょう。",
  ui_story_5035_50350801_70_dialog_content = "うわ、まぶしい！",
  ui_story_5035_50350801_71_dialog_content = "この地下室ですが、内装工事の際1度来たきりで、\n私もよく調べられておりません。",
  ui_story_5035_50350801_72_dialog_content = "何があるかは私にも分かりかねます。\n皆様、十分お気をつけください。",
  ui_story_5035_50350801_73_dialog_content = "見たかぎり、想像していたほどひどくはないわね。",
  ui_story_5035_50350801_74_dialog_content = "雑然としてはいるけど、汚いってほどでもないし、\n前の持ち主の人が言っていた、匂いもしないわ。",
  ui_story_5035_50350801_75_dialog_content = "それに、誰かが片付けた痕跡があるわね。",
  ui_story_5035_50350801_76_dialog_content = "あ、あっちにロウ人形があるよ。",
  ui_story_5035_50350801_77_dialog_content = "でも、雑なつくりだね…じっくり見るほどでもないかな。",
  ui_story_5035_50350801_78_dialog_content = "ホコリの上に…足跡がついてるみたいだね。",
  ui_story_5035_50350801_79_dialog_content = "あ、本当だわ！",
  ui_story_5035_50350801_80_dialog_content = "壁にも手形がついてるわ。\n私の手よりずいぶんと小さいけど。",
  ui_story_5035_50350801_81_dialog_content = "子どもの手形かしら？",
  ui_story_5035_50350801_82_dialog_content = "柱にキズがあるよ。\nコレ、なんだか知ってる。家にもあるから。",
  ui_story_5035_50350801_83_dialog_content = "歯形かしら？",
  ui_story_5035_50350801_84_dialog_content = "…そんなわけないでしょ…",
  ui_story_5035_50350801_85_dialog_content = "身長を測った跡だよ。\n子どもの背が伸びるたびに、刻むやつ。",
  ui_story_5035_50350801_86_dialog_content = "ああ、身長を測ってたのね。",
  ui_story_5035_50350801_87_dialog_content = "でも、ずいぶん背が低いわね？\n一番高い所にあるキズだって、サディにも届かないわ。",
  ui_story_5035_50350801_88_dialog_content = "うっ…",
  ui_story_5035_50350801_89_dialog_content = "おっしゃる通りでございますね。\nそのキズに手形、足跡はすべて、子どもが残したものでしょう。",
  ui_story_5035_50350801_90_dialog_content = "形の違うものが混ざっていますから、\nおそらく1人だけのものではありませんね。",
  ui_story_5035_50350801_91_dialog_content = "しかし…子どもがなぜこのような場所に…",
  ui_story_5035_50350801_92_dialog_content = "…ねえ、これを見て。",
  ui_story_5035_50350801_93_dialog_content = "床に落ちてた紙、文字が書いてあるわ。",
  ui_story_5035_50350801_94_dialog_content = "え？なんて書いてあるの？",
  ui_story_5035_50350801_95_dialog_content = "きれいな字ではないけど、読んでみるわね…オホン。",
  ui_story_5035_50350801_96_dialog_content = "「覚えておくことはたった一つ」",
  ui_story_5035_50350801_97_dialog_content = "「言うことを聞かない子どもは、奥様の<color=#FFB400>罰</color>を受ける」",
  ui_story_5035_50350801_98_dialog_content = "「地下室の扉が開き、言うことを聞かない子は連れて行かれる」",
  ui_story_5035_50350801_99_dialog_content = "「その子だけじゃない、一番仲のいい友達も道連れに」",
  ui_story_5035_50350801_100_dialog_content = "「言うことを聞かないとどうなるか、しっかり覚えておくこと」",
  ui_story_5035_50350801_101_dialog_content = "「お友達は、心配することはありません。あなたの身には何も起こりません」",
  ui_story_5035_50350801_102_dialog_content = "「ただし、言うことを聞いて、部屋の一番奥へ行き、\n壁に向かって立っていてください」",
  ui_story_5035_50350801_103_dialog_content = "「しっかり聞いて、でも何が聞こえても、\n決して振り返ってはなりません」",
  ui_story_5035_50350801_104_dialog_content = "「奥様は<color=#FFB400>罰を与える</color>ところを\n他人に見られるのが嫌いなのです」",
  ui_story_5035_50350801_105_dialog_content = "…これで終わりね。おかしな内容だわ。",
  ui_story_5035_50350801_106_dialog_content = "何だか警告みたいだね？\n書かれてたこと、本当なのかな？",
  ui_story_5035_50350801_107_dialog_content = "「奥様」っていうのは…\nミノスの言ってた「エスター夫人」のことかな？",
  ui_story_5035_50350801_108_dialog_content = "私にも分かりかねます。\n「エスター夫人」については、伝説のような話しか残っておりませんので。",
  ui_story_5035_50350801_109_dialog_content = "まさか、この地下室、\nお仕置き部屋だったのかな？",
  ui_story_5035_50350801_110_dialog_content = "1人は罰を受けて、\nもう1人は壁に向かわせられて、ただ音を聞かされる…",
  ui_story_5035_50350801_111_dialog_content = "そんなの、ヘンタイのすることよ。\n…本当の話じゃないことを願うわ。",
  ui_story_5035_50350801_112_dialog_content = "筆跡からすると、子どもが書いたのかしら。",
  ui_story_5035_50350801_113_dialog_content = "だったら、子どもの作り話かもしれないでしょ？",
  ui_story_5035_50350801_114_dialog_content = "たぶん違うよ。ほかの紙を見て。",
  ui_story_5035_50350801_115_dialog_content = "どれも字が書いてある。全部同じ内容。",
  ui_story_5035_50350801_116_dialog_content = "「覚えておくことはたった一つ」",
  ui_story_5035_50350801_117_dialog_content = "「言うことを聞かない子どもは、<color=#FFB400>罰</color>を受ける…」",
  ui_story_5035_50350801_118_dialog_content = "作り話をわざわざ何度も書き写したりするかな？",
  ui_story_5035_50350801_119_dialog_content = "と、当然、そんなことしないと思うわ…",
  ui_story_5035_50350801_120_dialog_content = "何度どころか、1度だって面倒よ。\nあたしが最後に字を書いたのっていつだったかしら？10歳？",
  ui_story_5035_50350801_121_dialog_content = "何度も書き写すなんて単純な作業、\n誰だってやりたくないわ。",
  ui_story_5035_50350801_122_dialog_content = "誰かに…",
  ui_story_5035_50350801_123_dialog_content = "やらされないかぎりはね。\nってことは…分かった、きっとこれが罰なんだ。",
  ui_story_5035_50350801_124_dialog_content = "子どもにこんなものを書かせるの？そんなの…",
  ui_story_5035_50350801_125_dialog_content = "ミノスって言ったっけ、執事さん、\n前の持ち主のこと、どれくらい知ってる？",
  ui_story_5035_50350801_126_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5035_50350801_127_dialog_content = "ミノス？",
  ui_story_5035_50350801_128_dialog_content = "別のものを見つけました。こちらを。",
  ui_story_5035_50350801_129_dialog_content = "ええと、ノートですね。\n中には同じことが書かれてるんですか？",
  ui_story_5035_50350801_130_dialog_content = "いえ、別のものです。\nただ、このノートは明らかに新しい。最近のものでしょう。",
  ui_story_5035_50350801_131_dialog_content = "表紙には「撮影クルー業務記録」とあります。\n執筆者は…プロデューサーとだけ。",
  ui_story_5035_50350801_132_dialog_content = "撮影クルー？プロデューサー？\nミノスさん、自分が臨時プロデューサーだって…",
  ui_story_5035_50350801_133_dialog_content = "私が書いたものではありません。\n他の誰かが撮影に来たことがあるのかもしれませんね…",
  ui_story_5035_50350801_134_dialog_content = "なるほど…中には何が？",
  ui_story_5035_50350801_135_dialog_content = "「撮影場所：寝室」",
  ui_story_5035_50350801_136_dialog_content = "「ここはひどい。窓からも壁からもすきま風が吹いてくる。\nみんな、全身を震わせながら仕事していた」",
  ui_story_5035_50350801_137_dialog_content = "「監督が来るのを待つ間、テレビでも見ようと思ったが、\nポンコツのようで、何も受信できない」",
  ui_story_5035_50350801_138_dialog_content = "「さらに最悪だったのは監督ではなく、暗鬼が出てきたことだ」",
  ui_story_5035_50350801_139_dialog_content = "「道具の半分が壊れ、スタッフ3人がケガをした。\n監督にはすでに伝えたが、こんな所で撮影なんてまっぴらだ」",
  ui_story_5035_50350801_140_dialog_content = "このスタッフたちも寝室に行ったようですね。",
  ui_story_5035_50350801_141_dialog_content = "このお屋敷、暗鬼が出てくるのが普通のことだったわけね…\nどうりで、安く売り払うわけだわ。",
  ui_story_5035_50350801_142_dialog_content = "次の記録も私たちのよく知っている場所ですね。",
  ui_story_5035_50350801_143_dialog_content = "「撮影場所：陳列室」",
  ui_story_5035_50350801_144_dialog_content = "「もうガマンならない。監督が何が何でもこの部屋で撮影するというなら、\n俺は仕事を辞めてでも帰らせてもらう」",
  ui_story_5035_50350801_145_dialog_content = "「気味の悪い歌がずっと流れている。\nおまけに歌に合わせて、うっとうしい水滴の音まで聞こえてくる」",
  ui_story_5035_50350801_146_dialog_content = "「これが家主の趣味だったっていうのか？\nだとしたら、頭を蹴り飛ばしてやりたい」",
  ui_story_5035_50350801_147_dialog_content = "「俺はホラー映画を撮りにきたんだ。\n幽霊に会いにきたわけじゃない」",
  ui_story_5035_50350801_148_dialog_content = "陳列室で私たちと同じ体験をしてるわ。\n歌と水滴の音、この人も聞いたのね！",
  ui_story_5035_50350801_149_dialog_content = "…これ、本当にミノスさんが書いたものじゃないの？",
  ui_story_5035_50350801_150_dialog_content = "私が書いたとしたら、もっと恐ろしいことだと思いませんか？",
  ui_story_5035_50350801_151_dialog_content = "そ、そうかも…",
  ui_story_5035_50350801_152_dialog_content = "それから？ノートの主、地下室にも行ったの？",
  ui_story_5035_50350801_153_dialog_content = "…いや…ごめん、バカなこと聞いちゃった。\nノートはここで見つけたんだったね。",
  ui_story_5035_50350801_154_dialog_content = "その通りですね。次の記録は地下室です。",
  ui_story_5035_50350801_155_dialog_content = "「撮影場所：地下室」",
  ui_story_5035_50350801_156_dialog_content = "…",
  ui_story_5035_50350801_157_dialog_content = "どうしたんですか？続きは…",
  ui_story_5035_50350801_158_dialog_content = "ご自分でご覧になってください。",
  ui_story_5035_50350801_159_dialog_content = "え？いったい何が…",
  ui_story_5035_50350801_160_dialog_content = "…",
  ui_story_5035_50350801_161_dialog_content = "「彼女が来た」",
  ui_story_5035_50350801_162_dialog_content = "…これだけ？",
  ui_story_5035_50350801_163_dialog_content = "誰が来たっていうの？",
  ui_story_5035_50350801_164_dialog_content = "もしかして、紙に書かれてた、「奥様」？",
  ui_story_5035_50350801_165_dialog_content = "これ以上の情報はありません。\n地下室にあるものは、今ここにあるものだけですから。",
  ui_story_5035_50350801_166_dialog_content = "何が起こったかは、想像するしかありませんね。",
  ui_story_5035_50350801_167_dialog_content = "皆様、他にご覧になりたいものはございますか？",
  ui_story_5035_50350801_168_dialog_content = "実はもう、ちょっと帰りたくなってきた…",
  ui_story_5035_50350801_169_dialog_content = "わ、私も…",
  ui_story_5035_50350801_170_dialog_content = "ちょっと待ってよ！\nみんな、どうしてそんなにテンション低いの！？",
  ui_story_5035_50350801_171_dialog_content = "もうすぐあたしたちの「ゴーストハウス」の撮影が終わるのよ？\n嬉しいことじゃないの？",
  ui_story_5035_50350801_172_dialog_content = "これだけのものを見て、リリカは怖くならないの？",
  ui_story_5035_50350801_173_dialog_content = "もちろん、ちょっとはゾッとしたけど…\nこういう時こそ、沈んだ空気を何とかしなきゃ！",
  ui_story_5035_50350801_174_dialog_content = "オバケもまだ出てきてないのに、\n自分で自分を怖がらせてどうするの！？",
  ui_story_5035_50350801_175_dialog_content = "さ、気分転換もかねて、\nみんなで地下室探検の記念撮影しましょ！",
  ui_story_5035_50350801_176_dialog_content = "ここで？いったん、外に出た方が…",
  ui_story_5035_50350801_177_dialog_content = "当然でしょ、ここで撮らなきゃ記念にならないじゃない。",
  ui_story_5035_50350801_178_dialog_content = "いいんじゃない？撮ったら、あたしにもちょうだい。\n新作の宣伝写真にするからさ。",
  ui_story_5035_50350801_179_dialog_content = "私にもいただけますか？\n写真があると諸々の交渉を進めやすくなりますので。",
  ui_story_5035_50350801_180_dialog_content = "ほら、みんな賛成してくれたわ。\nさあ、撮るわよ！",
  ui_story_5035_50350801_181_dialog_content = "分かった。じゃあ、僕が撮ってあげるよ。",
  ui_story_5035_50350801_182_dialog_content = "ダメよ。記念撮影なんだから全員で写らなきゃ！",
  ui_story_5035_50350801_183_dialog_content = "まずPlayerName以外のみんな、あたしの側に並んで。",
  ui_story_5035_50350801_184_dialog_content = "もうちょっとだけ寄ってね。",
  ui_story_5035_50350801_185_dialog_content = "こう？",
  ui_story_5035_50350801_186_dialog_content = "そう！じゃあ、PlayerName、カメラをそこのスタンドにのせて、\nピントを合わせて！",
  ui_story_5035_50350801_187_dialog_content = "シャッターを押したら、すぐにこっちに来て。\n分かった？",
  ui_story_5035_50350801_188_dialog_content = "ああ、そういうことか。分かったよ。",
  ui_story_5035_50350801_189_dialog_content = "ええっと、カメラはここに置いて、ピントを合わせて…",
  ui_story_5035_50350801_190_dialog_content = "シャッターはこのボタン？",
  ui_story_5035_50350801_191_dialog_content = "そうよ！ちゃんと数えてから押してね。\nあたしたちも準備があるんだから。",
  ui_story_5035_50350801_192_dialog_content = "分かった。皆、こっち向いて！",
  ui_story_5035_50350801_193_dialog_content = "行くよ、3、2、1…",
  ui_story_5035_50350801_194_dialog_content = "<color=#e8d9bb>フッ…</color>",
  ui_story_5035_50350801_195_dialog_content = "えっ！？",
  ui_story_5035_50350801_196_dialog_content = "な、何があったの！？停電？",
  ui_story_5035_50350801_197_dialog_content = "イタタ、誰かあたしの足、踏んでるよ！",
  ui_story_5035_50350801_198_dialog_content = "ごめんなさい！…って、ちょっと待って。\n私、何も踏んでないわ。",
  ui_story_5035_50350801_199_dialog_content = "あっ！！",
  ui_story_5035_50350801_200_dialog_content = "今、水滴か何かが落ちてこなかった？",
  ui_story_5035_50350801_201_dialog_content = "冷たい、水か何かが…",
  ui_story_5035_50350801_202_dialog_content = "うん、あたしも感じた…",
  ui_story_5035_50350801_203_dialog_content = "あなたも？よかった！！",
  ui_story_5035_50350801_204_dialog_content = "よかった！？",
  ui_story_5035_50350801_205_dialog_content = "きっと何か、「出た」んだわ！",
  ui_story_5035_50350801_206_dialog_content = "喜んでる場合じゃないわ！？",
  ui_story_5035_50350801_207_dialog_content = "PlayerName！\nそのカメラに暗視モードがついてるから、急いで切り換えて！",
  ui_story_5035_50350801_208_dialog_content = "え、そんな機能がついてるの！？\nで、どこをどうすればいい？",
  ui_story_5035_50350801_209_dialog_content = "シャッターの真下あたりを触ってみて。\n四角いボタンがあるはずよ、それを押して！",
  ui_story_5035_50350801_210_dialog_content = "シャッターの真下…",
  ui_story_5035_50350801_211_dialog_content = "あっ！！",
  ui_story_5035_50350801_212_dialog_content = "急いで！見えたわ、そこよ！そこそこ！",
  ui_story_5035_50350801_213_dialog_content = "あ、あった、これだ！",
  ui_story_5035_50350801_214_dialog_content = "<color=#e8d9bb>ピッ…</color>",
  ui_story_5035_50350801_215_dialog_content = "わあ！ちゃんと映ってる…",
  ui_story_5035_50350801_216_dialog_content = "何が映ってるの！？",
  ui_story_5035_50350801_217_dialog_content = "ええと、ミノス…みたいだけど。",
  ui_story_5035_50350801_218_dialog_content = "え？ミノスさんは私たちと一緒にいるでしょ？",
  ui_story_5035_50350801_219_dialog_content = "ううん、ミノスが…",
  ui_story_5035_50350801_220_dialog_content = "壁の隅っこに向かって立ってる…",
  ui_story_5035_50350801_221_dialog_content = "ちょっと待って…壁に向かって立ってる？",
  ui_story_5035_50350801_222_dialog_content = "ねえ、覚えてる？さっき見た紙に書いてあったこと…",
  ui_story_5035_50350801_223_dialog_content = "えっ？",
  ui_story_5035_50350801_224_dialog_content = "言うことを聞かない子どもには\n奥様が罰を与える、って話だったね。",
  ui_story_5035_50350801_225_dialog_content = "1人は罰を受けて、もう1人は…壁に向かって、ただ聞くだけ…",
  ui_story_5035_50350801_226_dialog_content = "まさか…",
  ui_story_5035_50350801_227_dialog_content = "でも、ミノスさんの様子って、まさに…",
  ui_story_5035_50350801_228_dialog_content = "待って！もし本当にそうなら…",
  ui_story_5035_50350801_229_dialog_content = "ミノスが罰を受ける様子を聞かされるなら、\nあたしたちは…",
  ui_story_5035_50350801_230_dialog_content = "<color=#e8d9bb>ピチャン…</color>",
  ui_story_5035_50350801_231_dialog_content = "うっ、水の音…",
  ui_story_5035_50350801_232_dialog_content = "いやあああああ！！！",
  ui_story_5035_50350801_233_dialog_content = "あわてないで、出口を探すから…",
  ui_story_5035_50350801_234_dialog_content = "<color=#e8d9bb>誰かが<size=50>罰</size>を受けなければならない</color>",
  ui_story_5035_50350801_235_dialog_content = "！？",
  ui_story_5035_50350801_236_dialog_content = "<color=#e8d9bb>ガチャン！！！</color>",
  ui_story_5035_50350801_237_dialog_content = "あっ！！",
  ui_story_5035_50350801_238_dialog_content = "<size=45>えっ！？</size>",
  ui_story_5035_50350801_239_dialog_content = "<size=55>きゃあ！！！</size>",
  ui_story_5035_50350801_240_dialog_content = "<color=#e8d9bb>ブーン…</color>",
  ui_story_5035_50350801_241_dialog_content = "<color=#e8d9bb>カツン――</color>",
  ui_story_5035_50350801_242_dialog_content = "<color=#e8d9bb>カツン…カツン…</color>",
  ui_story_5035_50350801_243_dialog_content = "カメラが落ちましたよ。\n皆様、何をなさっているのです？",
  ui_story_5035_50350801_244_dialog_content = "PlayerName様、どうぞ。\nしっかりお持ちになってください。",
  ui_story_5035_50350801_245_dialog_content = "あ、うん。あの、さっき、ミノスは…",
  ui_story_5035_50350801_246_dialog_content = "電気の安全用ブレーカーが落ちて照明が消えてしまったようなので、\n直してまいりました。",
  ui_story_5035_50350801_247_dialog_content = "…え、それだけ？",
  ui_story_5035_50350801_248_dialog_content = "じゃあ、壁に向かって立っていたのは…",
  ui_story_5035_50350801_249_dialog_content = "ブレーカーがあちらにあるのです。",
  ui_story_5035_50350801_250_dialog_content = "…",
  ui_story_5035_50350801_251_dialog_content = "手さぐりでスイッチを探すのに、少々時間がかかってしまいました。\n皆様が騒いでおられたので、気になっておりましたが…",
  ui_story_5035_50350801_252_dialog_content = "さきほど皆様に、何かございましたか？",
  ui_story_5035_50350801_253_dialog_content = "ええと、私たちが見たのは…その…",
  ui_story_5035_50350801_254_dialog_content = "もう、真っ暗で何が見えるっていうのよ？",
  ui_story_5035_50350801_255_dialog_content = "あー、よかった。また見間違いだったんだね。",
  ui_story_5035_50350801_256_dialog_content = "あーあ、残念だわ。またカン違いなんて！",
  ui_story_5035_50350801_257_dialog_content = "いったい何を期待してるの！？",
  ui_story_5035_50350801_258_dialog_content = "つまんないの～。\nでも、仕方ないか。今夜の撮影も収穫ナシみたいね。",
  ui_story_5035_50350801_259_dialog_content = "ふわぁ～…眠い。\n記念写真を撮り直したら、帰って寝ることにするわ。",
  ui_story_5035_50350801_260_dialog_content = "記念写真のこと、忘れてなかったんだね…",
  ui_story_5035_50350801_261_dialog_content = "当然でしょ！記念撮影はとっても大事なのよ！",
  ui_story_5035_50350801_262_dialog_content = "ついでに、カメラが壊れてないか確認しなきゃいけないし。\nもし壊れてたら、PlayerName…ふふふ。",
  ui_story_5035_50350801_263_dialog_content = "えっ！？",
  ui_story_5035_50350801_264_dialog_content = "わ、分かったよ！皆、急いで並んで！",
  ui_story_5035_50350801_265_dialog_content = "わ、わかったわ。",
  ui_story_5035_50350801_266_dialog_content = "カメラくん、お願いだよ。\n君はそんなに弱くないよね。",
  ui_story_5035_50350801_267_dialog_content = "こっちに来るのも忘れないでね。",
  ui_story_5035_50350801_268_dialog_content = "君ならきっとやれる！\nさあ、がんばって！",
  ui_story_5035_50350801_269_dialog_content = "3…2…1…",
  ui_story_5035_50350801_270_dialog_content = "<color=#e8d9bb>カシャッ！</color>",
  ui_story_5035_50350901_1_dialog_content = "『ゴーストハウス』――クランクアップ！！",
  ui_story_5035_50350901_2_dialog_content = "めでたしめでたし！\nミノス、ここって現像できる場所はある？",
  ui_story_5035_50350901_3_dialog_content = "一緒に撮った写真、みんなにプレゼントしたいの！",
  ui_story_5035_50350901_4_dialog_content = "私の作業部屋に暗室がございます。\nこちらへ。",
  ui_story_5035_50350901_5_dialog_content = "ほかの皆様もご一緒にいらしてください。\n今夜お休みいただくお部屋をご用意いたします。",
  ui_story_5035_50350901_6_dialog_content = "今日はたくさんのことが起こりましたから、\n落ち着いてゆっくり細部を整理する必要もございますので。",
  ui_story_5035_50350901_7_dialog_content = "うん、そうだね。\n今日は1日中、考えるヒマもなかった気がする。",
  ui_story_5035_50350901_8_dialog_content = "いろいろありすぎ、頭を使うヒマなんてなし、\n行動派のあたし、使うのは手足♪",
  ui_story_5035_50350901_9_dialog_content = "そういえば、さっき地下室で照明が消えた時、\n誰かがおかしなことを言わなかった？",
  ui_story_5035_50350901_10_dialog_content = "おかしなこと？",
  ui_story_5035_50350901_11_dialog_content = "「誰かが罰を受けなければならない」とか…\nでも、誰の声かは分からなかったでしょ。",
  ui_story_5035_50350901_12_dialog_content = "え？誰かそんなこと言った？",
  ui_story_5035_50350901_13_dialog_content = "私には聞こえなかったけど。",
  ui_story_5035_50350901_14_dialog_content = "え？聞こえなかったの？",
  ui_story_5035_50350901_15_dialog_content = "まさか、あの部屋に他にも…",
  ui_story_5035_50350901_16_dialog_content = "もう、おどかさないでよ！！",
  ui_story_5035_50350901_17_dialog_content = "早く行くわよ！",
  ui_story_5035_50350901_18_dialog_content = "わ！ミノスの部屋って、すっごく片付いてるのね！",
  ui_story_5035_50350901_19_dialog_content = "置いてある物にはお手を触れないでくださいませ。\n撮影クルーの機材だそうですので。",
  ui_story_5035_50350901_20_dialog_content = "分かってるって。それで、暗室はどこ？",
  ui_story_5035_50350901_21_dialog_content = "そうでしたね。暗室はそちらのドアの向こう側です。\n現像作業はお出来になりますか？",
  ui_story_5035_50350901_22_dialog_content = "もちろんよ！あたしはプロのカメラマ…",
  ui_story_5035_50350901_23_dialog_content = "じゃないわ、カメラ好きだもの！",
  ui_story_5035_50350901_24_dialog_content = "もうそっちを本業にしたら？",
  ui_story_5035_50350901_25_dialog_content = "アハハ…ちょっと時間がかかるから、\nみんなは待ってて。",
  ui_story_5035_50350901_26_dialog_content = "ふぅ…疲れたわ。ちょっと休みましょ。",
  ui_story_5035_50350901_27_dialog_content = "本当に来てよかったわ！\nスリルと絶叫の連続だったもの！",
  ui_story_5035_50350901_28_dialog_content = "あんなに怖がってたのに「来てよかった」って…？",
  ui_story_5035_50350901_29_dialog_content = "怪奇現象好きと怖がりは矛盾しないのよ。",
  ui_story_5035_50350901_30_dialog_content = "むしろ、怪奇現象が怖いからこそ、\nその神秘性にひかれるのよ。",
  ui_story_5035_50350901_31_dialog_content = "そういうものなの？",
  ui_story_5035_50350901_32_dialog_content = "そうよ。このお屋敷、\n怪奇現象好きの心をワシづかみだわ！",
  ui_story_5035_50350901_33_dialog_content = "ニナさんに感謝しなくちゃ。\nきっとこれから大人気になるわよ！",
  ui_story_5035_50350901_34_dialog_content = "今日起こったことがすべて我々の仕掛けたものだと\n思っていらっしゃるのですか？",
  ui_story_5035_50350901_35_dialog_content = "えっ？",
  ui_story_5035_50350901_36_dialog_content = "確かに、ニナお嬢様はしかけを準備なさっていました。",
  ui_story_5035_50350901_37_dialog_content = "ただ…今夜私たちが経験した事件の多くは、\nお嬢様が準備していたものではないはずです。",
  ui_story_5035_50350901_38_dialog_content = "地下室の停電もですか？",
  ui_story_5035_50350901_39_dialog_content = "はい。すでに申し上げたことではございますが、\n地下室はゴーストハウスの営業に使われておりません。",
  ui_story_5035_50350901_40_dialog_content = "ただの事故かもしれませんよ？",
  ui_story_5035_50350901_41_dialog_content = "怪奇現象が起こる場所では、\n事故もよく起こるものですし！",
  ui_story_5035_50350901_42_dialog_content = "ええ、私もそのように思っておりました。",
  ui_story_5035_50350901_43_dialog_content = "説明しようのない出来事は、\n単なる事故や偶然と解釈するのがいちばん楽です。",
  ui_story_5035_50350901_44_dialog_content = "でしょう？それに私やPlayerNameの周りって、\nなぜか事故が起こってばっかりだし…",
  ui_story_5035_50350901_45_dialog_content = "ただ、つい先ほど、\n事故と考えてしまうと矛盾が起こることに気づいたのです。",
  ui_story_5035_50350901_46_dialog_content = "え？矛盾ですか？",
  ui_story_5035_50350901_47_dialog_content = "最新版の新聞で、ある記事を見かけたのです。\nご覧になりましたか？",
  ui_story_5035_50350901_48_dialog_content = "「ホラー映画の主演女優が謎の失踪」という…",
  ui_story_5035_50350901_49_dialog_content = "その記事、覚えてるよ！",
  ui_story_5035_50350901_50_dialog_content = "「尋ね人：B級ホラー映画の無名主演女優が謎の失踪」？",
  ui_story_5035_50350901_51_dialog_content = "影ノ街なら、そういう事件も起こりそうだけど…",
  ui_story_5035_50350901_52_dialog_content = "ヤラセじゃないの？",
  ui_story_5035_50350901_53_dialog_content = "実は…その映画というのが、\nヨハン様のクルーが撮っていた、前作なのです。",
  ui_story_5035_50350901_54_dialog_content = "え！？あたしの先輩ってこと？",
  ui_story_5035_50350901_55_dialog_content = "そうですね。ただ、当時はこの屋敷がまだお嬢様のものになっておらず、\nむろん、私も撮影には関わっておりません。",
  ui_story_5035_50350901_56_dialog_content = "記録に書かれていたことを見て、\nようやく知ったことです。",
  ui_story_5035_50350901_57_dialog_content = "で？主演女優はどうして失踪したの？",
  ui_story_5035_50350901_58_dialog_content = "分かりません。記録から映画の撮影に参加していたことが分かるだけで、\nそれ以上の事は書かれておりません。",
  ui_story_5035_50350901_59_dialog_content = "じゃあ、矛盾っていうのは？",
  ui_story_5035_50350901_60_dialog_content = "さきほど地下室で拾った\n「業務記録」を覚えていらっしゃいますか？",
  ui_story_5035_50350901_61_dialog_content = "あのノートに記録されていたのは、\nその前作の撮影の様子でした。",
  ui_story_5035_50350901_62_dialog_content = "つまり、失踪した女優さんが出ていた作品だね！",
  ui_story_5035_50350901_63_dialog_content = "そうです。その映画は撮影中止となっているのですが、\nおそらく主演女優の失踪と関係があるのでしょう。",
  ui_story_5035_50350901_64_dialog_content = "しかし、業務記録に書かれていた撮影日程を\n見直してみたところ…",
  ui_story_5035_50350901_65_dialog_content = "もし失踪事件がなければ、\n撮影完了の予定は今日だったのです。",
  ui_story_5035_50350901_66_dialog_content = "何かがおかしいことにお気づきになりましたか？",
  ui_story_5035_50350901_67_dialog_content = "時間がかみ合わないってこと？",
  ui_story_5035_50350901_68_dialog_content = "ええ。失踪した主演女優の家族や友人は、\n彼女はまだ映画の撮影中だと思っているはずです。",
  ui_story_5035_50350901_69_dialog_content = "主演女優の足取りは、普通は外部の者へは漏らしません。\n撮影スタッフも、女優の家族への連絡方法など知らされないでしょう。",
  ui_story_5035_50350901_70_dialog_content = "そして仮に事故などが起こったなら、「失踪」にはなりません。\nつまり、今日の時点で彼女が行方知れずであると、誰かが考えるはずはないのです。",
  ui_story_5035_50350901_71_dialog_content = "ううん、そう言われると、確かに…",
  ui_story_5035_50350901_72_dialog_content = "<color=#e8d9bb>パチパチパチ――</color>",
  ui_story_5035_50350901_73_dialog_content = "すごいわ！すばらしい推理ね！",
  ui_story_5035_50350901_74_dialog_content = "リリカ、いつ戻って来たの？現像は終わった？",
  ui_story_5035_50350901_75_dialog_content = "ええ、あとは乾くのを待つだけよ。",
  ui_story_5035_50350901_76_dialog_content = "それより、話を続けて。\n誰も知らないはずなのに、なんで失踪の記事が出たの？",
  ui_story_5035_50350901_77_dialog_content = "可能性は2つあります。",
  ui_story_5035_50350901_78_dialog_content = "撮影スタッフまたは女優自身が\n失踪の情報を新聞社に伝えたという可能性が１つ。",
  ui_story_5035_50350901_79_dialog_content = "そうよね、そのことを知ってる人は他にいないわ。",
  ui_story_5035_50350901_80_dialog_content = "それはそうだけど、よく考えてみてよ。\nそんなことをする理由は、どっちにもないと思うよ？",
  ui_story_5035_50350901_81_dialog_content = "出演者が失踪したなんてニュースになったら、\n撮影スタッフにとってはマズいでしょ。わざわざ新聞社に教えるかな？",
  ui_story_5035_50350901_82_dialog_content = "それに女優さん本人だとしても、\nどうして自分が行方不明だなんて情報を流す必要があるの？",
  ui_story_5035_50350901_83_dialog_content = "それは私も理解しがたいところです。\n今のところ、結論は出せておりません。",
  ui_story_5035_50350901_84_dialog_content = "ううん…女優本人って可能性は低いと思うわ。",
  ui_story_5035_50350901_85_dialog_content = "大した有名人でもないし、\n失踪したってニュースになっても大きな話題にならないわ。",
  ui_story_5035_50350901_86_dialog_content = "こういう記事ってお金を払って載せてもらうの。\n女優のタマゴじゃ、そんなお金出すのも大変でしょ。",
  ui_story_5035_50350901_87_dialog_content = "それなら、もう1つの可能性に絞って…\n撮影クルーが情報を流した目的を考えた方がいいんじゃない？",
  ui_story_5035_50350901_88_dialog_content = "撮影の関係者が情報を流したとすると…",
  ui_story_5035_50350901_89_dialog_content = "主演女優の失踪を記事にするのは、費用がかかるだけでなく、\n悪い話題になってしまう――どう考えても損しかありません。",
  ui_story_5035_50350901_90_dialog_content = "可能性があるとすれば、情報を流した結果、非常に重要な何かを得られ、\nそのような代償を払うに値するという場合…",
  ui_story_5035_50350901_91_dialog_content = "というと？",
  ui_story_5035_50350901_92_dialog_content = "その女優の行方を、非常に気にかけているといった事でしょうか。",
  ui_story_5035_50350901_93_dialog_content = "関係者が本当に心配して、\n見つけたいと思っているのかもしれません。",
  ui_story_5035_50350901_94_dialog_content = "<color=#e8d9bb>パチパチパチ――</color>",
  ui_story_5035_50350901_95_dialog_content = "すごいわ、確かに筋が通ってる！",
  ui_story_5035_50350901_96_dialog_content = "少なくとも、突破口は見つかったと言えるかもしれません。",
  ui_story_5035_50350901_97_dialog_content = "ですが、考えなければならないことはまだあります。\n例えば、なぜ主演女優を見つける必要があるのか？そもそもなぜ失踪したのか…",
  ui_story_5035_50350901_98_dialog_content = "<color=#e8d9bb>パチパチパチ――</color>",
  ui_story_5035_50350901_99_dialog_content = "拍手をありがとうございます。\nですが、今は思考の最中ですので…",
  ui_story_5035_50350901_100_dialog_content = "え、あたし？",
  ui_story_5035_50350901_101_dialog_content = "拍手なんてしてないわ？",
  ui_story_5035_50350901_102_dialog_content = "<color=#e8d9bb>パチパチパチ――</color>",
  ui_story_5035_50350901_103_dialog_content = "どなたでも、どうかお静かに…",
  ui_story_5035_50350901_104_dialog_content = "…",
  ui_story_5035_50350901_105_dialog_content = "…",
  ui_story_5035_50350901_106_dialog_content = "…",
  ui_story_5035_50350901_107_dialog_content = "<color=#e8d9bb>パチパチパチ…ガタン、ガタン――</color>",
  ui_story_5035_50350901_108_dialog_content = "外から聞こえてくるみたいだね。",
  ui_story_5035_50350901_109_dialog_content = "外に人がいるの？",
  ui_story_5035_50350901_110_dialog_content = "人だといいけど…",
  ui_story_5035_50350901_111_dialog_content = "<color=#e8d9bb>バンッ――</color>",
  ui_story_5035_50350901_112_dialog_content = "<color=#e8d9bb>ドカン――</color>",
  ui_story_5035_50350901_113_dialog_content = "<color=#e8d9bb>ガチャン！！！</color>",
  ui_story_5035_50350901_114_dialog_content = "グア！！！",
  ui_story_5035_50350901_115_dialog_content = "どうしてまた！？\nもう、うっとうしいわね！",
  ui_story_5035_50350901_116_dialog_content = "中に入れちゃダメよ！ミノスが言ってたでしょ。\n部屋の中の機材に触っちゃダメって！",
  ui_story_5035_50350901_117_dialog_content = "機材よりも、まずは自分の心配でしょ！？",
  ui_story_5035_50350901_118_dialog_content = "あたしは逃げられるけど、機材は逃げられないわ！",
  ui_story_5035_50350901_119_dialog_content = "なるほど、確かに…",
  ui_story_5035_50350901_120_dialog_content = "…とにかく、暗鬼を追い払わないと！",
  ui_story_5035_50351002_1_dialog_content = "ふぅ、ざっとこんなもんね！",
  ui_story_5035_50351002_2_dialog_content = "暗鬼が出てくるのも\n慣れてきちゃった気がするわ。",
  ui_story_5035_50351002_3_dialog_content = "だったらいっそ、ここに住んだらどう？\nミノスから1部屋借りればいいよ。",
  ui_story_5035_50351002_4_dialog_content = "そうだ、ミノスは？\n戦ってる時、見かけなかったけど。",
  ui_story_5035_50351002_5_dialog_content = "ミノスさん、暗鬼にはまったく興味がないみたいね…",
  ui_story_5035_50351002_6_dialog_content = "帳簿は…問題ない…",
  ui_story_5035_50351002_7_dialog_content = "賃貸契約にも…問題ない…",
  ui_story_5035_50351002_8_dialog_content = "そんなはずがない、必ずどこかにおかしな点が…\nもう1度…",
  ui_story_5035_50351002_9_dialog_content = "うわ、床が書類だらけね。",
  ui_story_5035_50351002_10_dialog_content = "書類の中に埋もれるのが趣味なの？",
  ui_story_5035_50351002_11_dialog_content = "撮影スタッフの信用情報をチェックしているのです。",
  ui_story_5035_50351002_12_dialog_content = "運営に何か問題があるようならば、\n即刻契約を停止しなければなりません。",
  ui_story_5035_50351002_13_dialog_content = "お嬢様の事業には、1つの汚点もあってはなりませんから。",
  ui_story_5035_50351002_14_dialog_content = "すごい責任感ね。",
  ui_story_5035_50351002_15_dialog_content = "ここにあるのはすべて、撮影関連の書類です。",
  ui_story_5035_50351002_16_dialog_content = "おそらくですが、これは単に\n主演女優が失踪したと言うだけの話ではありません。",
  ui_story_5035_50351002_17_dialog_content = "必ずもっと大きな原因と結果があるはず…",
  ui_story_5035_50351002_18_dialog_content = "その原因と結果につながる糸が、\nこの書類の中にあるはずです。",
  ui_story_5035_50351002_19_dialog_content = "その糸こそ真相に近づく鍵です。\n必ず見つけなくては。",
  ui_story_5035_50351002_20_dialog_content = "それにしたって…\nこの書類の量、多すぎるんじゃない？",
  ui_story_5035_50351002_21_dialog_content = "こんなにたくさんの字を見るのは、\n生まれて初めてだわ。",
  ui_story_5035_50351002_22_dialog_content = "すでに一通り目を通しておりますが、\nおかしなところが見つからないのです。",
  ui_story_5035_50351002_23_dialog_content = "もう！？",
  ui_story_5035_50351002_24_dialog_content = "あ、あたし、字を読むのは苦手だから、\n邪魔しないようにするわ。",
  ui_story_5035_50351002_25_dialog_content = "ちょうど現像した写真も乾く頃だし、\nそっちを見てくる。",
  ui_story_5035_50351002_26_dialog_content = "道具リスト…購入記録…契約書…",
  ui_story_5035_50351002_27_dialog_content = "…写真？",
  ui_story_5035_50351002_28_dialog_content = "写真…写真…",
  ui_story_5035_50351002_29_dialog_content = "そうです、写真です！！！",
  ui_story_5035_50351002_30_dialog_content = "ミノス、どうしたの！？ビックリしたよ。",
  ui_story_5035_50351002_31_dialog_content = "私はなんと頭が固いのでしょう…",
  ui_story_5035_50351002_32_dialog_content = "目を通した書類には、確かに何も異常はありません。",
  ui_story_5035_50351002_33_dialog_content = "ならば、異常は私が見ていないものの中にあったのです。",
  ui_story_5035_50351002_34_dialog_content = "え？じゃあ、それって？",
  ui_story_5035_50351002_35_dialog_content = "スチル写真です。",
  ui_story_5035_50351002_36_dialog_content = "必ず撮って記録にするというものではないので、\n見落としていました。",
  ui_story_5035_50351002_37_dialog_content = "とはいえ、映画撮影を行うのであれば、\n通常は記念や宣伝用として、多くの写真を撮るものです。",
  ui_story_5035_50351002_38_dialog_content = "しかし、この中にはそれが1枚もありません。",
  ui_story_5035_50351002_39_dialog_content = "そりゃヘンだね。\n今日の監督だって、あたしも入れて写真を撮ってたよ。",
  ui_story_5035_50351002_40_dialog_content = "今回撮ってるってことは、\n今までだって撮ってたはずじゃない？",
  ui_story_5035_50351002_41_dialog_content = "「撮った」が「残っていない」ということは考えられます。",
  ui_story_5035_50351002_42_dialog_content = "他人に見られたくない写真ということも…",
  ui_story_5035_50351002_43_dialog_content = "写真、できたよ！！",
  ui_story_5035_50351002_44_dialog_content = "なかなかうまく撮れてるわ。\n見てみたい？",
  ui_story_5035_50351002_45_dialog_content = "え、今？",
  ui_story_5035_50351002_46_dialog_content = "ちょうど手がかりになりそうなものが見つかったところだし、\n写真を見るような気分じゃ…",
  ui_story_5035_50351002_47_dialog_content = "もう、そんなにピリピリしてても仕方ないでしょ！",
  ui_story_5035_50351002_48_dialog_content = "気分転換すれば、頭がスッキリするかもよ？",
  ui_story_5035_50351002_49_dialog_content = "ほらほら、みんな寄って。",
  ui_story_5035_50351002_50_dialog_content = "サディの顔、すごい得意げね！",
  ui_story_5035_50351002_51_dialog_content = "うるさいな…",
  ui_story_5035_50351002_52_dialog_content = "執事さん、次はちゃんとカメラを見てね！",
  ui_story_5035_50351002_53_dialog_content = "おや…？",
  ui_story_5035_50351002_54_dialog_content = "バイスとPlayerNameはいい感じね～。\n俳優の素質ありよ！",
  ui_story_5035_50351002_55_dialog_content = "俳優の素質って、そんな簡単に決まるの！？",
  ui_story_5035_50351002_56_dialog_content = "ただの写真よ。\n俳優だなんて、そんな…",
  ui_story_5035_50351002_57_dialog_content = "…待って！ねえ、私たちって…全部で5人よね？",
  ui_story_5035_50351002_58_dialog_content = "1、2、3、4、5…そうね、5人よ？",
  ui_story_5035_50351002_59_dialog_content = "この写真…手が1本多くない…？",
  ui_story_5035_50351002_60_dialog_content = "！！！",
  ui_story_5035_50351002_61_dialog_content = "ほ、ホントだ！\n誰のか分からない手が1本写ってる！",
  ui_story_5035_50351002_62_dialog_content = "え？え！？ええええ！？",
  ui_story_5035_50351002_63_dialog_content = "…断言しても構いません。\n地下室には私たち以外、誰もおりませんでした。",
  ui_story_5035_50351002_64_dialog_content = "うん、僕もそう思う。\nでも、この写真に写ってるのって…",
  ui_story_5035_50351002_65_dialog_content = "写真…スチル…",
  ui_story_5035_50351002_66_dialog_content = "まさか、写真が残っていない理由は、これなのでしょうか？",
  ui_story_5035_50351002_67_dialog_content = "PlayerName、今、ふと思い出したんだけど…",
  ui_story_5035_50351002_68_dialog_content = "バーバ・ヤーガが言ってたこと、覚えてる…？",
  ui_story_5035_50351002_69_dialog_content = "PlayerName――\n<color=#FFB400>あの子</color>とは、一緒じゃないのねぇ。",
  ui_story_5035_50351002_70_dialog_content = "私たちの方が先に<color=#FFB400>彼女</color>と\n知り合えたってことかしらぁ？",
  ui_story_5035_50351002_71_dialog_content = "<color=#FFB400>彼女のトリコにならないように、\n気をつけなさいねぇ…</color>",
  ui_story_5035_50351002_72_dialog_content = "だって、<color=#FFB400>彼女を「宴」に引きずりこめる</color>のは、\n私しかいないんだからぁ。",
  ui_story_5035_50351002_73_dialog_content = "うん、覚えてるよ。",
  ui_story_5035_50351002_74_dialog_content = "「彼女」が誰か考えてみたけど、\n思い当たる人がいないわ。",
  ui_story_5035_50351002_75_dialog_content = "今思えば、「彼女」って…",
  ui_story_5035_50351002_76_dialog_content = "「彼女のトリコにならないように、気をつけてねえ…」",
  ui_story_5035_50351002_77_dialog_content = "バーバ・ヤーガ、忠告してくれてたのね…",
  ui_story_5035_50351002_78_dialog_content = "この屋敷に、私たちの知らない何かが潜んでる…",
  ui_story_5035_50351002_79_dialog_content = "背後に現れるであろう「女の幽霊」に気をつけろって…",
  ui_story_5035_50351101_1_dialog_content = "（幽霊の存在…信じるべきなのかな？）",
  ui_story_5035_50351101_2_dialog_content = "（何かのついでに考えてみたことは何度もあるけど…）",
  ui_story_5035_50351101_3_dialog_content = "（ヒマつぶしみたいなものだったし、\n自分では答えを出せない、証明もできない問題だった）",
  ui_story_5035_50351101_4_dialog_content = "（それが突然、空に浮かんでた雲が戦士の姿になって、\n目の前に立ちはだかってるみたいに…）",
  ui_story_5035_50351101_5_dialog_content = "（急に距離を詰められて、\n今はすぐそこに写真の幽霊がいるような気さえする）",
  ui_story_5035_50351101_6_dialog_content = "（恐怖で身も心も固まらないうちに、\n何か質問して、早く抜け出さなきゃ…）",
  ui_story_5035_50351101_7_dialog_content = "この世には本当に…",
  ui_story_5035_50351101_8_dialog_content = "やっぱり、思った通りだわ！\nこのお屋敷には本当に幽霊がいるのよ！",
  ui_story_5035_50351101_9_dialog_content = "えっ…",
  ui_story_5035_50351101_10_dialog_content = "この写真が決定的証拠になるわ！",
  ui_story_5035_50351101_11_dialog_content = "さすがはオバケハンターチームね！\nこんな簡単に目的を達成しちゃうなんて！",
  ui_story_5035_50351101_12_dialog_content = "さ、クルーとカタをつけに行くわよ！",
  ui_story_5035_50351101_13_dialog_content = "ちょっと待った、もう少し考えてからにしなよ。\nだって、幽霊なんて…",
  ui_story_5035_50351101_14_dialog_content = "あと、「クルーとカタをつける」って？",
  ui_story_5035_50351101_15_dialog_content = "故意にスチル写真を隠していたということは、\n関係者はおそらく、幽霊の存在を知っていたのでしょう。",
  ui_story_5035_50351101_16_dialog_content = "しかし、それもただの推測です。\n今はまだ「女の幽霊」と「撮影クルー」を結びつける証拠はありません。",
  ui_story_5035_50351101_17_dialog_content = "むやみに動いては相手を警戒させるだけ…\n衝動的な行動は控えたほうがよろしいのでは？",
  ui_story_5035_50351101_18_dialog_content = "ふふん！今ある手がかりだけじゃ、\n「女の幽霊」と「撮影クルー」は結びつけられないけど…",
  ui_story_5035_50351101_19_dialog_content = "そこに失踪した主演女優がいるなら、どう？",
  ui_story_5035_50351101_20_dialog_content = "<color=#e8d9bb>ベリッ――</color>",
  ui_story_5035_50351101_21_dialog_content = "ジャジャジャジャーン！\nこれがあたしの正体よ！",
  ui_story_5035_50351101_22_dialog_content = "…何も変わってないけど…",
  ui_story_5035_50351101_23_dialog_content = "むしろ、ずっと聞きたかったんだよ。\nそのヘンなヒゲ、何のためにつけてるのかって。",
  ui_story_5035_50351101_24_dialog_content = "いや、それより…\n今、なんて言った？失踪した主演女優！？",
  ui_story_5035_50351101_25_dialog_content = "そうよ！「謎の失踪をとげた、B級ホラー映画の、無名の主演女優」…\nそれがこのあたし、リリカなの！",
  ui_story_5035_50351101_26_dialog_content = "え！？",
  ui_story_5035_50351101_27_dialog_content = "えっ？",
  ui_story_5035_50351101_28_dialog_content = "えっ…？",
  ui_story_5035_50351101_29_dialog_content = "それなら話は早いですね。ぜひ教えてください。\n失踪とは、どういうわけですか？",
  ui_story_5035_50351101_30_dialog_content = "話の始まりは、あたしが出演したヨハン監督の前作のホラー映画よ。",
  ui_story_5035_50351101_31_dialog_content = "あたし、小さい頃から映画が好きで、\n特にホラー映画が大好きだったの。",
  ui_story_5035_50351101_32_dialog_content = "だから、監督に新作映画に出てくれって言われた時は、\nすっごく嬉しかったわ。",
  ui_story_5035_50351101_33_dialog_content = "撮影場所は――\nみんなも知っての通り、このお屋敷よ。",
  ui_story_5035_50351101_34_dialog_content = "最初は順調に撮影が進んでたけど、\n地下室のシーンを撮る時に…事件が起こったの。",
  ui_story_5035_50351101_35_dialog_content = "事件？",
  ui_story_5035_50351101_36_dialog_content = "現場が大混乱になったわ。\n最初は水滴の落ちる音と鈴の音が聞こえて…",
  ui_story_5035_50351101_37_dialog_content = "あ、そうだ、それからロウソクも。\nなぜか地下室に、ロウソクが置かれてたのよ。",
  ui_story_5035_50351101_38_dialog_content = "そのすぐ後、何かが現われて、はっきり見えなかったけど…\n人じゃなかったのは確かね。",
  ui_story_5035_50351101_39_dialog_content = "その人ならざる何かが、あたしを殺そうとしたの。\nとっても強い、殺気を感じたわ。",
  ui_story_5035_50351101_40_dialog_content = "襲われて、大ケガしたあたしは、\n1度はこのまま地下室で死ぬんだとまで思ったけど…",
  ui_story_5035_50351101_41_dialog_content = "まぁ、小さい頃から逃げるのは得意だったから。",
  ui_story_5035_50351101_42_dialog_content = "夜の闇の中を長いこと走って、\nようやく影ノ街まで帰ってきたところで…お医者さんが助けてくれたの。",
  ui_story_5035_50351101_43_dialog_content = "診療所で2日間眠ってたらしいわ。\n危ないところを過ぎて、目が覚めたの。",
  ui_story_5035_50351101_44_dialog_content = "そんなことがあったんだ…大変だったね。",
  ui_story_5035_50351101_45_dialog_content = "それで地下室では急に、\n僕にカメラを持たせたんだね…",
  ui_story_5035_50351101_46_dialog_content = "そういうことよ。もしまた事件が起こったら、\n少なくともカメラに記録が残って、真実を解明できるでしょ？",
  ui_story_5035_50351101_47_dialog_content = "よくそんな場所に戻って来たね。\nあんた、度胸あるよ。",
  ui_story_5035_50351101_48_dialog_content = "あたしだったら、一生ここには近づかないかな。",
  ui_story_5035_50351101_49_dialog_content = "あたしだって最初は戻りたいと思わなかったわ。\nあんな恐ろしい体験、二度もしたくないもの。",
  ui_story_5035_50351101_50_dialog_content = "でも、すぐにおかしな話を聞いたの。\nヨハン監督のクルーが同じ屋敷で撮影するって。",
  ui_story_5035_50351101_51_dialog_content = "…確かにおかしいよね。\nそんな大きな事件があったのに…",
  ui_story_5035_50351101_52_dialog_content = "そのすぐ後に、新聞であの「尋ね人」の記事を見たのよ。",
  ui_story_5035_50351101_53_dialog_content = "…",
  ui_story_5035_50351101_54_dialog_content = "それで、貴方も私と同じ結論に達したというわけですね。",
  ui_story_5035_50351101_55_dialog_content = "あるいは、私のさきほどの推理は\n貴方に誘導されていたと言ったほうがよいでしょうか。",
  ui_story_5035_50351101_56_dialog_content = "ううん…女優本人って可能性は低いと思うわ。",
  ui_story_5035_50351101_57_dialog_content = "それなら、もう1つの可能性に絞って…\n撮影クルーが情報を流した目的を考えた方がいいんじゃない？",
  ui_story_5035_50351101_58_dialog_content = "ふふふ、誘導じゃないわ！\n間違った方向へ推理しないように、手伝っただけよ。",
  ui_story_5035_50351101_59_dialog_content = "あの時ずいぶん考えて…\nおかしな行動の理由について、恐ろしい推測に突き当たったの。",
  ui_story_5035_50351101_60_dialog_content = "つまり、このお屋敷には本当に幽霊がいる。\nそして、撮影クルーはそのことを知っている…",
  ui_story_5035_50351101_61_dialog_content = "クルーたちが見つけたっていう撮影場所は、\n本当にオバケの出る所だったってね。",
  ui_story_5035_50351101_62_dialog_content = "そんな…じゃあ、そんなことをする目的は…？",
  ui_story_5035_50351101_63_dialog_content = "何も知らないあたしをまんまとだまして、\n「ホンモノ」のホラー映画を撮影しようとしたのよ。",
  ui_story_5035_50351101_64_dialog_content = "人の手で演出した恐怖なんて、\nどんなによくできていようと、本当の恐怖にはかなわないものよ。",
  ui_story_5035_50351101_65_dialog_content = "だから、最高のホラーを撮るためなら、\n手段を選ばないってこと。",
  ui_story_5035_50351101_66_dialog_content = "「ホンモノ」のホラー…",
  ui_story_5035_50351101_67_dialog_content = "じゃあ、失踪の記事を出したのは、\n君に戻って来てもらって、映画を完成させるため？",
  ui_story_5035_50351101_68_dialog_content = "ええ、きっとそうに違いないわ。",
  ui_story_5035_50351101_69_dialog_content = "あの時の撮影は終盤に入ってたから、残りを撮り終えなきゃ、\nそれまで撮った分が全部ムダになっちゃうでしょ。",
  ui_story_5035_50351101_70_dialog_content = "でも結局、あたしを見つけられなくて、\n今はキャストを集めなおして、初めから撮り直してるってことじゃない？",
  ui_story_5035_50351101_71_dialog_content = "それでこの仕事が回ってきたんだ…\n助かったよ、あんたがいなきゃあたしが…",
  ui_story_5035_50351101_72_dialog_content = "お礼なんて、いいのいいの～。",
  ui_story_5035_50351101_73_dialog_content = "で、話を戻すと、こんな陰謀を知った以上、\nおとなしくしてるワケにはいかないわ！",
  ui_story_5035_50351101_74_dialog_content = "それで向こうの裏をかいて、\nクルーの出した記事通り、本当に失踪してあげたのよ。",
  ui_story_5035_50351101_75_dialog_content = "それで陰謀をあばくことにしたの。\n他にもあたしと同じ被害に遭う人が出ないように。",
  ui_story_5035_50351101_76_dialog_content = "あ…ってことは、次の被害者、あたしと…ゴルディ？",
  ui_story_5035_50351101_77_dialog_content = "<anim type=Shake><size=45>あんた</size>の<size=45>第一印象</size>、<size=50>疫病神</size>、\n<size=45>ほんと</size>は<size=45>命の恩人</size>、<size=45>幸運の女神</size>♪</anim>",
  ui_story_5035_50351101_78_dialog_content = "ふふん！そうよ。\nあたしをだました人たちに思い知らせてあげなくちゃ。",
  ui_story_5035_50351101_79_dialog_content = "十分な手がかりさえつかめれば、\n事件を公にできるわ。",
  ui_story_5035_50351101_80_dialog_content = "それであたしは、変装して潜入することにしたの！",
  ui_story_5035_50351101_81_dialog_content = "「変装して潜入」って…",
  ui_story_5035_50351101_82_dialog_content = "なによ、ちゃんとうまくいったでしょ？",
  ui_story_5035_50351101_83_dialog_content = "この心霊写真があれば、あたしの推測も立証できるわ！",
  ui_story_5035_50351101_84_dialog_content = "さあ、決着を付けにいかないと！\n良心の欠片もない撮影クルーをこらしめて、映画界を浄化するのよ！",
  ui_story_5035_50351101_85_dialog_content = "みんなも一緒に来る？",
  ui_story_5035_50351101_86_dialog_content = "むろん、そのような事実を隠していたとあらば、\n私どもの契約も解消せねばなりません。",
  ui_story_5035_50351101_87_dialog_content = "「アンデルセンのゴーストハウス」としては、\nそのような方々のご来場など、お断りでございます。",
  ui_story_5035_50351101_88_dialog_content = "他人を犠牲に映画撮る、そんなクズどもぶっ飛ばす！",
  ui_story_5035_50351101_89_dialog_content = "私たちにこんな怖い思いをさせて…\n絶対に許さないわ！",
  ui_story_5035_50351101_90_dialog_content = "そうだ！許すわけにはいかない！",
  ui_story_5035_50351101_91_dialog_content = "<color=#e8d9bb>ドスン――</color>",
  ui_story_5035_50351101_92_dialog_content = "<color=#e8d9bb>ドスン――</color>",
  ui_story_5035_50351101_93_dialog_content = "な、何だぁ！？",
  ui_story_5035_50351101_94_dialog_content = "<color=#e8d9bb>ドスン――</color>",
  ui_story_5035_50351101_95_dialog_content = "足音か…ずいぶん威勢がいいじゃねぇか…",
  ui_story_5035_50351101_96_dialog_content = "こんな夜遅くにデカい足音たてて、何するってぇんだ？\n屋敷を壊すつもりか？",
  ui_story_5035_50351101_97_dialog_content = "<color=#e8d9bb>ドスン――</color>",
  ui_story_5035_50351101_98_dialog_content = "おどかしに行くか？",
  ui_story_5035_50351101_99_dialog_content = "やっぱり様子見てからにするか…？",
  ui_story_5035_50351101_100_dialog_content = "グアアア――",
  ui_story_5035_50351101_101_dialog_content = "ん？ほ…本物の暗鬼か？",
  ui_story_5035_50351101_102_dialog_content = "すまねえすまねえ、ジャマしたな…",
  ui_story_5035_50351101_103_dialog_content = "まったく、契約と全然違うじゃねえか。\n金をかせぐってのは、大変なもんだな…",
  ui_story_5035_50351101_104_dialog_content = "グアア！！",
  ui_story_5035_50351101_105_dialog_content = "うおっ！？な、なんだ！？",
  ui_story_5035_50351101_106_dialog_content = "いったい何が近づいて来てんだ？暗鬼か？",
  ui_story_5035_50351101_107_dialog_content = "<color=#e8d9bb>ドン！！</color>",
  ui_story_5035_50351101_108_dialog_content = "ジャマよ、うっとうしいわね！",
  ui_story_5035_50351101_109_dialog_content = "今、気が立ってるの！",
  ui_story_5035_50351101_110_dialog_content = "え！？おい、お前、俺は…",
  ui_story_5035_50351101_111_dialog_content = "あっち行って！！",
  ui_story_5035_50351101_112_dialog_content = "うおっ――！？",
  ui_story_5035_50351102_1_dialog_content = "<color=#e8d9bb>ガラン…ガラン…</color>",
  ui_story_5035_50351102_2_dialog_content = "上の階、なんだか騒がしゅうござんすね。",
  ui_story_5035_50351102_3_dialog_content = "ああ、確かにな。",
  ui_story_5035_50351102_4_dialog_content = "客じゃないか？\n怖がってりゃ騒いでてもおかしくねぇだろ。",
  ui_story_5035_50351102_5_dialog_content = "そりゃ、うらやましいことでござんすなぁ。\nあたしも客なら、どれだけ気がラクか。",
  ui_story_5035_50351102_6_dialog_content = "何言ってやがんだ。\n俺たちは金を稼ぎにきたんだろうが。",
  ui_story_5035_50351102_7_dialog_content = "考え事してねぇで、さっさと道具を入口まで運んじまおう。\n監督が待ってるぞ。",
  ui_story_5035_50351102_8_dialog_content = "<color=#e8d9bb>ガラン…ガラン…</color>",
  ui_story_5035_50351102_9_dialog_content = "聞いたところによると、\nこの屋敷にゃ本物の幽霊が出るって話ざんすよ。",
  ui_story_5035_50351102_10_dialog_content = "そりゃそうでも言わなきゃ、\n客なんか来ねぇだろうな。",
  ui_story_5035_50351102_11_dialog_content = "いやいや、本当のことかも知れやせん。\n何だか、ずっと気味が悪りぃんでござんす。",
  ui_story_5035_50351102_12_dialog_content = "まるで…何かにずっとつけられてるみてぇな…",
  ui_story_5035_50351102_13_dialog_content = "そんなヒマと体力のあるヤツはいねーだろ。",
  ui_story_5035_50351102_14_dialog_content = "本当に聞いたことねぇんですか？最初にこの屋敷を造った人は、\n汚らわしいモンが命を奪いに来るっちゅうて、怖がっとったらしいんざんす。",
  ui_story_5035_50351102_15_dialog_content = "その汚らわしいモンってやつが、人違いでもしたら…",
  ui_story_5035_50351102_16_dialog_content = "あなたたち――",
  ui_story_5035_50351102_17_dialog_content = "ひぃっ！！",
  ui_story_5035_50351102_18_dialog_content = "こ、来ないでくだせぇ！あ、あたしじゃありやせん！",
  ui_story_5035_50351102_19_dialog_content = "待ちなさい！",
  ui_story_5035_50351102_20_dialog_content = "ありゃ？生身の人でござんしたか。",
  ui_story_5035_50351102_21_dialog_content = "良心の欠片もない撮影クルーどもめ！",
  ui_story_5035_50351102_22_dialog_content = "陰謀はもうあばかれたのよ！",
  ui_story_5035_50351102_23_dialog_content = "自分たちの趣味の悪い欲望を満たすために、\n出演者をだまして、命の危険にさらすなんて！",
  ui_story_5035_50351102_24_dialog_content = "本当に…本当に…",
  ui_story_5035_50351102_25_dialog_content = "…極悪非道、言語道断。",
  ui_story_5035_50351102_26_dialog_content = "そう、それ！極悪非道、言語道断！",
  ui_story_5035_50351102_27_dialog_content = "さっきちゃんと覚えたって言ってたのに、\n一番肝心なところで詰まっちゃった…",
  ui_story_5035_50351102_28_dialog_content = "ミ、ミノスが悪いのよ！\n難しい言葉ばかり使うんだから！",
  ui_story_5035_50351102_29_dialog_content = "「学がある感じのセリフ」がいいと、\nおっしゃっておりましたので…",
  ui_story_5035_50351102_30_dialog_content = "もう、そんなことはどうでもいいの！",
  ui_story_5035_50351102_31_dialog_content = "とにかく！あたしをあんなヒドイ目に遭わせておきながら、\nまた別の人を被害者にしようっていうの！？",
  ui_story_5035_50351102_32_dialog_content = "このお屋敷には本物の幽霊がいるって証明する、\n十分な証拠を持ってるのよ！",
  ui_story_5035_50351102_33_dialog_content = "のこのこ戻ってきて撮影を続けるなんて、\n幽霊の存在を知ったうえで、それを利用しようとしてる証拠だわ！",
  ui_story_5035_50351102_34_dialog_content = "思うようにはさせないわよ！\n明日にはシャドウマスターに制裁してもらうわ、覚悟しなさい！",
  ui_story_5035_50351102_35_dialog_content = "でもその前に、あたしが1発お見舞いしてあげる！",
  ui_story_5035_50351102_36_dialog_content = "被害者の怒りを思い知りなさい！！",
  ui_story_5035_50351102_37_dialog_content = "制裁！？一発お見舞い！？\nて、ててててえへんでござんす！？",
  ui_story_5035_50351102_38_dialog_content = "ふん、今さら後悔しても遅いわ！",
  ui_story_5035_50351102_39_dialog_content = "堪忍しておくんなまし！",
  ui_story_5035_50351102_40_dialog_content = "…おい、1つ聞いてもいいか？",
  ui_story_5035_50351102_41_dialog_content = "おまえ、誰だ？",
  ui_story_5035_50351102_42_dialog_content = "何ですって？\nあたしが誰か分からないの？前に…",
  ui_story_5035_50351102_43_dialog_content = "…あら？待って。",
  ui_story_5035_50351102_44_dialog_content = "あなたたち…",
  ui_story_5035_50351102_45_dialog_content = "誰！？",
  ui_story_5035_50351102_X45_dialog_content = "あ！君たちは…",
  ui_story_5035_50351102_X46_dialog_content = "知り合い？",
  ui_story_5035_50351102_X47_dialog_content = "レスターとコンスタン！",
  ui_story_5035_50351102_X48_dialog_content = "おや、こりゃあPlayerNameのダンナ。",
  ui_story_5035_50351102_X49_dialog_content = "このお化け屋敷、大人気みたいだな。",
  ui_story_5035_50351102_X50_dialog_content = "どうして映画の撮影なんてやってるの？\nどういうこと？",
  ui_story_5035_50351102_46_dialog_content = "えっ？？？",
  ui_story_5035_50351102_47_dialog_content = "こっちの方が聞きてぇぜ、いきなり好き放題言いやがって。\n俺たちはおまえのことなんか知らんぞ。",
  ui_story_5035_50351102_48_dialog_content = "どういうこと？\n前は一緒に撮影してたんじゃないの？",
  ui_story_5035_50351102_49_dialog_content = "ごめんなさい、人違いだったわ！\nてっきり撮影クルーだと思って。",
  ui_story_5035_50351102_50_dialog_content = "ほんと～にごめんなさい！",
  ui_story_5035_50351102_51_dialog_content = "何を言ってんです？撮影クルーではござんすよ。\nクビになっちゃいねぇはずですがねぇ…？",
  ui_story_5035_50351102_52_dialog_content = "道具運びなんざ、雇われてるんでもなきゃ誰がやるか。",
  ui_story_5035_50351102_53_dialog_content = "道具？",
  ui_story_5035_50351102_54_dialog_content = "<color=#e8d9bb>ガラン…ガラン…</color>",
  ui_story_5035_50351102_55_dialog_content = "あれ、鈴のついた…棺？",
  ui_story_5035_50351102_56_dialog_content = "そうでござんす。ホラー映画の撮影っちゅうのは、\n何から何までまったく気味悪うござんすね。",
  ui_story_5035_50351102_57_dialog_content = "こいつはカチンコ担当、俺はカメラマンだ。",
  ui_story_5035_50351102_58_dialog_content = "俺たちが撮影スタッフだってことと、\nおまえを知らねぇってことは、別に矛盾しないだろ？",
  ui_story_5035_50351102_59_dialog_content = "え？でも、あの時の2人は…",
  ui_story_5035_50351102_60_dialog_content = "どういうこと？人が変わったの？",
  ui_story_5035_50351102_61_dialog_content = "この仕事に就いたのは最近でござんすね。\nだからといって、甘く見ねぇでいただきたいもんです…",
  ui_story_5035_50351102_62_dialog_content = "まずい…！",
  ui_story_5035_50351102_63_dialog_content = "ど、どうしたの？",
  ui_story_5035_50351102_64_dialog_content = "撮影クルーが変わったのなら、\n以前の皆様はどこへ行かれたのですか？",
  ui_story_5035_50351102_65_dialog_content = "えっ…",
  ui_story_5035_50351102_66_dialog_content = "<color=#e8d9bb>ガチャリ…</color>",
  ui_story_5035_50351102_67_dialog_content = "！！！",
  ui_story_5035_50351102_68_dialog_content = "<color=#e8d9bb>ガチャン――！</color>",
  ui_story_5035_50351102_69_dialog_content = "<color=#e8d9bb>カチリ…</color>",
  ui_story_5035_50351102_70_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5035_50351102_71_dialog_content = "<color=#e8d9bb>ガシャン！！！</color>",
  ui_story_5035_50351102_72_dialog_content = "何の音？\nいったい何が起こってるの…？",
  ui_story_5035_50351102_73_dialog_content = "ドアの閉まる音だ…\n部屋のドア、全部閉められた。",
  ui_story_5035_50351102_74_dialog_content = "あたしたちを閉じ込めるつもりだ。",
  ui_story_5035_50351102_75_dialog_content = "誰がそんなことを…",
  ui_story_5035_50351102_76_dialog_content = "リリカ、リリカ…",
  ui_story_5035_50351102_77_dialog_content = "できそこないの「主演女優」君。",
  ui_story_5035_50351102_78_dialog_content = "やっと見つけたよ。",
  ui_story_5035_50351102_79_dialog_content = "（ヨハン監督の声だ…不気味に響いてくる。）",
  ui_story_5035_50351102_80_dialog_content = "（上の階の階段の手すり近くに立つ監督と、天井越しに目が合った）",
  ui_story_5035_50351102_81_dialog_content = "（高低差のせいか、視線が重くのしかかってくる）",
  ui_story_5035_50351102_82_dialog_content = "（その迫力で周りの空気が、まるで固まったみたいだ。\n歯と歯のこすれ合う音がかすかに聞こえる以外は…）",
  ui_story_5035_50351102_83_dialog_content = "ヨハン…監督。",
  ui_story_5035_50351102_84_dialog_content = "実のところ、君の演技はなかなかだよ。",
  ui_story_5035_50351102_85_dialog_content = "このあいだ撮影したモノ、私はとても気に入っているんだ。\n今までのどの作品よりもすばらしい。",
  ui_story_5035_50351102_86_dialog_content = "だが、残念なことに君は失格だ。\n俳優として必要な素質が欠けている。",
  ui_story_5035_50351102_87_dialog_content = "最後まで<color=#FFB400>演じ切る</color>ことができないのではね。",
  ui_story_5035_50351102_88_dialog_content = "あたしを探し回ってたのは、映画を完成させるため？",
  ui_story_5035_50351102_89_dialog_content = "いいや。",
  ui_story_5035_50351102_90_dialog_content = "君が逃げ出した瞬間、\nあの映画は二度と表に出せなくなってしまった。",
  ui_story_5035_50351102_91_dialog_content = "無理矢理つなぎ合わせたところで、俗な作品に成り下がるだけだ。\n私が欲しいのは、そんなものじゃない。",
  ui_story_5035_50351102_92_dialog_content = "君を探していたのは別の目的のためさ。",
  ui_story_5035_50351102_93_dialog_content = "教えてくれないか。\n君はあの暗闇の中で何を、どのぐらい見た？",
  ui_story_5035_50351102_94_dialog_content = "多くを見すぎてしまった者に、\nしゃべってもらっては困るのでね。",
  ui_story_5035_50351102_95_dialog_content = "しゃべってもらったら困る？\nどういう…",
  ui_story_5035_50351102_96_dialog_content = "監督、監督！",
  ui_story_5035_50351102_97_dialog_content = "もう、ここにいたのね。\nずいぶん探したんだから！",
  ui_story_5035_50351102_98_dialog_content = "脚本を読んでたんだけど、\nこのシーンのセリフ、ちょっと相談できないかしら…",
  ui_story_5035_50351102_99_dialog_content = "どのシーンだい？どれどれ…",
  ui_story_5035_50351102_100_dialog_content = "ここよ…",
  ui_story_5035_50351102_101_dialog_content = "マズい、ゴルディは事情を知らない！",
  ui_story_5035_50351102_102_dialog_content = "近寄っちゃダメ！！",
  ui_story_5035_50351102_103_dialog_content = "えっ？なに…",
  ui_story_5035_50351102_104_dialog_content = "シーッ――",
  ui_story_5035_50351102_105_dialog_content = "君はこれでオールアップだ。",
  ui_story_5035_50351102_106_dialog_content = "ゴルディ…！？",
  ui_story_5035_50351102_107_dialog_content = "あっ…！！！",
  ui_story_5035_50351201_1_dialog_content = "ゴルディが…殺された！？",
  ui_story_5035_50351201_2_dialog_content = "…",
  ui_story_5035_50351201_3_dialog_content = "やはり、そうでしたか。",
  ui_story_5035_50351201_4_dialog_content = "貴方にとっては、\nもう1人多く殺したところで、何も変わらない…",
  ui_story_5035_50351201_5_dialog_content = "前回の撮影クルーも全員、\n犠牲にしたということですね。",
  ui_story_5035_50351201_6_dialog_content = "全員…",
  ui_story_5035_50351201_7_dialog_content = "面白いことを言うね、プロデューサー君。\nなぜそう思うんだ？",
  ui_story_5035_50351201_8_dialog_content = "リリカ様はクルー全員が関わっていると思っていらっしゃるようですが、\nそれは間違いでした。",
  ui_story_5035_50351201_9_dialog_content = "全ては最初から最後まで、監督1人の陰謀だったのです。",
  ui_story_5035_50351201_10_dialog_content = "撮影クルーに関する書類には、\nスチル写真が1枚もありませんでした。",
  ui_story_5035_50351201_11_dialog_content = "「幽霊」の存在を隠すためだとばかり思っていましたが…",
  ui_story_5035_50351201_12_dialog_content = "今思えば、貴方が隠そうとしていたのは幽霊ではなく…",
  ui_story_5035_50351201_13_dialog_content = "スチル写真に写っていた、\nスタッフ全員の存在だったのですね。",
  ui_story_5035_50351201_14_dialog_content = "スタッフの入れ替え記録は書き換えられますが、\n写真まではごまかしが効きません。",
  ui_story_5035_50351201_15_dialog_content = "人員が異常に入れ替わっているという、\n実態があらわになってしまいます。",
  ui_story_5035_50351201_16_dialog_content = "すなわち、撮影のたびにスタッフ全員、\n殺されているという事実が…",
  ui_story_5035_50351201_17_dialog_content = "ふふ、君と契約したのは正解だったようだ、プロデューサー君。\nきめ細やかな、鋭い観察眼だ。",
  ui_story_5035_50351201_18_dialog_content = "君が気づいてくれたおかげで、\n私もつまらない説明シーンを省略できる。",
  ui_story_5035_50351201_19_dialog_content = "その通りだ。前回の撮影に参加したスタッフは全員犠牲になった。\n協調性のない「主演女優」1名を除いてね。",
  ui_story_5035_50351201_20_dialog_content = "主演女優君がどれほど大きな間違いを犯したか、分かったかな？\n君たちの死がこの上なくすばらしい映画になるはずだったんだ。",
  ui_story_5035_50351201_21_dialog_content = "君が逃げ出したせいで、フィルムだけじゃない。\n多くの命が無駄になってしまったんだ。",
  ui_story_5035_50351201_22_dialog_content = "そ…そ、そんな…",
  ui_story_5035_50351201_23_dialog_content = "そのような詭弁（きべん）、\n通用するとは思わないことです。",
  ui_story_5035_50351201_24_dialog_content = "どうして、殺したの…？",
  ui_story_5035_50351201_25_dialog_content = "ゴルディも…クルーのみんなも…",
  ui_story_5035_50351201_26_dialog_content = "どうして…！？",
  ui_story_5035_50351201_27_dialog_content = "言っただろう。\n多くを見すぎてしまった者に、しゃべられては困るんだ。",
  ui_story_5035_50351201_28_dialog_content = "スクリーンは実に不思議なものだと、\n私は思っていてね。",
  ui_story_5035_50351201_29_dialog_content = "そこに映ったものは、すべてが理にかなっているように見える。\n何でもない暮らしも芸術に変わる。",
  ui_story_5035_50351201_30_dialog_content = "私たちアーティストにとって、\nそれは最高の秘密の隠し場所だ。",
  ui_story_5035_50351201_31_dialog_content = "だから、私は守らなければならないのさ。\n「秘密」をスクリーンから出すわけにはいかない。",
  ui_story_5035_50351201_32_dialog_content = "秘密？この屋敷に幽霊がいるって知りながら、\n撮影場所に選んだってこと！？",
  ui_story_5035_50351201_33_dialog_content = "おや、それが君の推理か。",
  ui_story_5035_50351201_34_dialog_content = "なかなかだ。真相に迫っている。\nだが、最も根本的な部分を間違えているね。",
  ui_story_5035_50351201_35_dialog_content = "幽霊が出るから、ここで撮影してるんじゃない。",
  ui_story_5035_50351201_36_dialog_content = "私がここにいるから、幽霊が出るんだよ。",
  ui_story_5035_50351201_37_dialog_content = "！！！",
  ui_story_5035_50351201_38_dialog_content = "どういうこと！？あなたが…",
  ui_story_5035_50351201_39_dialog_content = "この屋敷の真の価値を活かせるのは、私だけだ。",
  ui_story_5035_50351201_40_dialog_content = "何しろ、私よりこの屋敷を理解している者は…\n<color=#FFB400>彼女</color>を理解している者は、いないのだからね。",
  ui_story_5035_50351201_41_dialog_content = "幼い頃、両親に言われたことがあった。\n先祖の残した古い地図に、決して興味を持ってはならないと。",
  ui_story_5035_50351201_42_dialog_content = "しかし、この屋敷も、彼女の存在も、\n私にはあまりにも魅力的すぎた。",
  ui_story_5035_50351201_43_dialog_content = "先祖が生きていたら、\nきっと私の作品に震えることだろう。",
  ui_story_5035_50351201_44_dialog_content = "かつて仕えていた夫人が100年の時を経て、\n「霊」となり、屋敷に住み続けているのだからね。",
  ui_story_5035_50351201_45_dialog_content = "私は彼女のぼやけた意識を呼び覚まし、\n彼女は私の枯れ果てたインスピレーションを救ってくれた。",
  ui_story_5035_50351201_46_dialog_content = "そう、私たちは互いに新たな命を与え合ったのだ。",
  ui_story_5035_50351201_47_dialog_content = "君とあのスタッフ2人は…最初の実験台というところさ。",
  ui_story_5035_50351201_48_dialog_content = "私と<color=#FFB400>彼女</color>も、\n久しぶりに会ったばかりだったものでね。",
  ui_story_5035_50351201_49_dialog_content = "なんてことを…！",
  ui_story_5035_50351201_50_dialog_content = "彼女は本当にすばらしい。\n最初から予想をはるかに超えていた。",
  ui_story_5035_50351201_51_dialog_content = "あれも君がうっかり「原版」をダメにしなければ、\n影ノ街でウワサの貴重な映画作品となっただろう。",
  ui_story_5035_50351201_52_dialog_content = "それが…罪のない人たちを殺した理由？",
  ui_story_5035_50351201_53_dialog_content = "ホラー映画を撮影して、発表し続けてきたのは…\nいつかその女幽霊と一緒に映画を作るためだったということ？",
  ui_story_5035_50351201_54_dialog_content = "今まで、あんな出来の悪い作品を\n楽しんでくれていたことには、感謝するよ。",
  ui_story_5035_50351201_55_dialog_content = "ホラー映画好きなら、分かるだろう？\nホラー映画ではね…主役よりも悪役が重要なんだ。",
  ui_story_5035_50351201_56_dialog_content = "出演者の代わりはいくらでもいる。\nだが、<color=#FFB400>彼女</color>の代役をできる者はいない。",
  ui_story_5035_50351201_57_dialog_content = "<color=#FFB400>彼女</color>こそが真の「主演女優」だ。",
  ui_story_5035_50351201_58_dialog_content = "つ、つまり…幽霊を連れ歩きながら、\n映画を撮影してるってこと！？",
  ui_story_5035_50351201_59_dialog_content = "そんな恐ろしいことが…",
  ui_story_5035_50351201_60_dialog_content = "もっと恐ろしいことがありますよ。",
  ui_story_5035_50351201_61_dialog_content = "同じ方法で多くの映画を撮影してきた、と言うならば…",
  ui_story_5035_50351201_62_dialog_content = "貴方の手にかけられたクルーは、\n前回の1組だけではありませんね。",
  ui_story_5035_50351201_63_dialog_content = "あっ、まさか、他の作品のスタッフも…",
  ui_story_5035_50351201_64_dialog_content = "フフフ…プロデューサー君。\n私が君の立場だったら、そんな質問はしないよ。",
  ui_story_5035_50351201_65_dialog_content = "目も耳も塞がってしまえばいい、何も知りたくないと\nひたすら祈るだろうね。",
  ui_story_5035_50351201_66_dialog_content = "答えを知ればどうなるか、よく分かっているはずだ。",
  ui_story_5035_50351201_67_dialog_content = "…",
  ui_story_5035_50351201_68_dialog_content = "もったいぶる必要はございませんよ。\n貴方が姿を現した時から、答えは明らかです。",
  ui_story_5035_50351201_69_dialog_content = "これまでのクルーの皆様と同様、\n私たちは秘密を知りすぎている。",
  ui_story_5035_50351201_70_dialog_content = "だから、扉を閉めたのです。",
  ui_story_5035_50351201_71_dialog_content = "ゴーストハウスの中にいる者を、\n誰1人として見逃すつもりはないのでしょう？",
  ui_story_5035_50351201_72_dialog_content = "プロデューサー君、そう敵意をむき出しにしないでくれ。",
  ui_story_5035_50351201_73_dialog_content = "私たちは秘密を共有している、違うかな？",
  ui_story_5035_50351201_74_dialog_content = "望む望まないに関わらず、\n私たちはもう同じ船の上にいるんだ。",
  ui_story_5035_50351201_75_dialog_content = "歓迎するよ。",
  ui_story_5035_50351201_76_dialog_content = "私の<color=#FFB400>撮影クルー</color>としてね。",
  ui_story_5035_50351201_77_dialog_content = "<color=#e8d9bb>ピチャン…</color>",
  ui_story_5035_50351201_78_dialog_content = "！！！",
  ui_story_5035_50351201_79_dialog_content = "聞こえた！？水滴の音だ！",
  ui_story_5035_50351201_80_dialog_content = "<color=#e8d9bb>ピチャン…</color>",
  ui_story_5035_50351201_81_dialog_content = "ち、近づいてくる…",
  ui_story_5035_50351201_82_dialog_content = "いったい何の音…！？",
  ui_story_5035_50351201_83_dialog_content = "そうだわ、カメラよ！",
  ui_story_5035_50351201_84_dialog_content = "リリカ、急いでカメラを構えて！",
  ui_story_5035_50351201_85_dialog_content = "えっ？",
  ui_story_5035_50351201_86_dialog_content = "前に向けて、カメラを回すの、早く！",
  ui_story_5035_50351201_87_dialog_content = "わ、分かったわ。",
  ui_story_5035_50351201_88_dialog_content = "カメラオン…前を撮影…",
  ui_story_5035_50351201_89_dialog_content = "！！！",
  ui_story_5035_50351201_90_dialog_content = "み、みんな…見て！",
  ui_story_5035_50351201_91_dialog_content = "これは…",
  ui_story_5035_50351201_92_dialog_content = "あ！！",
  ui_story_5035_50351201_93_dialog_content = "どうしたの？何が写ってるの！？",
  ui_story_5035_50351201_94_dialog_content = "来たわ…彼女が！！",
  ui_story_5035_50351201_95_dialog_content = "どういうこと…？\nもう、何が何だか…",
  ui_story_5035_50351201_96_dialog_content = "あたしたち、殺されるの…？",
  ui_story_5035_50351201_97_dialog_content = "ぼうっとしてないで！\n早く逃げるのよ！",
  ui_story_5035_50351201_98_dialog_content = "逃げる…あ、そうね！\nまずは逃げなくちゃ！",
  ui_story_5035_50351201_99_dialog_content = "しっかり付いてきてください！\n上へ向かいます！",
  ui_story_5035_50351201_100_dialog_content = "<color=#e8d9bb>ドン、ドン、ドン…</color>",
  ui_story_5035_50351201_101_dialog_content = "さあさあ、逃げるがいい！\nだが、そっちは出口じゃないよ。",
  ui_story_5035_50351201_102_dialog_content = "屋敷から出ずに、どこへ逃げるというのかな？",
  ui_story_5035_50351201_103_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5035_50351201_104_dialog_content = "グアアッ！",
  ui_story_5035_50351201_105_dialog_content = "ガアァ――！",
  ui_story_5035_50351201_106_dialog_content = "どうして暗鬼がこんなにたくさんいるの？\nしかも、こんな時に！",
  ui_story_5035_50351201_107_dialog_content = "屋敷に潜伏してた暗鬼が全部動きだしたみたいだ。\nヨハンのしわざなのかな？",
  ui_story_5035_50351201_108_dialog_content = "屋敷に潜伏してたって…",
  ui_story_5035_50351201_109_dialog_content = "いくら何でも、多すぎるんじゃないの？",
  ui_story_5035_50351201_110_dialog_content = "ええ、そうですね。",
  ui_story_5035_50351201_111_dialog_content = "PlayerName様の推測通り、\n暗鬼の出現は彼と関係があるのでしょう。",
  ui_story_5035_50351201_112_dialog_content = "幽霊を使って1人1人始末していくよりも、\nこの方がクルー全員を一気に片づけられますからね。",
  ui_story_5035_50351201_113_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5035_50351201_114_dialog_content = "正面から戦ってはなりません。\nこちらへ！",
  ui_story_5035_50351201_115_dialog_content = "…ふぅ、いつまで逃げ続ければいいの？",
  ui_story_5035_50351201_116_dialog_content = "少なくとも、追ってくる暗鬼を振り切るまでですね。",
  ui_story_5035_50351201_117_dialog_content = "待って！前、前を見て！",
  ui_story_5035_50351201_118_dialog_content = "前がどうしたのさ？",
  ui_story_5035_50351201_119_dialog_content = "ろ、廊下の先に…お、女の子が2人いるわ！",
  ui_story_5035_50351201_120_dialog_content = "女の子？誰だろ…",
  ui_story_5035_50351201_121_dialog_content = "パピー、パピー。",
  ui_story_5035_50351201_122_dialog_content = "見ーつけた。",
  ui_story_5035_50351201_123_dialog_content = "パピー？パピーなんて名前の人…いた？",
  ui_story_5035_50351201_124_dialog_content = "まさか…",
  ui_story_5035_50351201_125_dialog_content = "早く早く、私たちを見つけてよ。",
  ui_story_5035_50351201_126_dialog_content = "パピー、ゲームしよ！",
  ui_story_5035_50351201_127_dialog_content = "10数える間にゴールに着けたら、\nパピーの勝ちだよ。",
  ui_story_5035_50351201_128_dialog_content = "さあパピー、ゴールに突進だよ！",
  ui_story_5035_50351201_129_dialog_content = "み、道を変えましょ！\nこれ以上先に進んだら…",
  ui_story_5035_50351201_130_dialog_content = "暗鬼に追いつかれるよ！早く走って！",
  ui_story_5035_50351201_131_dialog_content = "でも、この先は…",
  ui_story_5035_50351201_132_dialog_content = "そうそう、いい感じだよ、パピー。",
  ui_story_5035_50351201_133_dialog_content = "あと5だよ、急いで！",
  ui_story_5035_50351201_134_dialog_content = "パテ、パシ！\nどうして君たちまで！？",
  ui_story_5035_50351201_135_dialog_content = "パテ、お化け屋敷が大好きなんだ。",
  ui_story_5035_50351201_136_dialog_content = "パシもだよ！",
  ui_story_5035_50351201_137_dialog_content = "だから、来たんだよ。",
  ui_story_5035_50351201_138_dialog_content = "分かったよ…でも、今は遊んでる時間がないんだ。",
  ui_story_5035_50351201_139_dialog_content = "僕の手をつかんで！",
  ui_story_5035_50351201_140_dialog_content = "パテは左手！",
  ui_story_5035_50351201_141_dialog_content = "じゃ、パシは右手。",
  ui_story_5035_50351201_142_dialog_content = "急いで、逃げるよ！",
  ui_story_5035_50351302_1_dialog_content = "グアアッ！",
  ui_story_5035_50351302_2_dialog_content = "オラァッ！",
  ui_story_5035_50351302_3_dialog_content = "<color=#e8d9bb>バン、バン、バン！</color>",
  ui_story_5035_50351302_4_dialog_content = "ふん、この程度？",
  ui_story_5035_50351302_5_dialog_content = "ただのキャストだと思ったら大間違いだよ。\nあたしの必殺、暗鬼なんて一発！",
  ui_story_5035_50351302_6_dialog_content = "サディ、さすがだわ！\nこれで追ってきた暗鬼は全部倒したわね！",
  ui_story_5035_50351302_7_dialog_content = "この後は…あら？",
  ui_story_5035_50351302_8_dialog_content = "他のみんなは？",
  ui_story_5035_50351302_9_dialog_content = "え？",
  ui_story_5035_50351302_10_dialog_content = "あたし、ずっとあんたの後を走ってたんだよ。\n他の人について走ってたんじゃないの？",
  ui_story_5035_50351302_11_dialog_content = "あ、あたし、ずっとあなたの後ろを走ってたのよ！？",
  ui_story_5035_50351302_12_dialog_content = "…",
  ui_story_5035_50351302_13_dialog_content = "<color=#e8d9bb>カツン、カツン…</color>",
  ui_story_5035_50351302_14_dialog_content = "静かね…",
  ui_story_5035_50351302_15_dialog_content = "シッ、静かに。",
  ui_story_5035_50351302_16_dialog_content = "こんなに静かだと、声が響くよ。",
  ui_story_5035_50351302_17_dialog_content = "もう安全じゃないの？",
  ui_story_5035_50351302_18_dialog_content = "暗鬼はいないし、水滴の音もしないわ。",
  ui_story_5035_50351302_19_dialog_content = "そんなの分かんないでしょ。\n次の曲がり角にいるかもしれないし。",
  ui_story_5035_50351302_20_dialog_content = "ちょっと、驚かそうとしてもムダよ。\nあたし、度胸はあるんだから。",
  ui_story_5035_50351302_21_dialog_content = "でも、確かに…やたらに動き回らない方がいいかも。",
  ui_story_5035_50351302_22_dialog_content = "敵がたくさん出て来るとか、他には…",
  ui_story_5035_50351302_23_dialog_content = "…とにかく、あたしたち2人だけじゃどうにもならないわ。",
  ui_story_5035_50351302_24_dialog_content = "…うん、そうだね。",
  ui_story_5035_50351302_25_dialog_content = "じゃあ、どこかの部屋に隠れよっか。",
  ui_story_5035_50351302_26_dialog_content = "見て！このドア、開くわ！",
  ui_story_5035_50351302_27_dialog_content = "シーッ！音を立てないように、そーっと…",
  ui_story_5035_50351302_28_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5035_50351302_29_dialog_content = "鍵はかけられるのかな？",
  ui_story_5035_50351302_30_dialog_content = "どうかしら…あ、かけられそう！",
  ui_story_5035_50351302_31_dialog_content = "じゃ、急いで鍵かけて。",
  ui_story_5035_50351302_32_dialog_content = "ええ。",
  ui_story_5035_50351302_33_dialog_content = "<color=#e8d9bb>カチャ</color>",
  ui_story_5035_50351302_34_dialog_content = "ふぅ――これで、ひと安心ね。",
  ui_story_5035_50351302_35_dialog_content = "はぁ――",
  ui_story_5035_50351302_36_dialog_content = "まったく…本当に怖かったわ。\nこれでようやく一息つけるわね。",
  ui_story_5035_50351302_37_dialog_content = "休憩したら様子を見て、\n他のみんなの動きが分かったら、合流することにしましょ。",
  ui_story_5035_50351302_38_dialog_content = "うん、そうだね。一休みしよ。",
  ui_story_5035_50351302_39_dialog_content = "ただ…",
  ui_story_5035_50351302_40_dialog_content = "気づいた？\nこの部屋、ちょっと見覚えあるんだけど。",
  ui_story_5035_50351302_41_dialog_content = "えっ？",
  ui_story_5035_50351302_42_dialog_content = "本当だわ！あの陳列室じゃない！",
  ui_story_5035_50351302_43_dialog_content = "いつの間に戻ってきちゃったの…？",
  ui_story_5035_50351302_44_dialog_content = "確か、初めて水滴の音を聞いたのは、\nこの陳列室だったね…",
  ui_story_5035_50351302_45_dialog_content = "へ、変なこと言わないで。\n休憩どころじゃなくなるじゃない！",
  ui_story_5035_50351302_46_dialog_content = "他のことを考えて、気をそらしましょ。",
  ui_story_5035_50351302_47_dialog_content = "そうだわ、記念にビデオを撮りましょ！",
  ui_story_5035_50351302_48_dialog_content = "今？あんた、ホントに\n状況に合わないことするの得意だね。",
  ui_story_5035_50351302_49_dialog_content = "そんなことないでしょ？\nカメラはいろんな場所と時間を記録するためにあるの！",
  ui_story_5035_50351302_50_dialog_content = "楽しい時も、怖い時も、記念するべき時も…",
  ui_story_5035_50351302_51_dialog_content = "それに、カメラで幽霊の痕跡をとらえられたら、\n何も見えないよりは安心じゃない！",
  ui_story_5035_50351302_52_dialog_content = "そう言われると、確かに…？",
  ui_story_5035_50351302_53_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_54_dialog_content = "！！",
  ui_story_5035_50351302_55_dialog_content = "何の音！？",
  ui_story_5035_50351302_56_dialog_content = "ど、ドアが…",
  ui_story_5035_50351302_57_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_58_dialog_content = "ドアが破られる！！",
  ui_story_5035_50351302_59_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_60_dialog_content = "誰！？",
  ui_story_5035_50351302_61_dialog_content = "リリカにサディか。ハハハ、これは大収穫だな。",
  ui_story_5035_50351302_62_dialog_content = "私のキャスト君たち、映画の撮影が始まるぞ。",
  ui_story_5035_50351302_63_dialog_content = "ヨハン！？",
  ui_story_5035_50351302_64_dialog_content = "こ、来ないで！ヒドい目に遭わせるよ！",
  ui_story_5035_50351302_65_dialog_content = "ヒドい目に遭わせる？\nずいぶん強気だね、サディ。",
  ui_story_5035_50351302_66_dialog_content = "ますます興味が湧いてきたよ。",
  ui_story_5035_50351302_67_dialog_content = "本当にそっちに行ったら、\n君は私をどうするつもりなんだい？",
  ui_story_5035_50351302_68_dialog_content = "どうするつもりなんだい！？",
  ui_story_5035_50351302_69_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_70_dialog_content = "あ！！",
  ui_story_5035_50351302_71_dialog_content = "ヨハン！！あなたの悪行は全部記録したわ！",
  ui_story_5035_50351302_72_dialog_content = "ビデオが世間に出たら、どうなるか分かってるの？\n分かってるなら、今すぐやめなさい！まだ間に合うわ！",
  ui_story_5035_50351302_73_dialog_content = "記録した？",
  ui_story_5035_50351302_74_dialog_content = "それはすばらしい、実にすばらしいよ。\nリリカ、君にはやはり才能がある。優れた嗅覚だ。",
  ui_story_5035_50351302_75_dialog_content = "ビデオはもちろん世間に出るさ。\nただし、私の作品の一部として編集した後でね。",
  ui_story_5035_50351302_76_dialog_content = "そうすれば、映画がもっと完璧に近づける。",
  ui_story_5035_50351302_77_dialog_content = "あ…あなたって人は…",
  ui_story_5035_50351302_78_dialog_content = "それに――",
  ui_story_5035_50351302_79_dialog_content = "映画の撮影フィルムに映ってる物が真実だなんて、\n誰が信じるんだい？",
  ui_story_5035_50351302_80_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_81_dialog_content = "うわあああ！！",
  ui_story_5035_50351302_82_dialog_content = "きゃあああ！！",
  ui_story_5035_50351302_83_dialog_content = "いいぞ、その調子だ！続けるんだ！",
  ui_story_5035_50351302_84_dialog_content = "叫び声を上げろ！\nホラーを止めるな！！",
  ui_story_5035_50351302_85_dialog_content = "<color=#e8d9bb>ガン！！</color>",
  ui_story_5035_50351302_86_dialog_content = "あああああ！！",
  ui_story_5035_50351302_87_dialog_content = "これで最後だ…",
  ui_story_5035_50351302_88_dialog_content = "アハハ、アハハハハ…",
  ui_story_5035_50351302_89_dialog_content = "うわああ――！！",
  ui_story_5035_50351302_90_dialog_content = "！？",
  ui_story_5035_50351302_91_dialog_content = "ん？",
  ui_story_5035_50351302_92_dialog_content = "おや、あっちか。",
  ui_story_5035_50351302_93_dialog_content = "始まった、始まったぞ！",
  ui_story_5035_50351302_94_dialog_content = "だが、これはいかん。\nあっちはカメラが回っていない…",
  ui_story_5035_50351302_95_dialog_content = "どのカットも欠かすわけにはいかん。\n全て完璧に、絶対に欠けてはいけないんだ…",
  ui_story_5035_50351302_96_dialog_content = "はぁ…はぁ…",
  ui_story_5035_50351302_97_dialog_content = "はぁ…はぁ…",
  ui_story_5035_50351302_98_dialog_content = "…もう、行ったの？",
  ui_story_5035_50351302_99_dialog_content = "た、たぶん…",
  ui_story_5035_50351302_100_dialog_content = "どういうことか、よく分かんないけど…\nさっきの声、気づいた？",
  ui_story_5035_50351302_101_dialog_content = "ええ、今思い出してるところ。\n少し距離があったわ、たぶん下の階ね。",
  ui_story_5035_50351302_102_dialog_content = "それに…聞いたことがある声だったわね？",
  ui_story_5035_50351302_103_dialog_content = "PlayerNameだよ、たぶん。",
  ui_story_5035_50351401_1_dialog_content = "<color=#e8d9bb>3分前</color>",
  ui_story_5035_50351401_2_dialog_content = "ふぅ、ようやく暗鬼を振り切れたね…\nみんな、大丈夫？",
  ui_story_5035_50351401_3_dialog_content = "私は無事です。\n…ただ、振り切ったのは暗鬼だけではないようですね。",
  ui_story_5035_50351401_4_dialog_content = "えっ？",
  ui_story_5035_50351401_5_dialog_content = "本当だ！リリカとサディは！？",
  ui_story_5035_50351401_6_dialog_content = "暗鬼との混戦ではぐれてしまったようです。\nどちらにいらっしゃるかは私にも…",
  ui_story_5035_50351401_7_dialog_content = "大変だ、2人だけじゃ大変なことになるかも！\n急いで戻って探さないと！",
  ui_story_5035_50351401_8_dialog_content = "そうですね…おそらくまだ2階にいらっしゃるかと。",
  ui_story_5035_50351401_9_dialog_content = "PlayerName様、感知能力で探してみてください。",
  ui_story_5035_50351401_10_dialog_content = "今やってる…",
  ui_story_5035_50351401_11_dialog_content = "待って！",
  ui_story_5035_50351401_12_dialog_content = "え？どうしたの？",
  ui_story_5035_50351401_13_dialog_content = "さっき…廊下にあんなものあった？",
  ui_story_5035_50351401_14_dialog_content = "いつの間に…？",
  ui_story_5035_50351401_15_dialog_content = "こんな大きな物、気づかないはずはないよね。",
  ui_story_5035_50351401_16_dialog_content = "うん、無かった。パテは見なかったよ。",
  ui_story_5035_50351401_17_dialog_content = "これ何？カンオケ？",
  ui_story_5035_50351401_18_dialog_content = "そうですね。\nさきほどの撮影クルーが運んでいたものです。",
  ui_story_5035_50351401_19_dialog_content = "誰がここまで運んできたのでしょう？",
  ui_story_5035_50351401_20_dialog_content = "と、とにかく、それは放っておこう。\nリリカとサディを探すことの方が先決だよ。",
  ui_story_5035_50351401_21_dialog_content = "避けて通ればいいだけのことだよね。",
  ui_story_5035_50351401_22_dialog_content = "まぁ、そうね。",
  ui_story_5035_50351401_23_dialog_content = "PlayerName、先に行って。",
  ui_story_5035_50351401_24_dialog_content = "え、ぼ、僕が？",
  ui_story_5035_50351401_25_dialog_content = "そうよ。",
  ui_story_5035_50351401_26_dialog_content = "でも…",
  ui_story_5035_50351401_27_dialog_content = "…分かった、僕が先頭を歩くよ！\nたかが撮影道具でしょ、怖くなんてない！",
  ui_story_5035_50351401_28_dialog_content = "しっかりついて来てね。一刻も早く…",
  ui_story_5035_50351401_29_dialog_content = "<color=#e8d9bb>カン！</color>",
  ui_story_5035_50351401_30_dialog_content = "うわあっ――！！",
  ui_story_5035_50351401_31_dialog_content = "ん？",
  ui_story_5035_50351401_32_dialog_content = "おや、あっちか。",
  ui_story_5035_50351401_33_dialog_content = "音がしたよ！！\nい、今、棺の中から音がした！",
  ui_story_5035_50351401_34_dialog_content = "聞こえてるわ！",
  ui_story_5035_50351401_35_dialog_content = "こ、これ…本当にただの撮影道具なの？",
  ui_story_5035_50351401_36_dialog_content = "うぅ…うぅ…",
  ui_story_5035_50351401_37_dialog_content = "助けて…オバケがいるよぉ…",
  ui_story_5035_50351401_38_dialog_content = "ど、どどどどどうしよう？\nこれ以上近づけないよ！",
  ui_story_5035_50351401_39_dialog_content = "道を変える？でも、棺に背を向けるのも…",
  ui_story_5035_50351401_40_dialog_content = "やはり、一度確認してみるのがよいでしょう。",
  ui_story_5035_50351401_41_dialog_content = "私が開けます。",
  ui_story_5035_50351401_42_dialog_content = "あ、開ける！？",
  ui_story_5035_50351401_43_dialog_content = "ええ、少なくとも目の前のものが何なのか、\nはっきりできますので。",
  ui_story_5035_50351401_44_dialog_content = "き、気をつけて…",
  ui_story_5035_50351401_45_dialog_content = "ご安心ください。",
  ui_story_5035_50351401_46_dialog_content = "何があろうと準備はできておりますので。",
  ui_story_5035_50351401_47_dialog_content = "<color=#e8d9bb>カン！</color>",
  ui_story_5035_50351401_48_dialog_content = "もう少し…",
  ui_story_5035_50351401_49_dialog_content = "<color=#e8d9bb>カン！</color>",
  ui_story_5035_50351401_50_dialog_content = "近づいて…",
  ui_story_5035_50351401_51_dialog_content = "<color=#e8d9bb>カン、カン！</color>",
  ui_story_5035_50351401_52_dialog_content = "…",
  ui_story_5035_50351401_53_dialog_content = "<color=#e8d9bb>カン、カン、カン、カン！！</color>",
  ui_story_5035_50351401_54_dialog_content = "……",
  ui_story_5035_50351401_55_dialog_content = "音が激しくなってる…\n近づいてるのが分かるんだ！",
  ui_story_5035_50351401_56_dialog_content = "早く退がって！",
  ui_story_5035_50351401_57_dialog_content = "申しわけございませんが、\nこれ以上は近づけません。",
  ui_story_5035_50351401_58_dialog_content = "えっ？",
  ui_story_5035_50351401_59_dialog_content = "気配で分かります。棺の中にあるものは…\n私を殺せるだけの力を持っているようです。",
  ui_story_5035_50351401_60_dialog_content = "やっぱり…撮影用の道具じゃなくて、本物の…",
  ui_story_5035_50351401_61_dialog_content = "今日はおかしなことばっかり起こるね…",
  ui_story_5035_50351401_62_dialog_content = "棺を避けて、できるだけ離れて歩こう。",
  ui_story_5035_50351401_63_dialog_content = "逃げて、避けられるものでしょうか？",
  ui_story_5035_50351401_64_dialog_content = "どこからともなく現れたということは、\n別の場所にも同じように出現する可能性があります。",
  ui_story_5035_50351401_65_dialog_content = "つ、つまり…",
  ui_story_5035_50351401_66_dialog_content = "開けるべきです。\n全員でいっせいにかかりましょう。",
  ui_story_5035_50351401_67_dialog_content = "やっぱり開けなきゃならないの！？",
  ui_story_5035_50351401_68_dialog_content = "危険は暗闇の中に潜ませておくよりも、\n表にさらけ出してしまったほうが安全です。",
  ui_story_5035_50351401_69_dialog_content = "皆様はどう思われますか？",
  ui_story_5035_50351401_70_dialog_content = "一理あるように聞こえるけど…",
  ui_story_5035_50351401_71_dialog_content = "怖いけど…でも…",
  ui_story_5035_50351401_72_dialog_content = "中に何が入っているのか、知りたいわ…",
  ui_story_5035_50351401_73_dialog_content = "うぅ…",
  ui_story_5035_50351401_74_dialog_content = "じゃあ、開けよう！皆で一緒に！",
  ui_story_5035_50351401_75_dialog_content = "命の危険なんて、\n今までだって数えきれないほど経験してる！",
  ui_story_5035_50351401_76_dialog_content = "ええ、そうよね。怖いことなんてないわ。\n怖くない…怖くない…",
  ui_story_5035_50351401_77_dialog_content = "では、皆様、集中してください。\n私の近くに寄って…",
  ui_story_5035_50351401_78_dialog_content = "何か起こった時は、すぐに動けるようにしてください。",
  ui_story_5035_50351401_79_dialog_content = "皆様、一緒に、前へ…",
  ui_story_5035_50351401_80_dialog_content = "待った待った待った！！",
  ui_story_5035_50351401_81_dialog_content = "え？？？",
  ui_story_5035_50351401_82_dialog_content = "ヨハン監督！？",
  ui_story_5035_50351401_83_dialog_content = "ちょっと待ってくれ！\n少しだけ時間が欲しい、頼む！",
  ui_story_5035_50351401_84_dialog_content = "このカットはリテイク不可能なんだ！\n何が何でも撮り逃すわけにはいかない！！",
  ui_story_5035_50351401_85_dialog_content = "1分、1分でいい！！\n信じてくれ、私はプロだ！！",
  ui_story_5035_50351401_86_dialog_content = "ど、どういう意味…？",
  ui_story_5035_50351401_87_dialog_content = "何をするおつもりでしょう？",
  ui_story_5035_50351401_88_dialog_content = "それと、この棺はいったい何！？",
  ui_story_5035_50351401_89_dialog_content = "とにかくライト、このアングルが必要で…",
  ui_story_5035_50351401_90_dialog_content = "ピントはもう少し寄せて…",
  ui_story_5035_50351401_91_dialog_content = "よし、これでいい…",
  ui_story_5035_50351401_92_dialog_content = "それからマイク…\nクソッ、ボタンがまたハマってるじゃないか！",
  ui_story_5035_50351401_93_dialog_content = "ポンコツめ！明日廃品回収に出してやる！",
  ui_story_5035_50351401_94_dialog_content = "カチンコ係はどこだ？おい、カチンコ！！",
  ui_story_5035_50351401_95_dialog_content = "ええい、もういい！自分でやる！！",
  ui_story_5035_50351401_96_dialog_content = "あと少しだ、待っててくれよ！\nこれで最後だ！",
  ui_story_5035_50351401_97_dialog_content = "火もつけておかないとな。\n「エスター」は火の燃える匂いが大好きなんだ。",
  ui_story_5035_50351401_98_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5035_50351401_99_dialog_content = "これでよし！\nみんな、待たせたね。",
  ui_story_5035_50351401_100_dialog_content = "さあ、『ホラーを止めるな！』最終カットの撮影開始だ！",
  ui_story_5035_50351401_101_dialog_content = "この作品は必ずや芸術性と商業性を兼ね備えた完璧な映画になるだろう！\nここにいる全員の俳優人生が、輝かしいものになる！",
  ui_story_5035_50351401_102_dialog_content = "君たちと…そして<color=#FFB400>エスター</color>と共に、\nこの快挙を成し遂げられることを光栄に思うよ。",
  ui_story_5035_50351401_103_dialog_content = "エスター？",
  ui_story_5035_50351401_104_dialog_content = "まずいわ、それってつまり…",
  ui_story_5035_50351401_105_dialog_content = "それでは、みんな…",
  ui_story_5035_50351401_106_dialog_content = "<color=#FFB400>主演女優</color>と対面する準備はできたかな？",
  ui_story_5035_50351401_107_dialog_content = "主演女優！？",
  ui_story_5035_50351401_108_dialog_content = "『ホラーを止めるな！』最終シーン！\nカット1、テイク1――",
  ui_story_5035_50351401_109_dialog_content = "アクション！！",
  ui_story_5035_50351401_110_dialog_content = "<color=#e8d9bb>ガラン…ガラン…</color>",
  ui_story_5035_50351401_111_dialog_content = "あ！！",
  ui_story_5035_50351401_112_dialog_content = "棺の鈴だ！鈴が鳴り出した！",
  ui_story_5035_50351401_113_dialog_content = "<color=#e8d9bb>カン、カン！</color>",
  ui_story_5035_50351401_114_dialog_content = "おかしいですね。\n誰も近づいておりませんが…",
  ui_story_5035_50351401_115_dialog_content = "<color=#e8d9bb>カン、カン…ガン、ガン！！</color>",
  ui_story_5035_50351401_116_dialog_content = "あっ…！！",
  ui_story_5035_50351401_117_dialog_content = "棺のフタが！フタが開くわ…",
  ui_story_5035_50351401_118_dialog_content = "<color=#e8d9bb>バン！！！</color>",
  ui_story_5035_50351401_119_dialog_content = "ヒヒヒ…ヒヒ…ヒヒ…",
  ui_story_5035_50351401_120_dialog_content = "何かがはい出してくる！？",
  ui_story_5035_50351401_121_dialog_content = "あ、あれは…何？",
  ui_story_5035_50351401_122_dialog_content = "あ、あ、あああ、あれは…",
  ui_story_5035_50351401_123_dialog_content = "私たちの後ろに写ってた、女の幽霊…",
  ui_story_5035_50351401_124_dialog_content = "<color=#FFB400>エスター</color>だわ！",
  ui_story_5035_50351401_125_dialog_content = "ヒヒヒ！ヒヒヒヒヒ！！",
  ui_story_5035_50351401_126_dialog_content = "ヨ、ヨハン監督の映画で似たようなシーンを見たわ…",
  ui_story_5035_50351401_127_dialog_content = "どんなシーン？",
  ui_story_5035_50351401_128_dialog_content = "棺の中から化け物がはい出してきて、\n生きてる人を中に引きずり込むの。",
  ui_story_5035_50351401_129_dialog_content = "それで、棺のフタが閉まって、\n「ブシュッ、グチャッ」ていう音が聞こえて…",
  ui_story_5035_50351401_130_dialog_content = "それからレンズに血が飛び散って、\n最後は真っ赤に染まった画面で、終わり…",
  ui_story_5035_50351401_131_dialog_content = "棺の中に引きずり込む…",
  ui_story_5035_50351401_132_dialog_content = "待って、じゃあ僕たちは今…",
  ui_story_5035_50351401_133_dialog_content = "そのシーンを撮らされてるってこと！？",
  ui_story_5035_50351401_134_dialog_content = "き、来たわ！",
  ui_story_5035_50351401_135_dialog_content = "ヒヒヒッ！！",
  ui_story_5035_50351401_136_dialog_content = "こっちに来る！\n逃げよう、急いで！！",
  ui_story_5035_50351401_137_dialog_content = "ヒヒヒ――",
  ui_story_5035_50351401_138_dialog_content = "私を狙ってる！！",
  ui_story_5035_50351401_139_dialog_content = "き、距離は！？",
  ui_story_5035_50351401_140_dialog_content = "分からないわ、怖くて振り向けないもの！",
  ui_story_5035_50351401_141_dialog_content = "うう～ん、臭いよ～…",
  ui_story_5035_50351401_142_dialog_content = "気を失っちゃいそう…",
  ui_story_5035_50351401_143_dialog_content = "いけません、これ以上先は…",
  ui_story_5035_50351401_144_dialog_content = "どうしたの？",
  ui_story_5035_50351401_145_dialog_content = "この先のドアが先に塞がれていたら、\n行き止まりに閉じ込められてしまいます。",
  ui_story_5035_50351401_146_dialog_content = "ええ！？じゃあ、どうするの！？",
  ui_story_5035_50351401_147_dialog_content = "引き返して、別の道を進むか…",
  ui_story_5035_50351401_148_dialog_content = "ヒヒヒ――",
  ui_story_5035_50351401_149_dialog_content = "そんなこと出来ると思う！？",
  ui_story_5035_50351401_150_dialog_content = "あるいは、ドアを破るしか…",
  ui_story_5035_50351401_151_dialog_content = "そっちの方がまだ可能性はあるね。\nドアを破るぐらい、難しくないよ！",
  ui_story_5035_50351401_152_dialog_content = "そうもまいりません。この屋敷のドアはすべて補強してあります。\n光力術に対して強力な耐性があるのです…",
  ui_story_5035_50351401_153_dialog_content = "補強！？なんでわざわざそんな余計なことを…",
  ui_story_5035_50351401_154_dialog_content = "お客様が興奮しすぎて建物を壊してしまうのではと、\n心配だったものですから。",
  ui_story_5035_50351401_155_dialog_content = "まさかドアを破らねばならない事態が起こるとは、\n予想できておりませんでしたので…",
  ui_story_5035_50351401_156_dialog_content = "じゃあ、なすすべがないってこと！？",
  ui_story_5035_50351401_157_dialog_content = "ご心配にはおよびません。\nドアが破れずとも、壁を破ることは出来ます。",
  ui_story_5035_50351401_158_dialog_content = "そうか！壁は補強してないんだね！？",
  ui_story_5035_50351401_159_dialog_content = "ええ、補強しておりません。もともと丈夫でしたから。\n少し時間はかかると思いますが…",
  ui_story_5035_50351401_160_dialog_content = "今一番足りないのは、その時間なんだけどね…",
  ui_story_5035_50351401_161_dialog_content = "こちらです。",
  ui_story_5035_50351401_162_dialog_content = "一斉に全力で攻撃します！",
  ui_story_5035_50351401_163_dialog_content = "分かったわ！／分かった！",
  ui_story_5035_50351401_164_dialog_content = "<color=#e8d9bb>バリン！</color>",
  ui_story_5035_50351401_165_dialog_content = "穴が開いたわ！",
  ui_story_5035_50351401_166_dialog_content = "も、もう少し、急いで！",
  ui_story_5035_50351401_167_dialog_content = "もう…すぐそばまで、来てる…",
  ui_story_5035_50351401_168_dialog_content = "（エスターの後ろにいるのは…ヨハン？）",
  ui_story_5035_50351401_169_dialog_content = "…",
  ui_story_5035_50351401_170_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_5035_50351401_171_dialog_content = "あと少しよ！",
  ui_story_5035_50351401_172_dialog_content = "ヒヒヒ――",
  ui_story_5035_50351401_173_dialog_content = "急いで！！もう目の前だ！！",
  ui_story_5035_50351401_174_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_5035_50351401_175_dialog_content = "やりました！皆様、お急ぎください！",
  ui_story_5035_50351401_176_dialog_content = "PlayerName、急いで！",
  ui_story_5035_50351401_177_dialog_content = "う、うん！",
  ui_story_5035_50351401_178_dialog_content = "この先は2階に通じています。\nそちらへ行けば、動ける範囲が広がるでしょう。",
  ui_story_5035_50351401_179_dialog_content = "よかった！じゃあ…",
  ui_story_5035_50351401_180_dialog_content = "きゃああ！！",
  ui_story_5035_50351401_181_dialog_content = "バイス！？どうしたの？",
  ui_story_5035_50351401_182_dialog_content = "何かに…引っ張られてる…！",
  ui_story_5035_50351401_183_dialog_content = "！！！",
  ui_story_5035_50351401_184_dialog_content = "バイスが捕まった！！",
  ui_story_5035_50351401_185_dialog_content = "棺め！バイスを放して！！",
  ui_story_5035_50351401_186_dialog_content = "お手伝いします…",
  ui_story_5035_50351401_187_dialog_content = "ヒヒヒ！",
  ui_story_5035_50351401_188_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5035_50351401_189_dialog_content = "ミノス！！",
  ui_story_5035_50351401_190_dialog_content = "パピー、私たちも引っ張るの、手伝う！",
  ui_story_5035_50351401_191_dialog_content = "よいしょ…ううう。",
  ui_story_5035_50351401_192_dialog_content = "すごい力よ…逃げられないわ。",
  ui_story_5035_50351401_193_dialog_content = "何か…何か方法は…",
  ui_story_5035_50351401_194_dialog_content = "そうそう、それそれ、その表情だ！\nここはアップで撮らなくては…",
  ui_story_5035_50351401_195_dialog_content = "君って人は！！",
  ui_story_5035_50351401_196_dialog_content = "シーッ――",
  ui_story_5035_50351401_197_dialog_content = "私に話しかけてはいけないよ。\n話すなら、他の登場人物と話してくれないと。",
  ui_story_5035_50351401_198_dialog_content = "これは君の命でつむがれる作品なんだ。\nプロとして、しっかり演じてもらわないと。",
  ui_story_5035_50351401_199_dialog_content = "クッ…",
  ui_story_5035_50351401_200_dialog_content = "だったら、プロに任せてもらおうじゃない！",
  ui_story_5035_50351401_201_dialog_content = "<color=#e8d9bb>パシャ！パシャパシャ――</color>",
  ui_story_5035_50351401_202_dialog_content = "うわあああ！？\n誰だ、フラッシュをたいたのは！？",
  ui_story_5035_50351401_203_dialog_content = "今のカットが全部台無しだ！！",
  ui_story_5035_50351401_204_dialog_content = "ヒ…",
  ui_story_5035_50351401_205_dialog_content = "力がゆるんだ！！",
  ui_story_5035_50351401_206_dialog_content = "今のうちに離れて！",
  ui_story_5035_50351401_207_dialog_content = "うん！",
  ui_story_5035_50351401_208_dialog_content = "今のは、リリカ？",
  ui_story_5035_50351401_209_dialog_content = "チッチッチッ…そんなカメラポジション、\nまるでダメダメだわ。",
  ui_story_5035_50351401_210_dialog_content = "こういうシーンはこっちが一番よ。\nまったく、シロート同然ね！",
  ui_story_5035_50351401_211_dialog_content = "リリカ…",
  ui_story_5035_50351401_212_dialog_content = "君が自分から私の前に現れるとは、意外だね。",
  ui_story_5035_50351401_213_dialog_content = "あんたが言ったんでしょ。\nやるなら、最後まで演じ切らないと。",
  ui_story_5035_50351401_214_dialog_content = "「前作」の借り、今返してあげるわ！",
  ui_story_5035_50351401_215_dialog_content = "そうか、それはよかった…",
  ui_story_5035_50351401_216_dialog_content = "ちょうど尺が足りないんじゃないかと、\n心配していたところなんだ。",
  ui_story_5035_50351401_217_dialog_content = "君が現われたと言うのなら…",
  ui_story_5035_50351401_218_dialog_content = "何をご心配で？",
  ui_story_5035_50351401_219_dialog_content = "ミノス！無事だったんだね！",
  ui_story_5035_50351401_220_dialog_content = "…",
  ui_story_5035_50351401_221_dialog_content = "当然のことです。大事な棺をぶつけられるとは思わず、\n少々不意を突かれただけでございます。",
  ui_story_5035_50351401_222_dialog_content = "私はプロデューサーでございますから…\n監督が撮影するというなら、最後までお付き合いしなければ。",
  ui_story_5035_50351401_223_dialog_content = "あんたたち、大したプロだよ。",
  ui_story_5035_50351401_224_dialog_content = "ま、勝手にやってれば？\nあたしは俳優なんて止めとくよ。",
  ui_story_5035_50351401_225_dialog_content = "改めて自己紹介するよ…\nあたしは「サディ・666」、頼れる義賊！",
  ui_story_5035_50351401_226_dialog_content = "あたしのバットがうなりを上げる、\nあんたは倒れて音を上げる！",
  ui_story_5035_50351401_227_dialog_content = "明日のニュースは「ヨハン逮捕」がトップを飾る！",
  ui_story_5035_50351401_228_dialog_content = "えっ、ライミングできるんだ？",
  ui_story_5035_50351401_229_dialog_content = "ふふ、何回も聞いてれば覚えるわ！",
  ui_story_5035_50351401_230_dialog_content = "それじゃ、みんな準備はいいわね！？",
  ui_story_5035_50351401_231_dialog_content = "実体があるなら幽霊なんか怖くないわ！\nただのモンスターだもの！",
  ui_story_5035_50351401_232_dialog_content = "『俳優のタマゴ必読マニュアル』も読んだことないくせに、\nあたしから主役を奪おうっていうの！？",
  ui_story_5035_50351401_233_dialog_content = "「主演女優」の座は返してもらうわ！",
  ui_story_5035_50351401_234_dialog_content = "皆にここまで熱演してもらえるなんて、\n嬉しい限りだよ。",
  ui_story_5035_50351401_235_dialog_content = "『ホラーを止めるな！』最終シーン、カット2、テイク1――",
  ui_story_5035_50351401_236_dialog_content = "アクション！！",
  ui_story_5035_50351402_1_dialog_content = "<color=#e8d9bb>バン、バン――</color>",
  ui_story_5035_50351402_2_dialog_content = "ヒヒヒッ！！",
  ui_story_5035_50351402_3_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_5035_50351402_4_dialog_content = "皆、大丈夫！？",
  ui_story_5035_50351402_5_dialog_content = "ゲホゲホ…",
  ui_story_5035_50351402_6_dialog_content = "ううっ…",
  ui_story_5035_50351402_7_dialog_content = "身体が言うことを聞かないわ…",
  ui_story_5035_50351402_8_dialog_content = "エスターは…？倒したの？",
  ui_story_5035_50351402_9_dialog_content = "まだ倒れてないよ。でも…",
  ui_story_5035_50351402_10_dialog_content = "弱ってるみたいだ。",
  ui_story_5035_50351402_11_dialog_content = "ヒヒ…ヒヒヒ…",
  ui_story_5035_50351402_12_dialog_content = "戦ってみて分かったけど、\n幽霊でも謎でも何でもないわね。",
  ui_story_5035_50351402_13_dialog_content = "そうだね。強烈な暗力を放ってるし、\n実は暗鬼とよく似た存在なのかもしれない…",
  ui_story_5035_50351402_14_dialog_content = "いや、もしかしたら、\n単なる特殊な暗鬼なのかも。",
  ui_story_5035_50351402_15_dialog_content = "そろそろおしまいです。\n後は持久戦といったところですね。",
  ui_story_5035_50351402_16_dialog_content = "なんとか持ちこたえれば…",
  ui_story_5035_50351402_17_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5035_50351402_18_dialog_content = "！！！",
  ui_story_5035_50351402_19_dialog_content = "いけない、ロウソクだ！",
  ui_story_5035_50351402_20_dialog_content = "ロウソクがエスターに力を与えてる！",
  ui_story_5035_50351402_21_dialog_content = "あと少しなんだ、エスター…\nあとほんの少しなんだよ。",
  ui_story_5035_50351402_22_dialog_content = "あと少し、がんばってくれ…",
  ui_story_5035_50351402_23_dialog_content = "ヒ…",
  ui_story_5035_50351402_24_dialog_content = "さあ、やつらを食ってしまえ。\n1人でも食えば、力を取り戻せるさ。",
  ui_story_5035_50351402_25_dialog_content = "たった1人食えれば、\n残りの全員を食うだけの力も得られる。",
  ui_story_5035_50351402_26_dialog_content = "ヒヒヒ――",
  ui_story_5035_50351402_27_dialog_content = "ただ、私は手伝えないんだ。\nもっと大切な仕事があるからね…",
  ui_story_5035_50351402_28_dialog_content = "君の一挙一動を、すべて記録しなければならないんだ。",
  ui_story_5035_50351402_29_dialog_content = "映像に残す方が、手を貸すよりもずっと大事なんだ。\n分かってくれるね？",
  ui_story_5035_50351402_30_dialog_content = "ヒヒヒ！",
  ui_story_5035_50351402_31_dialog_content = "私にできる事と言えば、\n君の獲物を照らすことぐらいだ。",
  ui_story_5035_50351402_32_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_5035_50351402_33_dialog_content = "温度を感じたかい？\nとうの昔に失っていた感覚だろう…",
  ui_story_5035_50351402_34_dialog_content = "熱が体内を巡っているのが分かるかい？\n君はまだ死んでなどいないんだ。",
  ui_story_5035_50351402_35_dialog_content = "少なくとも今、君は生きている。\n私が君を生き返らせたんだ。",
  ui_story_5035_50351402_36_dialog_content = "あいつらを見るがいい。\n君が渇望する命を持っているのに、命に対する敬意を忘れている。",
  ui_story_5035_50351402_37_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_5035_50351402_38_dialog_content = "さあ、取り戻すんだ。\n君が持つべきもの、そいつらには持つ資格のないものを！",
  ui_story_5035_50351402_39_dialog_content = "ヒヒヒッ！！",
  ui_story_5035_50351402_40_dialog_content = "エスターが…来るわ！",
  ui_story_5035_50351402_41_dialog_content = "あのロウソクを消さないと！\nでないと、すぐに回復されちゃうよ！",
  ui_story_5035_50351402_42_dialog_content = "二手に分かれましょう。私とバイス様でエスターを引き付けます。\n皆様はロウソクを消してください。",
  ui_story_5035_50351402_43_dialog_content = "分かったわ！",
  ui_story_5035_50351402_44_dialog_content = "エスターを引き付ける？2人で大丈夫？",
  ui_story_5035_50351402_45_dialog_content = "やれるだけやってみましょう。",
  ui_story_5035_50351402_46_dialog_content = "そうよ、ここまで来たら、やるしかないわ！",
  ui_story_5035_50351402_47_dialog_content = "速射感知！",
  ui_story_5035_50351402_48_dialog_content = "後方へ引き付けますよ。",
  ui_story_5035_50351402_49_dialog_content = "分かったわ！",
  ui_story_5035_50351402_50_dialog_content = "リリカ、サディ、今のうちだ！",
  ui_story_5035_50351402_51_dialog_content = "行くわよ！",
  ui_story_5035_50351402_52_dialog_content = "ついでに監督、1発殴っていい？",
  ui_story_5035_50351402_53_dialog_content = "ロウソクを消してからね！",
  ui_story_5035_50351402_54_dialog_content = "面白そうね、あたしも混ぜてよ！",
  ui_story_5035_50351402_55_dialog_content = "オバケにはかなわなくても、\n監督にオシオキぐらいできるわ！",
  ui_story_5035_50351402_56_dialog_content = "おい、カメラの前を塞ぐな！",
  ui_story_5035_50351402_57_dialog_content = "後でカメラもろともぶっ壊してやる！",
  ui_story_5035_50351402_58_dialog_content = "ボコボコにされたくなかったら、\n早くロウソクを差し出すことね！",
  ui_story_5035_50351402_59_dialog_content = "こっちは撮影道具じゃないんだよ。\n気にせず続けてくれ。",
  ui_story_5035_50351402_60_dialog_content = "話してる場合じゃないよ！\nミノスとバイスだって、いつまでも時間は稼げない！",
  ui_story_5035_50351402_61_dialog_content = "だったら、あたしの…",
  ui_story_5035_50351402_62_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_5035_50351402_63_dialog_content = "ゲホゲホ…何が起こったの？",
  ui_story_5035_50351402_64_dialog_content = "グア！！！",
  ui_story_5035_50351402_65_dialog_content = "暗鬼！？しかもこんなにたくさん！？",
  ui_story_5035_50351402_66_dialog_content = "しまった、気を取られてたスキに！",
  ui_story_5035_50351402_67_dialog_content = "囲まれてる！",
  ui_story_5035_50351402_68_dialog_content = "君たちが言ったことだろう…\nエスターと暗鬼がよく似てると。",
  ui_story_5035_50351402_69_dialog_content = "今日、この屋敷になぜたくさんの暗鬼が出たのか、\n考えたことはなかったかな？",
  ui_story_5035_50351402_70_dialog_content = "！！！",
  ui_story_5035_50351402_71_dialog_content = "そうだ、上級暗鬼なら…他の暗鬼を操れる！",
  ui_story_5035_50351402_72_dialog_content = "エスターを利用して、\n暗鬼を引き寄せてたんだ！",
  ui_story_5035_50351402_73_dialog_content = "正直、そいつらは美しくないから、\n写ってほしくないんだがね。",
  ui_story_5035_50351402_74_dialog_content = "だが、撮影を順調に進めるためには、\n用心棒が必要ということだ。",
  ui_story_5035_50351402_75_dialog_content = "キャストがワガママを言って騒いだ時、\n撮影を元の軌道に戻してくれるようにね。",
  ui_story_5035_50351402_76_dialog_content = "こんな数の暗鬼…",
  ui_story_5035_50351402_77_dialog_content = "あたしじゃ、たぶん、倒しきれない…",
  ui_story_5035_50351402_78_dialog_content = "きゃああ！！",
  ui_story_5035_50351402_79_dialog_content = "バイス！",
  ui_story_5035_50351402_80_dialog_content = "大変だ、向こうも限界に近づいてる…",
  ui_story_5035_50351402_81_dialog_content = "エスターも倒せず、ロウソクも消せない。\n集まってきた暗鬼も倒せない…",
  ui_story_5035_50351402_82_dialog_content = "このままじゃ本当に…",
  ui_story_5035_50351402_83_dialog_content = "そうそう。そのセリフを待っていたよ。",
  ui_story_5035_50351402_84_dialog_content = "君たちは本当に、絶体絶命なのだ！",
  ui_story_5035_50351402_85_dialog_content = "いい加減に…！",
  ui_story_5035_50351402_86_dialog_content = "PlayerName、逃げましょ！",
  ui_story_5035_50351402_87_dialog_content = "逃げる？",
  ui_story_5035_50351402_88_dialog_content = "そうよ、あたし、逃げるのは得意なの。\n一緒に逃げましょ。",
  ui_story_5035_50351402_89_dialog_content = "この場から逃げ出して、多くの人に真相を伝えれば、\n必ずヨハンを懲らしめてもらえるわ！",
  ui_story_5035_50351402_90_dialog_content = "で…できるかな…？",
  ui_story_5035_50351402_91_dialog_content = "それに、僕たちが逃げたら、他の皆はどうするの？",
  ui_story_5035_50351402_92_dialog_content = "他のみんなは…",
  ui_story_5035_50351402_93_dialog_content = "全員よく聞け！！",
  ui_story_5035_50351402_94_dialog_content = "思いっきり叩きのめせ！\n手加減は一切いらねぇからな！！",
  ui_story_5035_50351402_95_dialog_content = "え？誰！？",
  ui_story_5035_50351402_96_dialog_content = "グアア～！",
  ui_story_5035_50351402_97_dialog_content = "このお化け屋敷の暗鬼役はオレだ！\n横取りは許さねえぜ！！",
  ui_story_5035_50351402_98_dialog_content = "どういうこと？\n暗鬼と暗鬼が戦ってる！？",
  ui_story_5035_50351402_99_dialog_content = "違う、着ぐるみを着たスタッフが混じってるんだ！",
  ui_story_5035_50351402_100_dialog_content = "ガォ～！",
  ui_story_5035_50351402_101_dialog_content = "うるさい、うるさいぞ！",
  ui_story_5035_50351402_102_dialog_content = "いったい、どこから湧いて出た？\n撮影の邪魔だ、出ていけ！",
  ui_story_5035_50351402_103_dialog_content = "今、撮影の真っ最中なんだ、分かっているのか！\n本番中なんだぞ！",
  ui_story_5035_50351402_104_dialog_content = "早く早く早く！\nあいつが気を取られてるうちだってば！",
  ui_story_5035_50351402_105_dialog_content = "聞きましたよね。\nPlayerName、あのロウソクが欲しいそうですよ。",
  ui_story_5035_50351402_106_dialog_content = "分かっとります！",
  ui_story_5035_50351402_107_dialog_content = "何者だ！？",
  ui_story_5035_50351402_108_dialog_content = "取った！うちが取りましたえ！",
  ui_story_5035_50351402_109_dialog_content = "PlayerNameはん、こいつどすな？",
  ui_story_5035_50351402_110_dialog_content = "あっ！ロウソク！",
  ui_story_5035_50351402_111_dialog_content = "何をしている！？ロウソクに触るな！",
  ui_story_5035_50351402_112_dialog_content = "ヘへへ！捕まえてみなさいってば！",
  ui_story_5035_50351402_113_dialog_content = "もう1本！",
  ui_story_5035_50351402_114_dialog_content = "うっとうしいスズメどもめ！\n生かしておかんぞ！",
  ui_story_5035_50351402_115_dialog_content = "ヨハン！あたしたちとのケリがまだついてないよ。",
  ui_story_5035_50351402_116_dialog_content = "サディか？\n今さらエラそうな口をきくなど、こざかしい！",
  ui_story_5035_50351402_117_dialog_content = "だが、ロウソク2本が何になる！\nまだ他にもあるんだ！",
  ui_story_5035_50351402_118_dialog_content = "こっちへ来るんだ、エスター！\nうるさいスズメどもを食らってしまえ！",
  ui_story_5035_50351402_119_dialog_content = "ヒヒ――！",
  ui_story_5035_50351402_120_dialog_content = "他にもロウソク、ねぇ…",
  ui_story_5035_50351402_121_dialog_content = "これのコト？",
  ui_story_5035_50351402_122_dialog_content = "！！！",
  ui_story_5035_50351402_123_dialog_content = "どうしてそれを！？いつ盗んだ！？",
  ui_story_5035_50351402_124_dialog_content = "言ってなかったっけ？\nあたしは義賊だって。",
  ui_story_5035_50351402_125_dialog_content = "エスターがそっちに行ったわ！\n早く、ロウソクを消して！",
  ui_story_5035_50351402_126_dialog_content = "トーゼン。",
  ui_story_5035_50351402_127_dialog_content = "今度はあんたがクランクアップだよ、監督？",
  ui_story_5035_50351402_128_dialog_content = "ふぅっ――",
  ui_story_5035_50351402_129_dialog_content = "ヒ、ヒヒ…ヒヒ…",
  ui_story_5035_50351402_130_dialog_content = "ヒヒヒ――",
  ui_story_5035_50351402_131_dialog_content = "やったわ！動きが鈍くなった！",
  ui_story_5035_50351402_132_dialog_content = "どうやら、私どものねばり勝ちのようでございますね。",
  ui_story_5035_50351402_133_dialog_content = "気は抜けないよ。エスターの力、まだ完全には消えてない…\nどこか別の場所に、まだロウソクを隠してる可能性がある…",
  ui_story_5035_50351402_134_dialog_content = "弱ってる今のうちに、一気に倒しちゃおう！",
  ui_story_5035_50351402_135_dialog_content = "分かったわ！",
  ui_story_5035_50351402_136_dialog_content = "速射感…",
  ui_story_5035_50351402_137_dialog_content = "止めてくれ！！！",
  ui_story_5035_50351402_138_dialog_content = "ダメだ！絶対にダメだ！",
  ui_story_5035_50351402_139_dialog_content = "こんな結末があるか！\nこんなオチの作品、到底受け入れられない！",
  ui_story_5035_50351402_140_dialog_content = "…エスターをかばう気？",
  ui_story_5035_50351402_141_dialog_content = "もう少しで当てちゃうところだったわ。\nエスターのために命を捨てる気…？",
  ui_story_5035_50351402_142_dialog_content = "なんて乱暴なやつらだろう。\nスカートが破れてしまったね…",
  ui_story_5035_50351402_143_dialog_content = "ああ、エスター、私のエスター。\n私の愛しい主演女優…",
  ui_story_5035_50351402_144_dialog_content = "疲れてしまったんだね、分かっているよ。\n火が消えてしまって、寒いだろう？",
  ui_story_5035_50351402_145_dialog_content = "世間なんて、いつもそうだ。\n誰も君に暖かさを分けてやろうとはしない…",
  ui_story_5035_50351402_146_dialog_content = "でも、怖がることはない、エスター。\n君には私がいるじゃないか…",
  ui_story_5035_50351402_147_dialog_content = "私の温度を君にささげるよ…",
  ui_story_5035_50351402_148_dialog_content = "私を食うんだ。\nそして、あいつらと戦う力をもう1度手に入れるんだ。",
  ui_story_5035_50351402_149_dialog_content = "え、エスターに…近寄っていくわ！",
  ui_story_5035_50351402_150_dialog_content = "…正気ではありませんね。",
  ui_story_5035_50351402_151_dialog_content = "止める？",
  ui_story_5035_50351402_152_dialog_content = "止めるって…殺して止める気？",
  ui_story_5035_50351402_153_dialog_content = "リリカ！",
  ui_story_5035_50351402_154_dialog_content = "え、あたし！？",
  ui_story_5035_50351402_155_dialog_content = "カメラを回せ！\nこれから起こることを、カメラに収めるんだ！",
  ui_story_5035_50351402_156_dialog_content = "頼む、撮ってくれ。\n何が何でも撮らなきゃならない…",
  ui_story_5035_50351402_157_dialog_content = "こ、今度は何をしようっていうの…？",
  ui_story_5035_50351402_158_dialog_content = "これから撮る映像を、\n今まで撮ったシーンとつなげるんだ！",
  ui_story_5035_50351402_159_dialog_content = "そうすれば完璧な結末が出来上がる。\n予想もしていなかった、最高の画が！",
  ui_story_5035_50351402_160_dialog_content = "私の最終作で、エスターを最高の芸術にしてやるんだ。\nその主演にふさわしいのは私しかいない…",
  ui_story_5035_50351402_161_dialog_content = "私とエスターの2人が組んでこそ、最高の作品ができるんだ。",
  ui_story_5035_50351402_162_dialog_content = "何を言ってるの！？\n自分まで犠牲にするつもり！？",
  ui_story_5035_50351402_163_dialog_content = "早く、カメラを回せ！！",
  ui_story_5035_50351402_164_dialog_content = "私には分かるんだ！\nエスターから暖かさがなくなっていく…",
  ui_story_5035_50351402_165_dialog_content = "早く、完璧な芸術を創るためだ！\n1カットたりとも逃すんじゃない！",
  ui_story_5035_50351402_166_dialog_content = "バカなこと言わないで。\nこんなの、芸術なんて呼べないわ。",
  ui_story_5035_50351402_167_dialog_content = "何！？",
  ui_story_5035_50351402_168_dialog_content = "誰だ！？",
  ui_story_5035_50351402_169_dialog_content = "芸術って、作る人自身の\n心血と愛がこもったものだと思うの。",
  ui_story_5035_50351402_170_dialog_content = "他人をもてあそんでおいて、\n自分の心血を注いだとは言えないわ。",
  ui_story_5035_50351402_171_dialog_content = "屍（しかばね）に向かって気持ちを吐き出したところで、\n愛情なんて呼べはしないの。",
  ui_story_5035_50351402_172_dialog_content = "ここに芸術と呼べるものなんて、1つもないわ。",
  ui_story_5035_50351402_173_dialog_content = "あるのは、哀れなひとりよがりだけ。",
  ui_story_5035_50351402_174_dialog_content = "ゴルディ！？\nどうしてまだ生きている！？",
  ui_story_5035_50351402_175_dialog_content = "結末を撮影しようと思って。",
  ui_story_5035_50351402_176_dialog_content = "観客が本当に満足するものを撮らせてあげるわ。",
  ui_story_5035_50351402_177_dialog_content = "このロウソク、何か分かるでしょ？\n長いこと燃えてるけど、これってあなたが最初につけたものよね。",
  ui_story_5035_50351402_178_dialog_content = "持ってきてあげたわ。",
  ui_story_5035_50351402_179_dialog_content = "ダメだ！！今は、今ばかりは…！！",
  ui_story_5035_50351402_180_dialog_content = "エスター！急ぐんだ、もう時間がない！",
  ui_story_5035_50351402_181_dialog_content = "もう1度力をふりしぼれ！\nそのアゴで私のノドを貫け！",
  ui_story_5035_50351402_182_dialog_content = "さあ、食らえ！\n今すぐ、この私を食うんだ！",
  ui_story_5035_50351402_183_dialog_content = "急げ！！",
  ui_story_5035_50351402_184_dialog_content = "すばらしい演技だわ、監督。",
  ui_story_5035_50351402_185_dialog_content = "これで「ジ・エンド」ね。",
  ui_story_5035_50351402_186_dialog_content = "ふぅっ――",
  ui_story_5035_50351402_187_dialog_content = "やめろ――！！！",
  ui_story_5035_50351402_188_dialog_content = "エスター！エスター、起きてくれ！",
  ui_story_5035_50351402_189_dialog_content = "私はここにいる！よく聞け、私だ！",
  ui_story_5035_50351402_190_dialog_content = "頼む、答えろ…答えてくれ！",
  ui_story_5035_50351402_191_dialog_content = "あと少しで完成なんだ、エスター！\n私たちの最高傑作が、もう少しで出来上がるんだ！",
  ui_story_5035_50351402_192_dialog_content = "<anim type=Shake><size=50>エスター！エスタ―…！！！</size></anim>",
  ui_story_5035_50351501_1_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5035_50351501_2_dialog_content = "聞いた？屋敷の中から大きな音が…",
  ui_story_5035_50351501_3_dialog_content = "叫び声もしたぞ…\nどう考えても、普通の叫び声じゃない…",
  ui_story_5035_50351501_4_dialog_content = "（気になるわね…ミノスとPlayerNameたち、\n中でいったい何をしているのかしら？）",
  ui_story_5035_50351501_5_dialog_content = "（ああ、ダメよ私！\n私が入ってしまったら、出入り口は誰が見るの？）",
  ui_story_5035_50351501_6_dialog_content = "ここって開業したばかりのお化け屋敷だった？",
  ui_story_5035_50351501_7_dialog_content = "あ！本当だ、看板に書いてある！",
  ui_story_5035_50351501_8_dialog_content = "（あら、思わぬ呼び込み効果があったみたいね…）",
  ui_story_5035_50351501_9_dialog_content = "アンデルセンのゴーストハウスは本日開業でしてよ。\n体験なさってはいかがかしら？",
  ui_story_5035_50351501_10_dialog_content = "ゴーストハウス…\nってことは、さっきのも全部仕掛け？",
  ui_story_5035_50351501_11_dialog_content = "どれどれ、入ってみて、\nつまらなかったら出てくればいいか。",
  ui_story_5035_50351501_12_dialog_content = "お嬢さん、「体験」ってことは無料にしてくれるのかい？",
  ui_story_5035_50351501_13_dialog_content = "それは……",
  ui_story_5035_50351501_14_dialog_content = "お待ちください。\nこれ以上中に人を入れてはいけません。",
  ui_story_5035_50351501_15_dialog_content = "あら？ジェーン。どうして急に…",
  ui_story_5035_50351501_16_dialog_content = "（後ろにあるのは…総合商会の馬車！？）",
  ui_story_5035_50351501_17_dialog_content = "<color=#e8d9bb>ヒヒン――</color>",
  ui_story_5035_50351501_18_dialog_content = "探すのに苦労したぞ。",
  ui_story_5035_50351501_19_dialog_content = "アンデルセン家の扱う不動産としては、\n似つかわしくないな。",
  ui_story_5035_50351501_20_dialog_content = "…イスタバンおじ様！？",
  ui_story_5035_50351501_21_dialog_content = "ごきげんよう、ニナ。",
  ui_story_5035_50351501_22_dialog_content = "かわいそうだが、\n自分の屋敷で何が起こっているのか知らないようだな。",
  ui_story_5035_50351501_23_dialog_content = "あ、開業おめでとう、ニナお嬢様～。",
  ui_story_5035_50351501_24_dialog_content = "（シェオルまで？営業許可書に何か問題でもあったのかしら？）",
  ui_story_5035_50351501_25_dialog_content = "少々お待ちになって。\n責任者を呼んでまいりますわ…",
  ui_story_5035_50351501_26_dialog_content = "ミノスのことかしら？そこにいるじゃない。",
  ui_story_5035_50351501_27_dialog_content = "皆様、ごきげんよう。",
  ui_story_5035_50351501_28_dialog_content = "連れてまいりました。",
  ui_story_5035_50351501_29_dialog_content = "放せ！！",
  ui_story_5035_50351501_30_dialog_content = "みんな私の映画のための犠牲になればいいんだ！！",
  ui_story_5035_50351501_31_dialog_content = "フン！楽しみにしてるといいわ！\nあなたの顔はぜんぶ、変顔に加工しといてあげる！",
  ui_story_5035_50351501_32_dialog_content = "みにくい姿をさらして、\n地位も名誉もズタズタになればいいのよ！",
  ui_story_5035_50351501_33_dialog_content = "そいつが騒ぎの張本人か。",
  ui_story_5035_50351501_34_dialog_content = "左様で、シャドウマスター様。",
  ui_story_5035_50351501_35_dialog_content = "屋敷の仕掛けをめちゃくちゃにされ、\nもう少しでお客様に危害が及ぶところでございました。",
  ui_story_5035_50351501_36_dialog_content = "何を言ってる！？これが私の芸術なんだ！",
  ui_story_5035_50351501_37_dialog_content = "それで、ええと…こいつは監督として、\n今まで暗鬼を操って、映画を撮り続けてきたの！",
  ui_story_5035_50351501_38_dialog_content = "この屋敷で撮影されたこの前の作品では、\n映画の演出だとか言って、スタッフ全員殺されてるのよ！",
  ui_story_5035_50351501_39_dialog_content = "あたしだけ、逃げるのが速かったから助かったの。\nあの時カメラが壊れてなければ、物証もそろってたのに！",
  ui_story_5035_50351501_40_dialog_content = "黙れ！",
  ui_story_5035_50351501_41_dialog_content = "リリカ、蹴られないように気をつけて！",
  ui_story_5035_50351501_42_dialog_content = "<color=#e8d9bb>ガンッ――</color>",
  ui_story_5035_50351501_43_dialog_content = "うっ…！！",
  ui_story_5035_50351501_44_dialog_content = "イヌのしつけには杖が一番だ。",
  ui_story_5035_50351501_45_dialog_content = "連れていけ。\nひとまず軽犯罪者として拘束しておこう。",
  ui_story_5035_50351501_46_dialog_content = "資産はすべて没収とする。",
  ui_story_5035_50351501_47_dialog_content = "了解～。",
  ui_story_5035_50351501_48_dialog_content = "あの、イスタバンさん！",
  ui_story_5035_50351501_49_dialog_content = "あせることはない。",
  ui_story_5035_50351501_50_dialog_content = "影ノ街には明文で凝り固まった秩序など存在しない。\n秩序は時として、悪人をかばうものだからな。",
  ui_story_5035_50351501_51_dialog_content = "お嬢さんの告発については…",
  ui_story_5035_50351501_52_dialog_content = "ジェーン、お前に調査を任せる。",
  ui_story_5035_50351501_53_dialog_content = "早急に調べ上げて、結果を報告してくれ。\n後のことはこちらに任せろ。",
  ui_story_5035_50351501_54_dialog_content = "承知しました。",
  ui_story_5035_50351501_55_dialog_content = "お待ちになって！\n一体どういう事ですの！？",
  ui_story_5035_50351501_56_dialog_content = "YO、YO、ヨハンはもうおしまい…",
  ui_story_5035_50351501_57_dialog_content = "屋敷の主はまだ知らない、\n今日の事件をまだ知らない。",
  ui_story_5035_50351501_58_dialog_content = "ふふふ…真相を知りたければ――",
  ui_story_5035_50351501_59_dialog_content = "もうすぐ発売の『ゴーストハウス』、見てね～！",
  ui_story_5035_50351501_60_dialog_content = "<color=#e8d9bb>数日後、影ノ街「アンデルセンのゴーストハウス」</color>",
  ui_story_5035_50351501_61_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5035_50351501_62_dialog_content = "アリも通れないほど人がいるわ！？",
  ui_story_5035_50351501_63_dialog_content = "列の最後尾が見えない…",
  ui_story_5035_50351501_64_dialog_content = "（ミノスから招待され、\n僕とバイスは再びアンデルセンのゴーストハウスにやってきた）",
  ui_story_5035_50351501_65_dialog_content = "（どうしても事件のお詫びをさせて欲しいって言うから、\n来るには来てみたけど、この様子じゃ…）",
  ui_story_5035_50351501_66_dialog_content = "入れそうにないわ！",
  ui_story_5035_50351501_67_dialog_content = "あれ、PlayerNameもここでサボり？",
  ui_story_5035_50351501_68_dialog_content = "同じこと考えるなんて、気が合うね～。",
  ui_story_5035_50351501_69_dialog_content = "ドーヴ、元気出してよ。\n並んでる時から疲れきっててどうするの？",
  ui_story_5035_50351501_70_dialog_content = "あら？2人とも、おはよう！",
  ui_story_5035_50351501_71_dialog_content = "2人もペアチケット半額が目当てで一緒に来たの？",
  ui_story_5035_50351501_72_dialog_content = "半額？ここのチケットは今、全部事前予約制だよ。\n半額なんてないよ？",
  ui_story_5035_50351501_73_dialog_content = "えっ？",
  ui_story_5035_50351501_74_dialog_content = "知らないの？\nまさか最近影ノ街で話題の『ゴーストハウス』、見てないの！？",
  ui_story_5035_50351501_75_dialog_content = "この「アンデルセンのゴーストハウス」が、\nロケに使われた場所なんだよ。",
  ui_story_5035_50351501_76_dialog_content = "今、超大人気なんだよ。\n見てないと話題についていけないぐらい。",
  ui_story_5035_50351501_77_dialog_content = "ウェンディ、PlayerNameもバイスも出演者だよ…",
  ui_story_5035_50351501_78_dialog_content = "え！？そ、そうだったの！？",
  ui_story_5035_50351501_79_dialog_content = "ウェンディ、見るのをずっとガマンしてるんだ。\n実際にお化け屋敷を体験してから見るって言って。",
  ui_story_5035_50351501_80_dialog_content = "ピープたちがネタばらししようとしたけど、\n全部ウェンディが止めたの。",
  ui_story_5035_50351501_81_dialog_content = "自分の目と耳で体験したかっただけだよ！",
  ui_story_5035_50351501_82_dialog_content = "PlayerName、よかったわね。\nこれならニナさんとミノスさん、売上げに悩むことはなさそうだわ。",
  ui_story_5035_50351501_83_dialog_content = "あれ？見間違いじゃないわよね？",
  ui_story_5035_50351501_84_dialog_content = "やっぱり！とってもステキだわ！",
  ui_story_5035_50351501_85_dialog_content = "次々に襲ってくる困難を乗り越えた仲間と、\n同じ場所で再会できるなんて！",
  ui_story_5035_50351501_86_dialog_content = "あ、最初に言っとくけど、\n演出のためにわざわざセッティングしたわけじゃないわよ！",
  ui_story_5035_50351501_87_dialog_content = "リリカ！君もミノスの招待でここに？",
  ui_story_5035_50351501_88_dialog_content = "シーッ…PlayerName、今カメラ回してるの！\n撮影中よ！",
  ui_story_5035_50351501_89_dialog_content = "スクリーンの前のみんな～！\n『ゴーストハウス・リターンズ』を観てくれてありがとう！",
  ui_story_5035_50351501_90_dialog_content = "主演のサディに、今のロケ現場の様子を案内してもらうわ！",
  ui_story_5035_50351501_91_dialog_content = "YO、YO、「サディ・666」、依頼はマジメにやり遂げる…",
  ui_story_5035_50351501_92_dialog_content = "サディ！主役になったんだね！おめでとう。",
  ui_story_5035_50351501_93_dialog_content = "あたしはただ、\n本物の義賊になるために努力してるだけだよ。",
  ui_story_5035_50351501_94_dialog_content = "え？映画の仕事も本気でやるようになったってこと？",
  ui_story_5035_50351501_95_dialog_content = "あたし、わかったんだ。",
  ui_story_5035_50351501_96_dialog_content = "弱い人を助けるとか、正義を貫くとか、他人に頼らず生きるとか、\nそういう行動こそがカッコいい義賊の生き方なんだって。",
  ui_story_5035_50351501_97_dialog_content = "だから、義賊って名前とか身分にこだわるのはやめたんだ。",
  ui_story_5035_50351501_98_dialog_content = "すごいわ、サディ。若いのに立派ね！",
  ui_story_5035_50351501_99_dialog_content = "そ、そんなことないよ。",
  ui_story_5035_50351501_100_dialog_content = "カット！いいわ！とってもいい感じ！",
  ui_story_5035_50351501_101_dialog_content = "皆様おそろいのようですね。",
  ui_story_5035_50351501_102_dialog_content = "前回は十分なおもてなしができず申しわけございませんでした。\nどうか埋め合わせをさせてくださいませ。",
  ui_story_5035_50351501_103_dialog_content = "皆様、改良後のゴーストハウスをぜひ体験なさって。\n後ほど我が家でのお食事も用意しておりましてよ！",
  ui_story_5035_50351501_104_dialog_content = "ミノスとメイドのサナエが、\n腕によりをかけた逸品をごちそういたしますわ。",
  ui_story_5035_50351501_105_dialog_content = "お嬢様の期待を裏切らないよう努力いたします。",
  ui_story_5035_50351501_106_dialog_content = "仲直りできたんだね。",
  ui_story_5035_50351501_107_dialog_content = "そういうことになるかしら。\nミノスとの誤解は解けたわ。",
  ui_story_5035_50351501_108_dialog_content = "この度はリリカ様の映像に助けられました。\n私自身でいくら説明しようと伝わらなかったでしょうから。",
  ui_story_5035_50351501_109_dialog_content = "フフフ、だったら、次回作もぜひ応援してね～！",
  ui_story_5035_50351501_110_dialog_content = "あたし、なんとなく感じたの。\n女優より監督の才能があるんじゃないかって！",
  ui_story_5035_50351501_111_dialog_content = "そうなんだ？\nじゃあ、監督に転職するつもり？",
  ui_story_5035_50351501_112_dialog_content = "まだ考え中よ！それに、監督だって簡単じゃないわ。\n何から始めればいいのか…",
  ui_story_5035_50351501_113_dialog_content = "あら、奇遇ね。皆で集まってたの？",
  ui_story_5035_50351501_114_dialog_content = "今日はラッキーデーかしら。",
  ui_story_5035_50351501_115_dialog_content = "あ！ゴルディ、久しぶり！",
  ui_story_5035_50351501_116_dialog_content = "最近どうしてんの？新しい撮影とかやってる？",
  ui_story_5035_50351501_117_dialog_content = "ああ、最近はね…映画に出るのは、もうやめようかと思って。\nそれで今は…",
  ui_story_5035_50351501_118_dialog_content = "ん？ええっと…",
  ui_story_5035_50351501_119_dialog_content = "（どこかで会ったわよね…！？）",
  ui_story_5035_50351501_120_dialog_content = "あ、そうだ！あなたは！！",
  ui_story_5035_50351501_121_dialog_content = "ゴルディね！！",
  ui_story_5035_50351501_122_dialog_content = "ゴルディ！？聞いた？",
  ui_story_5035_50351501_123_dialog_content = "本当か？あのゴルディが来てるのか！？",
  ui_story_5035_50351501_124_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5035_50351501_125_dialog_content = "うわ！お客さんが騒ぎだしたよ！",
  ui_story_5035_50351501_126_dialog_content = "ゴルディさん！こちらです、こちらにお願いします！\nいくつか質問させてください！",
  ui_story_5035_50351501_127_dialog_content = "はじめまして！\n『デイリー・スクープ速報版』の見習い記者、ブランディです。",
  ui_story_5035_50351501_128_dialog_content = "多くの人が関心を持っていることなのですが、\n『ゴーストハウス』で危険な目に遭うシーン、あれも本物なんですか？",
  ui_story_5035_50351501_129_dialog_content = "ええ、その件はすでに報道されている通り…",
  ui_story_5035_50351501_130_dialog_content = "あの時、確かにヨハン監督に殺されそうになったわ。",
  ui_story_5035_50351501_131_dialog_content = "では、ゴルディさんはどうやって生き延びたんでしょう？",
  ui_story_5035_50351501_132_dialog_content = "それは、言ってもなかなか信じてもらえないでしょうけど、\nあの時私は――",
  ui_story_5035_50351501_133_dialog_content = "<color=#FFB400>何もしてないの</color>。",
  ui_story_5035_50351501_134_dialog_content = "足下の床板が突然外れたと思ったら…\n上から板やがれきが落ちてきて、本当に驚いたわ。",
  ui_story_5035_50351501_135_dialog_content = "でも、落ちてきた物が大きすぎたみたいで、\n私には当たらなかったの。",
  ui_story_5035_50351501_136_dialog_content = "大きな石の柱が壁に引っかかって、板もそこに引っかかったから、\nちょうど屋根みたいに石が降りかかるのを防いでくれたわ。",
  ui_story_5035_50351501_137_dialog_content = "ちょうど1人分ぐらいの高さがある感じで。",
  ui_story_5035_50351501_138_dialog_content = "はあ…？",
  ui_story_5035_50351501_139_dialog_content = "それから、少しずつ板や落下物をどけていったのが、\n積み木遊びみたいで楽しかったわ！",
  ui_story_5035_50351501_140_dialog_content = "脱出した後は声をたよりに、\n皆のいる所を目指したの。",
  ui_story_5035_50351501_141_dialog_content = "途中で明かりに使えると思って、\n監督が残していったロウソクを拾っていったら…",
  ui_story_5035_50351501_142_dialog_content = "後のことは映画に写っていた通りよ。",
  ui_story_5035_50351501_143_dialog_content = "他に質問は？",
  ui_story_5035_50351501_144_dialog_content = "そ、そんなことだったんですか！？",
  ui_story_5035_50351501_145_dialog_content = "すでに「幸運」の域を超えていますね。\nまさに奇跡です！",
  ui_story_5035_50351501_146_dialog_content = "そうかもね。\nでも、奇跡って、毎日起こってることなのよ。",
  ui_story_5035_50351501_147_dialog_content = "私たちが生まれてきたことだって、奇跡だもの！",
  ui_story_5035_50351501_148_dialog_content = "これが人気歌手のオーラというものでしょうか…",
  ui_story_5035_50351501_149_dialog_content = "ふぅ…や、やっと人の波を抜けられたわ！",
  ui_story_5035_50351501_150_dialog_content = "ゴルディ、無事で本当によかったわ！！",
  ui_story_5035_50351501_151_dialog_content = "あたし、決めたの。\n今度の作品はあなたから撮り始めるわ！",
  ui_story_5035_50351501_152_dialog_content = "おや、出演者の皆様がおそろいですか？\nでしたら、ぜひ取材にご協力お願いします！",
  ui_story_5035_50351501_153_dialog_content = "『ゴーストハウス』が上映されてから、\nある話題に高い関心が集まり、今だに熱気冷めやらないのですが――",
  ui_story_5035_50351501_154_dialog_content = "棺からはい出してきた「エスター夫人」は、\n本物の悪霊なのですか？",
  ui_story_5035_50351501_155_dialog_content = "ええと、それは正確に言うと…",
  ui_story_5035_50351501_156_dialog_content = "中に入って、自分で見てみるといいよ。",
  ui_story_5035_50351501_157_dialog_content = "はい？",
  ui_story_5035_50351501_158_dialog_content = "自分の目で確かめた方が、\n納得できる答えが得られるでしょ。",
  ui_story_5035_50351501_159_dialog_content = "そう言われてしまっては、\nチケットを買わずにはいられませんね！",
  ui_story_5035_50351501_160_dialog_content = "体験が終わったら、\n改めて皆さんに取材アポをとらせていただきますね！",
  ui_story_5035_50351501_161_dialog_content = "サディ様、ゴーストハウスを\n宣伝していただき、ありがとうございます。",
  ui_story_5035_50351501_162_dialog_content = "…ただ、思ったことを言っただけだよ。",
  ui_story_5035_50351501_163_dialog_content = "サディの言う通りね。",
  ui_story_5035_50351501_164_dialog_content = "上級暗鬼は倒してしまったし、\nその影響で起こっていた異常な現象も二度と起こることはない…",
  ui_story_5035_50351501_165_dialog_content = "でも、観客には幻を生きたままにしておくのも、\n悪い事じゃないかもしれないわ。",
  ui_story_5035_50351501_166_dialog_content = "「本物の心霊現象」なんて存在しないかもしれない…",
  ui_story_5035_50351501_167_dialog_content = "でも、私たちのまだ見ぬどこかに、新しい発見が待ってるのかもしれない。\nPlayerNameも言ってたわ！",
  ui_story_5035_50351501_168_dialog_content = "そんな風に思ってもらってるなら、嬉しいよ。",
  ui_story_5035_50351501_169_dialog_content = "フフフ、もちろんお客さんたちの\n幻想を壊すわけにはいかないわ！",
  ui_story_5035_50351501_170_dialog_content = "だって『ゴーストハウス・リターンズ』が\n今まさに準備中なんだもの！",
  ui_story_5035_50351501_171_dialog_content = "『ゴーストハウス・リターンズ』！？",
  ui_story_5035_50351501_172_dialog_content = "あっ！つけヒゲ探偵のリリカだ！\n俺、大ファンなんだ！",
  ui_story_5035_50351501_173_dialog_content = "何！リリカだって？\n――ああ、本当にリリカだ！",
  ui_story_5035_50351501_174_dialog_content = "え！？待って待って、みんな…1人ずつでお願い！",
  ui_story_5035_50351501_175_dialog_content = "いやー、予想外だね。\nたった一晩のうちにリリカの人気がこんなに出るなんて。",
  ui_story_5035_50351501_176_dialog_content = "願ってた通り、誰もが知ってる大スターになれたみたいね！",
  ui_story_5035_50351501_177_dialog_content = "やった！ゴルディとリリカのサイン、\n両方にサインしてもらったわ！",
  ui_story_5035_50351501_178_dialog_content = "おい待て、あそこにいるのって、\n『ゴーストハウス』の出演者たちじゃないか？",
  ui_story_5035_50351501_179_dialog_content = "あ！本当だわ！",
  ui_story_5035_50351501_180_dialog_content = "細目で白髪の紳士に、太いシッポの美少女と\nキャップを被った女の子…それからモヤシ！",
  ui_story_5035_50351501_181_dialog_content = "（どうして僕だけそんな扱いなの！？）",
  ui_story_5035_50351501_182_dialog_content = "ええ？どうしよう！\n私、スターになる心の準備なんて出来てないわ！",
  ui_story_5035_50351501_183_dialog_content = "こ、こっちに来るよ！！",
  ui_story_5035_50351501_184_dialog_content = "もみくちゃにされる前に逃げるよ！\n急いで！！",
  ui_story_5035_50351501_185_dialog_content = "こっちよ！道があるわ！",
  ui_story_5035_50351501_186_dialog_content = "あ、みんな、ちゃんとカメラの方を向いて！",
  ui_story_5035_50351501_187_dialog_content = "まだ――",
  ui_story_5035_50351501_188_dialog_content = "撮影は終わってないの！",
  ui_story_5035_50351501_189_dialog_content = "ふふ…すぐには収まりそうにないわね。",
  ui_story_5035_50351501_190_dialog_content = "私もそろそろ戻らないと。",
  ui_story_5035_50351501_191_dialog_content = "今日はお客様が多いようだし、\n突発的な問題に備える必要が…",
  ui_story_5035_50351501_192_dialog_content = "きゃあ！ゴキブリ！",
  ui_story_5035_50351501_193_dialog_content = "スタッフはどこ！？\nクレームをつけないと！",
  ui_story_5035_50351501_194_dialog_content = "今まいりますわ！",
  ui_story_5035_50351501_195_dialog_content = "このトイレ、ずっと人が入ったままなんだ。\n他にトイレはないの？",
  ui_story_5035_50351501_196_dialog_content = "ございませんわ。\n別のお手洗いはずいぶん遠くにありましてよ。",
  ui_story_5035_50351501_197_dialog_content = "少々お待ちになって。\n他にも呼ばれておりますの。",
  ui_story_5035_50351501_198_dialog_content = "まったく…",
  ui_story_5035_50351501_199_dialog_content = "おい、まだか！？\n怖くてちびったのか？",
  ui_story_5035_50351501_200_dialog_content = "もともとトイレが少ないってのに…\n急いでくれよ！",
  ui_story_5035_50351501_201_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5035_50351501_202_dialog_content = "どうしたんだ？おい！",
  ui_story_5035_50351501_203_dialog_content = "おかしいな…音がまったくしない…",
  ui_story_5035_50351501_204_dialog_content = "おい、中に誰もいないのか？",
  ui_story_5035_50351501_205_dialog_content = "<color=#e8d9bb>ピチャン…ポタッ…</color>"
}
return config
